from pathlib import Path
import subprocess
import hashlib
import json
import sys

PROJECT_ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
REPO_DIR = Path("/content/FastSpeech2_reference")
REPO_URL = "https://github.com/ming024/FastSpeech2.git"
RECORDS_DIR = PROJECT_ROOT / "reproducibility"
RECORDS_DIR.mkdir(parents=True, exist_ok=True)

def run_command(arguments):
    result = subprocess.run(
        arguments,
        capture_output=True,
        text=True,
        check=True,
    )
    return result.stdout.strip()

# Reuse an existing checkout only if it is the expected repository.
if not REPO_DIR.exists():
    print("Downloading the public reference repository...")
    print(run_command([
        "git", "clone", REPO_URL, str(REPO_DIR)
    ]))
else:
    if not (REPO_DIR / ".git").is_dir():
        raise RuntimeError(
            f"{REPO_DIR} exists but is not a Git checkout. "
            "Stop and share this error."
        )

    origin = run_command([
        "git", "-C", str(REPO_DIR), "remote", "get-url", "origin"
    ])

    if origin.rstrip("/") != REPO_URL:
        raise RuntimeError(f"Unexpected repository origin: {origin}")

    print("Reusing the existing reference checkout.")

# Do not silently proceed with modified source files.
changes = run_command([
    "git", "-C", str(REPO_DIR), "status", "--porcelain"
])
if changes:
    raise RuntimeError(
        "The reference checkout has changes. Stop and share:\n" + changes
    )

commit = run_command([
    "git", "-C", str(REPO_DIR), "rev-parse", "HEAD"
])

# Persist the exact upstream source, including its LICENSE.
archive_path = RECORDS_DIR / f"FastSpeech2_upstream_{commit[:12]}.tar.gz"

if not archive_path.exists():
    run_command([
        "git", "-C", str(REPO_DIR),
        "archive", "--format=tar.gz",
        "--prefix=FastSpeech2/",
        f"--output={archive_path}",
        commit,
    ])

archive_sha256 = hashlib.sha256(archive_path.read_bytes()).hexdigest()

record = {
    "repository_url": REPO_URL,
    "commit": commit,
    "source_archive": archive_path.name,
    "source_archive_sha256": archive_sha256,
    "python_version": sys.version,
}

record_path = RECORDS_DIR / "upstream_reference.json"
record_path.write_text(
    json.dumps(record, indent=2),
    encoding="utf-8",
)

print("\n=== SOURCE RECORD ===")
print(json.dumps(record, indent=2))

# Read files as text; do not import or execute repository code.
inspection_files = [
    "requirements.txt",
    "config/LJSpeech/preprocess.yaml",
    "config/LJSpeech/model.yaml",
    "config/LJSpeech/train.yaml",
    "config/LibriTTS/model.yaml",
    "config/README.md",
]

for relative_path in inspection_files:
    path = REPO_DIR / relative_path
    print(f"\n=== {relative_path} ===")

    if not path.is_file():
        raise FileNotFoundError(
            f"Expected reference file is missing: {relative_path}"
        )

    print(path.read_text(encoding="utf-8"))

print("\nInspection finished. No packages installed.")
print("Source archive and commit record saved in:", RECORDS_DIR)

from pathlib import Path
from importlib import metadata
import re

REPO_DIR = Path("/content/FastSpeech2_reference")

if not (REPO_DIR / ".git").is_dir():
    raise RuntimeError(
        "Reference repository is missing. "
        "Share this output before continuing."
    )

print("=== INSTALLED PACKAGE VERSIONS ===")

packages = [
    "torch", "numpy", "scipy", "librosa", "numba",
    "matplotlib", "soundfile", "scikit-learn",
    "PyYAML", "pyworld", "tgt", "g2p-en",
    "inflect", "Unidecode", "pypinyin",
    "tensorboard", "tqdm", "datasets", "huggingface-hub",
]

for package in packages:
    try:
        version = metadata.version(package)
    except metadata.PackageNotFoundError:
        version = "NOT INSTALLED"
    print(f"{package}: {version}")

print("\n=== COMPATIBILITY-SENSITIVE SOURCE LINES ===")

# These patterns identify code to review, not confirmed errors.
patterns = [
    r"\bnp\.(?:int|float|complex|bool|object|str)\b",
    r"librosa\.(?:load|stft)",
    r"librosa\.filters\.mel",
    r"torch\.load",
    r"torch\.stft",
    r"get_window",
    r"weight_norm",
]

matcher = re.compile("|".join(patterns))
matches = []

for path in sorted(REPO_DIR.rglob("*.py")):
    if ".git" in path.parts:
        continue

    lines = path.read_text(encoding="utf-8").splitlines()

    for number, line in enumerate(lines, start=1):
        if matcher.search(line):
            matches.append(
                f"{path.relative_to(REPO_DIR)}:{number}: "
                f"{line.strip()}"
            )

if matches:
    print("\n".join(matches))
else:
    print("No matches for these review patterns.")

print("\n=== VOCODER LOADER ===")

loader_path = REPO_DIR / "utils/model.py"
if not loader_path.is_file():
    raise FileNotFoundError(f"Missing: {loader_path}")

source = loader_path.read_text(encoding="utf-8")
start = source.find("def get_vocoder(")

if start < 0:
    raise RuntimeError("Could not locate get_vocoder().")

# Print the loader function up to the next top-level function.
following_source = source[start + 1:]
next_function = re.search(r"\ndef ", following_source)

end = (
    start + 1 + next_function.start()
    if next_function
    else len(source)
)

print(source[start:end])

print("\nInspection complete. Nothing installed or modified.")

