from pathlib import Path
import inspect
import subprocess
import sys
import librosa

REPO_DIR = Path("/content/FastSpeech2_reference")
PROJECT_ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS_DIR = PROJECT_ROOT / "reproducibility"
MODIFIED_DIR = PROJECT_ROOT / "upstream_modified"

# Verify that the intended calls match the installed API
# before modifying any files.
inspect.signature(librosa.util.pad_center).bind(
    [0.0], size=1024
)
inspect.signature(librosa.filters.mel).bind(
    sr=22050,
    n_fft=1024,
    n_mels=80,
    fmin=0,
    fmax=8000,
)

replacements = {
    "audio/stft.py": [
        (
            "pad_center(fft_window, filter_length)",
            "pad_center(fft_window, size=filter_length)",
        ),
        (
            "sampling_rate, filter_length, n_mel_channels, mel_fmin, mel_fmax",
            "sr=sampling_rate, n_fft=filter_length, "
            "n_mels=n_mel_channels, fmin=mel_fmin, fmax=mel_fmax",
        ),
    ],
    "audio/audio_processing.py": [
        (
            "librosa_util.pad_center(win_sq, n_fft)",
            "librosa_util.pad_center(win_sq, size=n_fft)",
        ),
    ],
}

# Validate every replacement before writing anything.
updated_sources = {}

for relative_path, edits in replacements.items():
    path = REPO_DIR / relative_path
    source = path.read_text(encoding="utf-8")

    for old, new in edits:
        if source.count(old) == 1:
            source = source.replace(old, new, 1)
        elif old not in source and source.count(new) == 1:
            pass  # This exact patch was already applied.
        else:
            raise RuntimeError(
                f"Unexpected source in {relative_path}. "
                "Stop and share this error."
            )

    compile(source, str(path), "exec")
    updated_sources[relative_path] = source

for relative_path, source in updated_sources.items():
    (REPO_DIR / relative_path).write_text(source, encoding="utf-8")

    saved_path = MODIFIED_DIR / relative_path
    saved_path.parent.mkdir(parents=True, exist_ok=True)
    saved_path.write_text(source, encoding="utf-8")
    print("Patched/saved:", relative_path)

RECORDS_DIR.mkdir(parents=True, exist_ok=True)

diff = subprocess.run(
    ["git", "-C", str(REPO_DIR), "diff", "--", *replacements],
    capture_output=True,
    text=True,
    check=True,
).stdout

(RECORDS_DIR / "librosa_keyword_compatibility.patch").write_text(
    diff, encoding="utf-8"
)

# A fresh process ensures the patched modules are loaded.
test_code = r'''
import numpy as np
import yaml
from audio.stft import TacotronSTFT
from audio.tools import get_mel_from_wav

with open("config/LJSpeech/preprocess.yaml", encoding="utf-8") as f:
    config = yaml.safe_load(f)["preprocessing"]

print("Constructing upstream STFT; this may take a little time.", flush=True)

stft = TacotronSTFT(
    filter_length=config["stft"]["filter_length"],
    hop_length=config["stft"]["hop_length"],
    win_length=config["stft"]["win_length"],
    n_mel_channels=config["mel"]["n_mel_channels"],
    sampling_rate=config["audio"]["sampling_rate"],
    mel_fmin=config["mel"]["mel_fmin"],
    mel_fmax=config["mel"]["mel_fmax"],
)

sr = config["audio"]["sampling_rate"]
time = np.arange(sr, dtype=np.float64) / sr
waveform = (0.2 * np.sin(2 * np.pi * 220 * time)).astype(np.float32)

mel, energy = get_mel_from_wav(waveform, stft)

assert mel.ndim == 2 and mel.shape[0] == 80
assert energy.ndim == 1 and energy.shape[0] == mel.shape[1]
assert np.isfinite(mel).all()
assert np.isfinite(energy).all()
assert np.all(energy >= 0)
assert np.max(energy) > 0

print("Mel shape:", mel.shape, flush=True)
print("Energy shape:", energy.shape, flush=True)
print("Mel range:", float(mel.min()), float(mel.max()), flush=True)
print("Acoustic extraction smoke test: PASSED", flush=True)
'''

log_path = RECORDS_DIR / "acoustic_smoke_test.log"

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        [sys.executable, "-u", "-c", test_code],
        cwd=REPO_DIR,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="")
        log.write(line)
        log.flush()

    exit_code = process.wait()

print("\nExit code:", exit_code)
print("Log saved:", log_path)

if exit_code != 0:
    print("FAILED: Share the complete traceback before continuing.")
else:
    print("PASSED: Synthetic mel/energy extraction works.")

from getpass import getpass
from pathlib import Path
import json

from huggingface_hub import HfApi, get_hf_file_metadata, hf_hub_url

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

dataset_id = "ai4bharat/Svarah"
access_record = None

# Hidden input: do not put the token directly into the code.
hf_token = getpass("Enter your Hugging Face read token (hidden): ").strip()

try:
    if not hf_token:
        raise ValueError("No token entered.")

    api = HfApi(token=hf_token)
    info = api.dataset_info(dataset_id, files_metadata=False)

    revision = info.sha
    files = sorted(
        item.rfilename for item in (info.siblings or [])
    )

    # Select an actual data file, rather than the public README.
    data_files = [
        name for name in files
        if name.lower().endswith((".parquet", ".arrow", ".tar.gz", ".zip"))
    ]

    if not data_files:
        print("Repository files:")
        for name in files[:40]:
            print(name)
        raise RuntimeError(
            "No recognized data file found. Share this output."
        )

    probe_file = data_files[0]

    # Metadata request only: verifies access without downloading audio.
    file_info = get_hf_file_metadata(
        hf_hub_url(
            repo_id=dataset_id,
            filename=probe_file,
            repo_type="dataset",
            revision=revision,
        ),
        token=hf_token,
    )

    access_record = {
        "dataset": dataset_id,
        "revision": revision,
        "access_check": "PASSED",
        "checked_file": probe_file,
        "checked_file_size_bytes": file_info.size,
        "repository_file_count": len(files),
    }

    print("\nDataset:", dataset_id)
    print("Revision:", revision)
    print("Checked file:", probe_file)
    print("File size (bytes):", file_info.size)
    print("Dataset file access: PASSED")
    print("Audio dataset downloaded: NO")

except Exception as error:
    # Avoid printing request headers, URLs, or credentials.
    print("\nDataset access check: FAILED")
    print("Error type:", type(error).__name__)

    response = getattr(error, "response", None)
    if response is not None:
        print("HTTP status:", response.status_code)

    print(
        "Check that access conditions are accepted and your token "
        "has read access to this dataset. Do not share the token."
    )

finally:
    hf_token = None
    api = None

if access_record is not None:
    RECORDS_DIR.mkdir(parents=True, exist_ok=True)
    record_path = RECORDS_DIR / "svarah_access_check.json"
    record_path.write_text(
        json.dumps(access_record, indent=2),
        encoding="utf-8",
    )
    print("Access record saved:", record_path)

