from pathlib import Path
from collections import defaultdict
import json
import math
import re

import pyarrow.parquet as pq

records_dir = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

metadata_path = records_dir / "svarah_original_metadata.parquet"
rows = pq.read_table(metadata_path).to_pylist()

pattern = re.compile(
    r"^(?P<recording>\d+)_(?P<candidate>[fm]\d+)_chunk_(?P<chunk>\d+)\.wav$"
)

# These fields check consistency, not unique identity.
profile_fields = [
    "gender", "age-group", "primary_language",
    "native_place_state", "native_place_district",
    "highest_qualification", "job_category", "occupation_domain",
]

groups = defaultdict(
    lambda: {"clips": 0, "seconds": 0.0, "profiles": set(),
             "recordings": set()}
)

unmatched = []
invalid_duration_count = 0
empty_text_count = 0
total_seconds = 0.0

for row in rows:
    path = str(row["audio_filepath"]).replace("\\", "/")
    filename = path.rsplit("/", 1)[-1]
    match = pattern.fullmatch(filename)

    duration = row["duration"]
    valid_duration = (
        isinstance(duration, (int, float))
        and math.isfinite(duration)
        and duration > 0
    )

    if valid_duration:
        total_seconds += duration
    else:
        invalid_duration_count += 1

    if not str(row.get("text") or "").strip():
        empty_text_count += 1

    if match is None:
        unmatched.append(filename)
        continue

    group = groups[match["candidate"]]
    group["clips"] += 1
    group["seconds"] += duration if valid_duration else 0.0
    group["recordings"].add(match["recording"])
    group["profiles"].add(
        tuple(row.get(field) for field in profile_fields)
    )

conflicts = sorted(
    key for key, value in groups.items()
    if len(value["profiles"]) > 1
)

summary = {
    "metadata_rows": len(rows),
    "reported_duration_hours": total_seconds / 3600,
    "invalid_duration_count": invalid_duration_count,
    "empty_transcript_count": empty_text_count,
    "unmatched_filename_count": len(unmatched),
    "candidate_group_count": len(groups),
    "candidate_groups_with_multiple_profiles": conflicts,
    "candidate_ids_are_verified_speakers": False,
}

print("=== METADATA AUDIT ===")
print(json.dumps(summary, indent=2))

print("\n=== FIRST 12 CANDIDATE GROUPS ===")
for key in sorted(groups)[:12]:
    value = groups[key]
    print(
        f"{key}: clips={value['clips']}, "
        f"minutes={value['seconds'] / 60:.2f}, "
        f"recordings={len(value['recordings'])}, "
        f"distinct_profiles={len(value['profiles'])}"
    )

if unmatched:
    print("\nUnmatched filename examples:", unmatched[:10])

output_path = records_dir / "svarah_candidate_group_audit.json"
output_path.write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\nAudit saved:", output_path)
print("No speaker mapping or train/validation split created.")

from pathlib import Path
from collections import defaultdict
import json
import re

import pyarrow.parquet as pq

records_dir = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)
rows = pq.read_table(
    records_dir / "svarah_original_metadata.parquet"
).to_pylist()

pattern = re.compile(
    r"^(?P<prefix>\d+)_(?P<file_id>[fm]\d+)_chunk_(?P<chunk>\d+)\.wav$"
)

profile_fields = [
    "gender", "age-group", "primary_language",
    "native_place_state", "native_place_district",
    "highest_qualification", "job_category", "occupation_domain",
]

groups = defaultdict(
    lambda: {
        "clips": 0,
        "seconds": 0.0,
        "file_ids": set(),
        "profiles": set(),
    }
)

for row in rows:
    filename = str(row["audio_filepath"]).replace("\\", "/").rsplit("/", 1)[-1]
    match = pattern.fullmatch(filename)

    if match is None:
        raise ValueError(f"Unexpected filename: {filename}")

    group = groups[match["prefix"]]
    group["clips"] += 1
    group["seconds"] += float(row["duration"])
    group["file_ids"].add(match["file_id"])
    group["profiles"].add(
        tuple(row.get(field) for field in profile_fields)
    )

conflicts = sorted(
    prefix for prefix, group in groups.items()
    if len(group["profiles"]) > 1
)

summary = {
    "metadata_rows": len(rows),
    "leading_numeric_group_count": len(groups),
    "groups_with_multiple_demographic_profiles": conflicts,
    "minimum_group_minutes": min(
        group["seconds"] for group in groups.values()
    ) / 60,
    "maximum_group_minutes": max(
        group["seconds"] for group in groups.values()
    ) / 60,
    "speaker_identity_verified": False,
}

print("=== LEADING IDENTIFIER AUDIT ===")
print(json.dumps(summary, indent=2))

print("\n=== FIRST 12 GROUPS ===")
for prefix in sorted(groups)[:12]:
    group = groups[prefix]
    print(
        f"{prefix}: clips={group['clips']}, "
        f"minutes={group['seconds'] / 60:.2f}, "
        f"file_ids={len(group['file_ids'])}, "
        f"profiles={len(group['profiles'])}"
    )

output_path = records_dir / "svarah_numeric_prefix_audit.json"
output_path.write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\nSaved:", output_path)
print("No speaker labels or data splits assigned.")

