inventory = json.loads(
    (RECORDS_DIR / "svarah_repository_files.json").read_text(
        encoding="utf-8"
    )
)

shards = sorted(
    [
        item for item in inventory
        if item["filename"].endswith(".parquet")
    ],
    key=lambda item: item["filename"],
)

if len(shards) != 3:
    raise RuntimeError(
        f"Expected 3 pinned audio shards; found {len(shards)}."
    )

DATASET_DIR = BASE_DIR / "datasets/Svarah" / access["revision"]
DATASET_DIR.mkdir(parents=True, exist_ok=True)

print(
    "Expected download size (GB):",
    round(sum(item["size_bytes"] for item in shards) / 1e9, 3),
)
print("Destination:", DATASET_DIR)

token = getpass("Hugging Face read token (hidden): ").strip()
if not token:
    raise ValueError("No token entered.")

saved_files = []

try:
    for index, item in enumerate(shards, start=1):
        print(f"\nShard {index}/{len(shards)}: {item['filename']}")

        path = Path(hf_hub_download(
            repo_id=access["dataset"],
            repo_type="dataset",
            revision=access["revision"],
            filename=item["filename"],
            local_dir=str(DATASET_DIR),
            token=token,
        ))

        actual_size = path.stat().st_size
        if actual_size != item["size_bytes"]:
            raise RuntimeError(
                f"Size mismatch for {item['filename']}: "
                f"expected {item['size_bytes']}, got {actual_size}"
            )

        saved_files.append({
            "filename": item["filename"],
            "local_path": str(path),
            "size_bytes": actual_size,
        })
        print("File size check: PASSED")

finally:
    token = None

record = {
    "dataset": access["dataset"],
    "revision": access["revision"],
    "dataset_directory": str(DATASET_DIR),
    "files": saved_files,
    "speaker_mapping_status": "unresolved",
}

record_path = RECORDS_DIR / "svarah_local_shards.json"
record_path.write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("\nAll three shards saved: PASSED")
print("Download record:", record_path)
print("Audio integrity and usable duration still need checking.")
print("No split, resampling, alignment, or training performed.")

from pathlib import Path
from collections import Counter
import hashlib
import io
import json
import math

import numpy as np
import pyarrow.parquet as pq
import soundfile as sf
from tqdm.auto import tqdm

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

download_record = json.loads(
    (RECORDS_DIR / "svarah_local_shards.json").read_text(
        encoding="utf-8"
    )
)

audit = []
sample_rates = Counter()
channel_counts = Counter()
seen_audio = {}
seen_paths = set()
duplicate_audio_count = 0
duplicate_path_count = 0

for shard in download_record["files"]:
    shard_path = Path(shard["local_path"])
    parquet = pq.ParquetFile(shard_path)

    print(f"\nChecking {shard_path.name}")

    with tqdm(total=parquet.metadata.num_rows, unit="clip") as progress:
        for batch in parquet.iter_batches(batch_size=32):
            for row in batch.to_pylist():
                index = len(audit)
                audio = row["audio_filepath"]
                record = {
                    "index": index,
                    "shard": shard["filename"],
                    "original_path": audio.get("path"),
                    "text": row["text"],
                    "reported_duration_seconds": row["duration"],
                    "issues": [],
                }

                try:
                    encoded = audio.get("bytes")
                    if encoded is None:
                        raise ValueError("Embedded audio bytes are missing.")

                    with io.BytesIO(encoded) as buffer:
                        waveform, sr = sf.read(
                            buffer,
                            dtype="float32",
                            always_2d=True,
                        )

                    frames, channels = waveform.shape
                    duration = frames / sr
                    sample_rates[sr] += 1
                    channel_counts[channels] += 1

                    if frames == 0:
                        raise ValueError("Audio contains zero frames.")

                    if not np.isfinite(waveform).all():
                        raise ValueError("Audio contains non-finite samples.")

                    peak = float(np.max(np.abs(waveform)))
                    rms = float(np.sqrt(
                        np.mean(waveform.astype(np.float64) ** 2)
                    ))

                    reported = float(row["duration"])

                    if not math.isfinite(reported) or reported <= 0:
                        record["issues"].append("invalid_reported_duration")
                    elif abs(duration - reported) > max(0.02, 1 / sr):
                        record["issues"].append("duration_mismatch")

                    if peak == 0:
                        record["issues"].append("silent_audio")

                    if not str(row["text"] or "").strip():
                        record["issues"].append("empty_transcript")

                    # Canonical sample bytes, including rate and channels.
                    digest = hashlib.sha256()
                    digest.update(f"{sr}:{channels}:".encode("ascii"))
                    digest.update(
                        np.ascontiguousarray(
                            waveform, dtype="<f4"
                        ).tobytes()
                    )
                    audio_hash = digest.hexdigest()

                    duplicate_of = seen_audio.get(audio_hash)
                    if duplicate_of is not None:
                        duplicate_audio_count += 1
                    else:
                        seen_audio[audio_hash] = index

                    path = audio.get("path")
                    duplicate_path = path is not None and path in seen_paths
                    if duplicate_path:
                        duplicate_path_count += 1
                    if path is not None:
                        seen_paths.add(path)

                    record.update({
                        "sample_rate_hz": sr,
                        "channels": channels,
                        "frames": frames,
                        "duration_seconds": duration,
                        "peak": peak,
                        "rms": rms,
                        "waveform_sha256": audio_hash,
                        "duplicate_audio_of_index": duplicate_of,
                        "duplicate_path": duplicate_path,
                        "decode_ok": True,
                    })

                except Exception as error:
                    record["decode_ok"] = False
                    record["issues"].append(
                        f"{type(error).__name__}: {error}"
                    )

                audit.append(record)
                progress.update(1)

manifest_path = RECORDS_DIR / "svarah_audio_audit.jsonl"
with manifest_path.open("w", encoding="utf-8") as file:
    for record in audit:
        file.write(json.dumps(record, ensure_ascii=False) + "\n")

decoded = [record for record in audit if record["decode_ok"]]
issue_counts = Counter(
    issue for record in audit for issue in record["issues"]
)

summary = {
    "records_checked": len(audit),
    "expected_records": 6656,
    "decoded_records": len(decoded),
    "decode_failures": len(audit) - len(decoded),
    "decoded_duration_hours": sum(
        record["duration_seconds"] for record in decoded
    ) / 3600,
    "sample_rate_counts": dict(sample_rates),
    "channel_counts": dict(channel_counts),
    "exact_duplicate_audio_records": duplicate_audio_count,
    "duplicate_path_records": duplicate_path_count,
    "issue_counts": dict(issue_counts),
}

summary_path = RECORDS_DIR / "svarah_audio_audit_summary.json"
summary_path.write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\n=== FULL AUDIO AUDIT ===")
print(json.dumps(summary, indent=2))
print("\nManifest:", manifest_path)
print("Summary:", summary_path)

if len(audit) != 6656:
    raise RuntimeError(
        "Record count differs from the expected count. Stop here."
    )

print("\nAudit completed. Review the summary before proceeding.")

from pathlib import Path
from collections import defaultdict
import json
import re
import unicodedata

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

audit_path = RECORDS_DIR / "svarah_audio_audit.jsonl"

with audit_path.open(encoding="utf-8") as file:
    records = [json.loads(line) for line in file if line.strip()]

if len(records) != 6656:
    raise RuntimeError("Unexpected audit record count.")

def comparison_text(text):
    # For overlap detection only. Original transcripts remain unchanged.
    text = unicodedata.normalize("NFKC", text).casefold()
    text = "".join(
        " " if unicodedata.category(char).startswith("P") else char
        for char in text
    )
    return re.sub(r"\s+", " ", text).strip()

valid = [
    record for record in records
    if record["decode_ok"] and not record["issues"]
]

duration_options = [(1, 20), (1, 30), (2, 20)]
report = []

print("=== CANDIDATE DURATION RANGES ===")

for minimum, maximum in duration_options:
    candidates = [
        record for record in valid
        if minimum <= record["duration_seconds"] <= maximum
    ]

    text_groups = defaultdict(list)
    for record in candidates:
        key = comparison_text(record["text"])
        text_groups[key].append(record)

    repeated = {
        key: group for key, group in text_groups.items()
        if len(group) > 1
    }

    hours = sum(
        record["duration_seconds"] for record in candidates
    ) / 3600

    result = {
        "minimum_seconds": minimum,
        "maximum_seconds": maximum,
        "clips": len(candidates),
        "hours": hours,
        "unique_comparison_texts": len(text_groups),
        "repeated_text_groups": len(repeated),
        "clips_in_repeated_text_groups": sum(
            len(group) for group in repeated.values()
        ),
        "empty_comparison_texts": len(text_groups.get("", [])),
    }

    report.append(result)
    print(json.dumps(result, indent=2))

print("\n=== EXAMPLES AT DURATION EXTREMES ===")
ordered = sorted(valid, key=lambda record: record["duration_seconds"])

for label, examples in [
    ("Shortest", ordered[:3]),
    ("Longest", ordered[-3:]),
]:
    print(f"\n{label}:")
    for record in examples:
        print(
            f"{record['duration_seconds']:.3f} seconds | "
            f"{record['text'][:200]!r}"
        )

output_path = RECORDS_DIR / "svarah_selection_feasibility.json"
output_path.write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\nSaved:", output_path)
print("These are candidate ranges, not final exclusion rules.")
print("No transcripts changed and no splits created.")

from pathlib import Path
from collections import defaultdict
import json
import random
import re
import unicodedata

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
OUTPUT = ROOT / "English/manifests"
OUTPUT.mkdir(parents=True, exist_ok=True)

def comparison_text(text):
    text = unicodedata.normalize("NFKC", text).casefold()
    text = "".join(
        " " if unicodedata.category(c).startswith("P") else c
        for c in text
    )
    return re.sub(r"\s+", " ", text).strip()

# Comparison copies only; original test/source text is not modified.
test_texts = [
    "The antidisestablishmentarianism movement gained considerable momentum "
    "during the parliamentary proceedings.",
    "The orchestra's conduct during the ceremony was praised by the audience.",
    "The researchers will conduct an experiment to evaluate the proposed method.",
    "The rhyth  m of the orchestra changed unexpectedly.",
    "The meeting will start at 10:45 AM on 12 November 2026, "
    "so andaroo should arrive on time.",
]
test_keys = {comparison_text(text) for text in test_texts}

with (RECORDS / "svarah_audio_audit.jsonl").open(encoding="utf-8") as f:
    audit = [json.loads(line) for line in f if line.strip()]

rows = [
    row for row in audit
    if row["decode_ok"]
    and not row["issues"]
    and 1 <= row["duration_seconds"] <= 20
]

# Join related clips before selection.
parent = list(range(len(rows)))

def find(i):
    while parent[i] != i:
        parent[i] = parent[parent[i]]
        i = parent[i]
    return i

def union(i, j):
    parent[find(i)] = find(j)

seen_keys = {}
recording_keys = []

for i, row in enumerate(rows):
    filename = row["original_path"].replace("\\", "/").rsplit("/", 1)[-1]
    match = re.fullmatch(r"(\d+)_([fm]\d+)_chunk_(\d+)\.wav", filename)
    if match is None:
        raise ValueError(f"Unexpected filename: {filename}")

    recording_key = match.group(1)
    recording_keys.append(recording_key)

    for key in [
        ("text", comparison_text(row["text"])),
        ("recording_prefix", recording_key),
    ]:
        if key in seen_keys:
            union(i, seen_keys[key])
        else:
            seen_keys[key] = i

groups = defaultdict(list)
for i in range(len(rows)):
    groups[find(i)].append(i)

# Exclude entire related groups containing an exact comparison-text
# match to an assignment test sentence.
blocked = []
available = []

for indices in groups.values():
    if any(comparison_text(rows[i]["text"]) in test_keys for i in indices):
        blocked.extend(indices)
    else:
        available.append(indices)

rng = random.Random(42)
rng.shuffle(available)

def select_groups(pool, target_seconds):
    selected, remaining = [], []
    seconds = 0.0
    for indices in pool:
        group_seconds = sum(rows[i]["duration_seconds"] for i in indices)
        if abs(target_seconds - (seconds + group_seconds)) < abs(
            target_seconds - seconds
        ):
            selected.extend(indices)
            seconds += group_seconds
        else:
            remaining.append(indices)
    return selected, remaining, seconds

validation, pool, validation_seconds = select_groups(available, 3600)
training, reserve_groups, training_seconds = select_groups(pool, 5 * 3600)
reserve = [i for group in reserve_groups for i in group]

if abs(validation_seconds - 3600) > 60:
    raise RuntimeError("Validation duration is over one minute from target.")
if abs(training_seconds - 5 * 3600) > 60:
    raise RuntimeError("Training duration is over one minute from target.")

def keys(indices, kind):
    if kind == "text":
        return {comparison_text(rows[i]["text"]) for i in indices}
    if kind == "recording":
        return {recording_keys[i] for i in indices}
    return {rows[i]["waveform_sha256"] for i in indices}

assert set(training).isdisjoint(validation)
for kind in ("text", "recording", "audio"):
    assert keys(training, kind).isdisjoint(keys(validation, kind))

summary = {
    "status": "provisional_before_alignment_and_speaker_resolution",
    "seed": 42,
    "duration_range_seconds": [1, 20],
    "train_clips": len(training),
    "train_hours": training_seconds / 3600,
    "validation_clips": len(validation),
    "validation_hours": validation_seconds / 3600,
    "reserve_clips": len(reserve),
    "test_related_excluded_clips": len(blocked),
    "train_validation_overlap_checks": "PASSED",
    "speaker_disjointness": "not established",
}

for name, indices in [
    ("train_candidate", training),
    ("validation_candidate", validation),
    ("reserve_candidate", reserve),
]:
    with (OUTPUT / f"{name}.jsonl").open("w", encoding="utf-8") as f:
        for i in sorted(indices, key=lambda i: rows[i]["index"]):
            entry = dict(rows[i])
            entry["recording_group_key"] = recording_keys[i]
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")

(OUTPUT / "selection_summary.json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print(json.dumps(summary, indent=2))
print("\nCandidate manifests saved:", OUTPUT)
print("No speaker IDs assigned; no audio exported or training performed.")

