from pathlib import Path
from itertools import islice
import io
import json

import soundfile as sf
from datasets import load_dataset, Audio

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

inventory = json.loads(
    (RECORDS_DIR / "telugu_repository_inventory.json").read_text(
        encoding="utf-8"
    )
)

dataset = load_dataset(
    inventory["dataset"],
    revision=inventory["revision"],
    split="train",
    streaming=True,
    token=False,
)

print("=== DATASET FEATURES ===")
print(dataset.features)

if dataset.features is None:
    raise RuntimeError("Dataset schema is unavailable.")

features = dataset.features
if "audio" not in features or "text" not in features:
    raise RuntimeError("Expected audio/text fields are missing.")

gender_feature = features.get("gender")
dataset = dataset.cast_column("audio", Audio(decode=False))

checks = []

print("\n=== THREE SAMPLE RECORDS ===")

for index, example in enumerate(islice(dataset, 3)):
    audio = example["audio"]
    encoded = audio.get("bytes")

    if encoded is None:
        raise RuntimeError("Embedded audio bytes are missing.")

    with io.BytesIO(encoded) as buffer:
        info = sf.info(buffer)

    text = example["text"]
    gender_value = example.get("gender")
    gender_label = (
        gender_feature.int2str(gender_value)
        if hasattr(gender_feature, "int2str")
        and gender_value is not None
        else gender_value
    )

    path = str(audio.get("path") or "")
    record = {
        "record_index": index,
        "audio_filename": path.replace("\\", "/").rsplit("/", 1)[-1],
        "text": text,
        "telugu_unicode_character_count": sum(
            "\u0c00" <= character <= "\u0c7f"
            for character in text
        ),
        "devanagari_character_count": sum(
            "\u0900" <= character <= "\u097f"
            for character in text
        ),
        "gender_label": gender_label,
        "sample_rate_hz": info.samplerate,
        "channels": info.channels,
        "format": info.format,
        "subtype": info.subtype,
        "duration_seconds": info.frames / info.samplerate,
    }

    checks.append(record)
    print(json.dumps(record, indent=2, ensure_ascii=False))

if len(checks) != 3:
    raise RuntimeError("Fewer than three records were inspected.")

result = {
    "dataset": inventory["dataset"],
    "revision": inventory["revision"],
    "features": features.to_dict(),
    "sample_checks": checks,
    "license_review_status": "pending",
}

output_path = RECORDS_DIR / "telugu_initial_sample_checks.json"
output_path.write_text(
    json.dumps(result, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\nThree-record inspection: PASSED")
print("Saved:", output_path)
print("Corpus-wide language, speaker, and duration checks remain pending.")

