from pathlib import Path
from collections import Counter, defaultdict
import hashlib
import io
import json
import re

import numpy as np
import pyarrow.parquet as pq
import soundfile as sf
from tqdm.auto import tqdm

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

download = json.loads(
    (RECORDS_DIR / "telugu_local_shards.json").read_text(
        encoding="utf-8"
    )
)
initial = json.loads(
    (RECORDS_DIR / "telugu_initial_sample_checks.json").read_text(
        encoding="utf-8"
    )
)

gender_names = initial["features"]["gender"]["names"]

audit = []
sample_rates = Counter()
channel_counts = Counter()
speaker_seconds = defaultdict(float)
seen_hashes = {}
seen_paths = set()
duplicate_audio_count = 0
duplicate_path_count = 0

for shard in download["files"]:
    parquet = pq.ParquetFile(shard["local_path"])
    print(f"\nChecking {Path(shard['local_path']).name}")

    with tqdm(total=parquet.metadata.num_rows, unit="clip") as progress:
        for batch in parquet.iter_batches(batch_size=8):
            for row in batch.to_pylist():
                index = len(audit)
                audio = row["audio"]
                record = {
                    "index": index,
                    "shard": shard["filename"],
                    "original_path": audio.get("path"),
                    "text": row["text"],
                    "gender_value": row["gender"],
                    "issues": [],
                }

                try:
                    label = gender_names[int(row["gender"])]
                    record["gender_label"] = label

                    filename = str(audio.get("path") or "").replace(
                        "\\", "/"
                    ).rsplit("/", 1)[-1]

                    match = re.fullmatch(
                        r"train_telugu(female|male)_(\d+)\.wav",
                        filename,
                    )
                    if match is None:
                        record["issues"].append("unexpected_filename")
                    elif match.group(1) != label:
                        record["issues"].append("filename_label_mismatch")

                    encoded = audio.get("bytes")
                    if encoded is None:
                        raise ValueError("Embedded audio bytes missing.")

                    with io.BytesIO(encoded) as buffer:
                        waveform, sr = sf.read(
                            buffer, dtype="float32", always_2d=True
                        )

                    frames, channels = waveform.shape
                    if frames == 0:
                        raise ValueError("Zero audio frames.")
                    if not np.isfinite(waveform).all():
                        raise ValueError("Non-finite audio samples.")

                    duration = frames / sr
                    peak = float(np.max(np.abs(waveform)))
                    rms = float(np.sqrt(
                        np.mean(waveform.astype(np.float64) ** 2)
                    ))

                    sample_rates[sr] += 1
                    channel_counts[channels] += 1
                    speaker_seconds[label] += duration

                    text = str(row["text"] or "")
                    telugu_count = sum(
                        "\u0c00" <= char <= "\u0c7f" for char in text
                    )

                    if not text.strip():
                        record["issues"].append("empty_transcript")
                    elif telugu_count == 0:
                        record["issues"].append("no_telugu_script")
                    if peak == 0:
                        record["issues"].append("silent_audio")

                    digest = hashlib.sha256()
                    digest.update(f"{sr}:{channels}:".encode("ascii"))
                    digest.update(
                        np.ascontiguousarray(
                            waveform, dtype="<f4"
                        ).tobytes()
                    )
                    audio_hash = digest.hexdigest()

                    duplicate_of = seen_hashes.get(audio_hash)
                    if duplicate_of is None:
                        seen_hashes[audio_hash] = index
                    else:
                        duplicate_audio_count += 1

                    path = audio.get("path")
                    duplicate_path = path is not None and path in seen_paths
                    if duplicate_path:
                        duplicate_path_count += 1
                    if path is not None:
                        seen_paths.add(path)

                    record.update({
                        "decode_ok": True,
                        "sample_rate_hz": sr,
                        "channels": channels,
                        "frames": frames,
                        "duration_seconds": duration,
                        "peak": peak,
                        "rms": rms,
                        "telugu_character_count": telugu_count,
                        "waveform_sha256": audio_hash,
                        "duplicate_audio_of_index": duplicate_of,
                        "duplicate_path": duplicate_path,
                    })

                except Exception as error:
                    record["decode_ok"] = False
                    record["issues"].append(
                        f"{type(error).__name__}: {error}"
                    )

                audit.append(record)
                progress.update(1)

manifest_path = RECORDS_DIR / "telugu_audio_audit.jsonl"
with manifest_path.open("w", encoding="utf-8") as file:
    for record in audit:
        file.write(json.dumps(record, ensure_ascii=False) + "\n")

decoded = [record for record in audit if record["decode_ok"]]
clean = [
    record for record in decoded
    if not record["issues"]
    and record["duplicate_audio_of_index"] is None
]

ranges = []
for minimum, maximum in [(1, 20), (1, 30), (1, 45)]:
    selected = [
        record for record in clean
        if minimum <= record["duration_seconds"] <= maximum
    ]
    hours_by_label = defaultdict(float)
    for record in selected:
        hours_by_label[record["gender_label"]] += (
            record["duration_seconds"] / 3600
        )

    ranges.append({
        "range_seconds": [minimum, maximum],
        "clips": len(selected),
        "hours": sum(hours_by_label.values()),
        "hours_by_label": dict(hours_by_label),
    })

summary = {
    "records_checked": len(audit),
    "expected_records": 8576,
    "decoded_records": len(decoded),
    "decode_failures": len(audit) - len(decoded),
    "decoded_hours": sum(
        record["duration_seconds"] for record in decoded
    ) / 3600,
    "sample_rate_counts": dict(sample_rates),
    "channel_counts": dict(channel_counts),
    "decoded_hours_by_label": {
        label: seconds / 3600
        for label, seconds in speaker_seconds.items()
    },
    "exact_duplicate_audio_records": duplicate_audio_count,
    "duplicate_path_records": duplicate_path_count,
    "issue_counts": dict(Counter(
        issue for record in audit for issue in record["issues"]
    )),
    "candidate_duration_ranges": ranges,
}

summary_path = RECORDS_DIR / "telugu_audio_audit_summary.json"
summary_path.write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\n=== FULL TELUGU AUDIO AUDIT ===")
print(json.dumps(summary, indent=2))
print("\nManifest:", manifest_path)
print("Summary:", summary_path)

if len(audit) != 8576:
    raise RuntimeError("Unexpected record count. Stop here.")

print("\nAudit completed. No splits or training performed.")

from pathlib import Path
from collections import Counter, defaultdict
import io
import json

import pyarrow.parquet as pq
import soundfile as sf
from IPython.display import Audio, display

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

with (RECORDS_DIR / "telugu_audio_audit.jsonl").open(
    encoding="utf-8"
) as f:
    audit = [json.loads(line) for line in f if line.strip()]

download = json.loads(
    (RECORDS_DIR / "telugu_local_shards.json").read_text(
        encoding="utf-8"
    )
)

print("=== LABEL / SAMPLE-RATE COUNTS ===")
counts = Counter(
    (row["gender_label"], row["sample_rate_hz"])
    for row in audit if row["decode_ok"]
)
for (label, rate), count in sorted(counts.items()):
    print(f"{label} | {rate} Hz | {count} clips")

# Locate one 3–12 second example for each available combination.
selected = {}
local_indices = Counter()
targets = defaultdict(dict)

for row in audit:
    shard = row["shard"]
    local_index = local_indices[shard]
    local_indices[shard] += 1

    if not row["decode_ok"] or row["issues"]:
        continue

    key = (row["gender_label"], row["sample_rate_hz"])
    if key not in selected and 3 <= row["duration_seconds"] <= 12:
        selected[key] = row
        targets[shard][local_index] = row

print("\nExamples selected:", len(selected))

for shard in download["files"]:
    wanted = dict(targets.get(shard["filename"], {}))
    if not wanted:
        continue

    parquet = pq.ParquetFile(shard["local_path"])
    offset = 0

    for batch in parquet.iter_batches(
        batch_size=8, columns=["audio"]
    ):
        batch_end = offset + batch.num_rows
        matching = [
            index for index in wanted
            if offset <= index < batch_end
        ]

        if matching:
            batch_rows = batch.to_pylist()

            for index in sorted(matching):
                record = wanted.pop(index)
                encoded = batch_rows[index - offset]["audio"]["bytes"]

                with io.BytesIO(encoded) as buffer:
                    waveform, rate = sf.read(
                        buffer, dtype="float32", always_2d=True
                    )

                print(
                    f"\nAUDIT INDEX {record['index']} | "
                    f"{record['gender_label']} | {rate} Hz"
                )
                print("Text:", record["text"])
                print(
                    "Full duration:",
                    round(record["duration_seconds"], 3),
                    "seconds; playing first 8 seconds at most.",
                )

                excerpt = waveform[:8 * rate, 0]
                display(Audio(
                    excerpt, rate=rate, normalize=False
                ))

        offset = batch_end
        if not wanted:
            break

    if wanted:
        raise RuntimeError("Some selected examples were not found.")

print("\nListening examples displayed. No audio modified.")

from pathlib import Path
from collections import defaultdict
import json
import random
import re
import unicodedata

import numpy as np
from scipy.optimize import milp, Bounds, LinearConstraint
from scipy.sparse import coo_matrix

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
OUTPUT = ROOT / "Telugu/manifests"

def comparison_text(text):
    text = unicodedata.normalize("NFC", text).casefold()
    text = "".join(
        " " if unicodedata.category(c).startswith("P") else c
        for c in text
    )
    return re.sub(r"\s+", " ", text).strip()

with (RECORDS / "telugu_audio_audit.jsonl").open(
    encoding="utf-8"
) as f:
    audit = [json.loads(line) for line in f if line.strip()]

eligible = [
    row for row in audit
    if row["decode_ok"]
    and not row["issues"]
    and row["duplicate_audio_of_index"] is None
    and 1 <= row["duration_seconds"] <= 20
]

grouped = defaultdict(list)
for row in eligible:
    key = comparison_text(row["text"])
    if not key:
        raise ValueError("Empty comparison text.")
    grouped[key].append(row)

groups = [grouped[key] for key in sorted(grouped)]
random.Random(42).shuffle(groups)

labels = ("female", "male")
n = len(groups)

# Two binary choices per group: training or validation.
# Choosing neither leaves the group in reserve.
matrix_rows, matrix_columns, matrix_values = [], [], []

for i, group in enumerate(groups):
    seconds = {label: 0.0 for label in labels}
    for row in group:
        seconds[row["gender_label"]] += row["duration_seconds"]

    for label_index, label in enumerate(labels):
        matrix_rows.extend([label_index, 2 + label_index])
        matrix_columns.extend([2 * i, 2 * i + 1])
        matrix_values.extend([seconds[label], seconds[label]])

    # A group cannot occur in both splits.
    matrix_rows.extend([4 + i, 4 + i])
    matrix_columns.extend([2 * i, 2 * i + 1])
    matrix_values.extend([1.0, 1.0])

matrix = coo_matrix(
    (matrix_values, (matrix_rows, matrix_columns)),
    shape=(4 + n, 2 * n),
).tocsc()

# Targets: 2.5 training hours and 0.5 validation hours per speaker.
# Allow at most 30 seconds deviation per speaker/split.
targets = np.array([9000, 9000, 1800, 1800], dtype=float)
lower = np.concatenate([targets - 30, np.zeros(n)])
upper = np.concatenate([targets + 30, np.ones(n)])

print("Eligible clips:", len(eligible))
print("Transcript groups:", n)
print("Finding a jointly balanced selection...")

result = milp(
    c=np.zeros(2 * n),
    integrality=np.ones(2 * n, dtype=int),
    bounds=Bounds(np.zeros(2 * n), np.ones(2 * n)),
    constraints=LinearConstraint(matrix, lower, upper),
    options={"time_limit": 30.0},
)

print("Solver status:", result.message)

if result.x is None:
    raise RuntimeError(
        "No selection returned. Share this output. "
        "A timeout does not prove the constraints are impossible."
    )

choices = np.rint(result.x).astype(int)
if np.max(np.abs(result.x - choices)) > 1e-5:
    raise RuntimeError("Solver did not return an integer selection.")

training, validation, reserve = [], [], []

for i, group in enumerate(groups):
    train_choice, val_choice = choices[2 * i:2 * i + 2]
    if train_choice + val_choice > 1:
        raise RuntimeError("A group was selected twice.")
    if train_choice:
        training.extend(group)
    elif val_choice:
        validation.extend(group)
    else:
        reserve.extend(group)

def seconds_by_label(records):
    return {
        label: sum(
            row["duration_seconds"]
            for row in records
            if row["gender_label"] == label
        )
        for label in labels
    }

train_seconds = seconds_by_label(training)
val_seconds = seconds_by_label(validation)

for label in labels:
    assert abs(train_seconds[label] - 9000) <= 30.001
    assert abs(val_seconds[label] - 1800) <= 30.001

def keys(records, field):
    if field == "text":
        return {comparison_text(row["text"]) for row in records}
    return {row[field] for row in records}

for field in ("index", "text", "original_path", "waveform_sha256"):
    assert keys(training, field).isdisjoint(
        keys(validation, field)
    ), f"Overlap detected: {field}"

summary = {
    "status": "provisional_before_test_text_check_and_alignment",
    "method": "joint constrained selection of intact transcript groups",
    "seed": 42,
    "duration_range_seconds": [1, 20],
    "train_clips": len(training),
    "train_hours": sum(train_seconds.values()) / 3600,
    "train_hours_by_label": {
        label: value / 3600 for label, value in train_seconds.items()
    },
    "validation_clips": len(validation),
    "validation_hours": sum(val_seconds.values()) / 3600,
    "validation_hours_by_label": {
        label: value / 3600 for label, value in val_seconds.items()
    },
    "reserve_clips": len(reserve),
    "train_validation_overlap_checks": "PASSED",
    "speaker_policy": "Both documented speakers occur in both splits.",
    "assignment_test_text_overlap_check": "pending",
    "listening_check": "User reported pass for audit indices 4 and 4043.",
    "scipy_version": __import__("scipy").__version__,
}

# Write only after all duration and overlap checks pass.
OUTPUT.mkdir(parents=True, exist_ok=True)

for name, records in [
    ("train_candidate", training),
    ("validation_candidate", validation),
    ("reserve_candidate", reserve),
]:
    with (OUTPUT / f"{name}.jsonl").open("w", encoding="utf-8") as f:
        for row in sorted(records, key=lambda row: row["index"]):
            f.write(json.dumps(row, ensure_ascii=False) + "\n")

(OUTPUT / "selection_summary.json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\n=== REPAIRED SELECTION ===")
print(json.dumps(summary, indent=2))
print("\nManifests saved:", OUTPUT)

from pathlib import Path
from collections import defaultdict
import json

import pyarrow.parquet as pq

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

fields = [
    "gender", "age-group", "primary_language",
    "native_place_state", "native_place_district",
    "highest_qualification", "job_category", "occupation_domain",
]

metadata = pq.read_table(
    RECORDS / "svarah_original_metadata.parquet"
).to_pylist()

def filename(path):
    return str(path).replace("\\", "/").rsplit("/", 1)[-1]

by_filename = {}
profiles = defaultdict(list)

for row in metadata:
    name = filename(row["audio_filepath"])
    if name in by_filename:
        raise ValueError(f"Duplicate metadata filename: {name}")

    profile = tuple(row.get(field) for field in fields)
    by_filename[name] = {
        "text": row["text"],
        "duration": float(row["duration"]),
        "profile": profile,
    }
    profiles[profile].append(row)

def read_manifest(name):
    path = ROOT / "English/manifests" / name
    with path.open(encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]

def selected_profiles(records):
    found = set()

    for record in records:
        name = filename(record["original_path"])
        if name not in by_filename:
            raise ValueError(f"No historical metadata match: {name}")

        source = by_filename[name]

        # Verify correspondence instead of assuming row order is unchanged.
        if source["text"] != record["text"]:
            raise ValueError(f"Transcript mismatch: {name}")

        if abs(source["duration"] - record["duration_seconds"]) > 0.02:
            raise ValueError(f"Duration mismatch: {name}")

        found.add(source["profile"])

    return found

training = read_manifest("train_candidate.jsonl")
validation = read_manifest("validation_candidate.jsonl")

train_profiles = selected_profiles(training)
val_profiles = selected_profiles(validation)

profile_minutes = [
    sum(float(row["duration"]) for row in group) / 60
    for group in profiles.values()
]

summary = {
    "historical_metadata_records": len(metadata),
    "distinct_demographic_profiles": len(profiles),
    "profiles_with_missing_values": sum(
        any(value is None or str(value).strip() == "" for value in profile)
        for profile in profiles
    ),
    "training_profiles": len(train_profiles),
    "validation_profiles": len(val_profiles),
    "validation_profiles_absent_from_training": len(
        val_profiles - train_profiles
    ),
    "minimum_profile_minutes": min(profile_minutes),
    "maximum_profile_minutes": max(profile_minutes),
    "selected_metadata_correspondence": "PASSED",
    "verified_speaker_ids": False,
}

output = RECORDS / "svarah_demographic_profile_audit.json"
output.write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print(json.dumps(summary, indent=2))
print("\nSaved:", output)
print("No demographic details printed or speaker IDs assigned.")

from pathlib import Path
import hashlib
import json

import pyarrow.parquet as pq

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "English/manifests"

fields = [
    "gender", "age-group", "primary_language",
    "native_place_state", "native_place_district",
    "highest_qualification", "job_category", "occupation_domain",
]

metadata = pq.read_table(
    RECORDS / "svarah_original_metadata.parquet"
).to_pylist()

def filename(path):
    return str(path).replace("\\", "/").rsplit("/", 1)[-1]

def profile_fingerprint(row):
    # This hash creates an opaque group key, not an anonymous identity
    # or proof that records belong to one speaker.
    values = [row.get(field) for field in fields]
    encoded = json.dumps(
        values, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()

lookup = {}
for row in metadata:
    name = filename(row["audio_filepath"])
    if name in lookup:
        raise ValueError(f"Duplicate metadata filename: {name}")
    lookup[name] = {
        "fingerprint": profile_fingerprint(row),
        "text": row["text"],
        "duration": float(row["duration"]),
    }

fingerprints = sorted({
    entry["fingerprint"] for entry in lookup.values()
})
group_names = {
    fingerprint: f"proxy_{index:03d}"
    for index, fingerprint in enumerate(fingerprints)
}

prepared = {}
for split in ("train", "validation", "reserve"):
    source_path = MANIFESTS / f"{split}_candidate.jsonl"
    with source_path.open(encoding="utf-8") as f:
        rows = [json.loads(line) for line in f if line.strip()]

    augmented = []
    for row in rows:
        source = lookup[filename(row["original_path"])]

        if source["text"] != row["text"]:
            raise ValueError("Transcript correspondence failed.")
        if abs(source["duration"] - row["duration_seconds"]) > 0.02:
            raise ValueError("Duration correspondence failed.")

        entry = dict(row)
        entry["conditioning_group"] = group_names[source["fingerprint"]]
        entry["conditioning_group_type"] = "demographic_proxy"
        augmented.append(entry)

    prepared[split] = augmented

train_groups = {
    row["conditioning_group"] for row in prepared["train"]
}
val_groups = {
    row["conditioning_group"] for row in prepared["validation"]
}

if not val_groups.issubset(train_groups):
    raise RuntimeError("Validation contains a group absent from training.")

# Continuous embedding indices for the groups represented in training.
embedding_indices = {
    name: index for index, name in enumerate(sorted(train_groups))
}

policy = {
    "status": "provisional_modeling_compromise",
    "method": "exact matching of eight released demographic fields",
    "conditioning_group_count": len(embedding_indices),
    "published_speaker_count": 117,
    "verified_speaker_identity": False,
    "multiple_people_per_group_possible": True,
    "validation_groups_present_in_training": True,
    "embedding_indices": embedding_indices,
    "limitations": [
        "Proxy groups are not verified speaker identities.",
        "Conditioning may combine different voices.",
        "Speaker-disjoint evaluation cannot be claimed.",
    ],
}

# Save only after all checks pass.
for split, rows in prepared.items():
    output = MANIFESTS / f"{split}_candidate_with_groups.jsonl"
    with output.open("w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")

(MANIFESTS / "conditioning_group_policy.json").write_text(
    json.dumps(policy, indent=2), encoding="utf-8"
)

print("English proxy conditioning groups:", len(embedding_indices))
print("Validation group coverage: PASSED")
print("Original manifests: preserved")
print("Augmented manifests and policy saved:", MANIFESTS)
print("Verified speaker identities: NO")
print("No alignment or training performed.")

from pathlib import Path
import json
import re
import unicodedata

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
MANIFESTS = ROOT / "Telugu/manifests"

test_sentences = []

for sentence_id in ("T1", "T2a", "T2b", "T3", "T4"):
    text = input(f"Paste the exact {sentence_id} sentence: ")

    if not text.strip():
        raise ValueError(f"{sentence_id} is empty. No file saved.")

    if not any("\u0c00" <= character <= "\u0c7f" for character in text):
        raise ValueError(
            f"{sentence_id} contains no Telugu characters. No file saved."
        )

    test_sentences.append({
        "id": sentence_id,
        "original_text": text,
        "verification_status": "awaiting_user_confirmation",
    })

print("\n=== CHECK AGAINST THE ASSIGNMENT ===")
for sentence in test_sentences:
    print(f"\n{sentence['id']}: {sentence['original_text']}")
    print("Whitespace-visible representation:", repr(sentence["original_text"]))

def comparison_text(text):
    text = unicodedata.normalize("NFC", text).casefold()
    text = "".join(
        " " if unicodedata.category(c).startswith("P") else c
        for c in text
    )
    return re.sub(r"\s+", " ", text).strip()

test_keys = {
    comparison_text(sentence["original_text"]): sentence["id"]
    for sentence in test_sentences
}

matches = []
for split in ("train", "validation"):
    path = MANIFESTS / f"{split}_candidate.jsonl"
    with path.open(encoding="utf-8") as file:
        for line in file:
            row = json.loads(line)
            key = comparison_text(row["text"])
            if key in test_keys:
                matches.append({
                    "split": split,
                    "audit_index": row["index"],
                    "test_id": test_keys[key],
                })

output_path = MANIFESTS / "test_sentences_candidate.json"
output_path.write_text(
    json.dumps(test_sentences, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\n=== TEST-TEXT OVERLAP CHECK ===")
print(json.dumps(matches, indent=2))
print("Matching selected recordings:", len(matches))
print("Candidate test text saved:", output_path)
print("Text confirmation is still required.")
print("No training/validation manifests changed.")

from pathlib import Path
from datetime import datetime, timezone
import json
import re
import shutil
import unicodedata

MANIFESTS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/Telugu/manifests"
)

# Restore missing endings; retain your supplied internal spaces.
sentences = {
    "T1": "న్యూ రోఫార్మ కోలాజికల్ పరిశోధనలో నూతన ఔషధాల ప్రభావాన్ని విశ్లేషించారు.",
    "T2a": "తాడుపై అతని పట్టు చాలా బలంగా ఉంది.",
    "T2b": "ఆమె పట్టు చీరను ధరించి వేడుకకు వచ్చ ింది.",
    "T3": "పులి అడ  విలో నిశ్శ బ్దంగా నడిచింది.",
    "T4": "ఈ సమావేశం 2026 నవంబర్ 12వ తేదీ ఉదయం 10:45 గంటలకు ప్రారంభమవుతుంది, సమయానికి సిద్ధంగా ఉంచండి.",
}

candidate_path = MANIFESTS / "test_sentences_candidate.json"

if candidate_path.exists():
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = MANIFESTS / f"test_sentences_backup_{timestamp}.json"
    shutil.copyfile(candidate_path, backup)
    print("Previous candidate backed up:", backup.name)

records = [
    {
        "id": sentence_id,
        "original_text": text,
        "verification_status": "endings_restored_spacing_awaiting_confirmation",
    }
    for sentence_id, text in sentences.items()
]

def comparison_text(text):
    text = unicodedata.normalize("NFC", text).casefold()
    text = "".join(
        " " if unicodedata.category(c).startswith("P") else c
        for c in text
    )
    return re.sub(r"\s+", " ", text).strip()

matches = []

for split in ("train", "validation"):
    with (MANIFESTS / f"{split}_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        for line in file:
            row = json.loads(line)
            for sentence_id, text in sentences.items():
                if comparison_text(row["text"]) == comparison_text(text):
                    matches.append({
                        "split": split,
                        "audit_index": row["index"],
                        "test_id": sentence_id,
                    })

candidate_path.write_text(
    json.dumps(records, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\n=== REPAIRED CANDIDATE TEXT ===")
for sentence_id, text in sentences.items():
    print(f"{sentence_id}: {text}")

print("\nMatching selected recordings:", len(matches))
print(json.dumps(matches, indent=2))
print("\nCandidate saved:", candidate_path)
print("Training/validation manifests unchanged.")

from pathlib import Path
from importlib import metadata
import json
import shutil
import subprocess
import sys

RECORDS_DIR = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

print("=== CURRENT PYTHON ===")
print(sys.version)

print("\n=== COMMAND AVAILABILITY ===")
commands = {}
for name in ("mfa", "conda", "micromamba", "uv", "espeak-ng", "espeak"):
    commands[name] = shutil.which(name)
    print(f"{name}: {commands[name] or 'NOT FOUND'}")

print("\n=== RELEVANT PACKAGES ===")
packages = {}
for name in (
    "Montreal-Forced-Aligner",
    "phonemizer",
    "praatio",
    "kaldiio",
):
    try:
        packages[name] = metadata.version(name)
    except metadata.PackageNotFoundError:
        packages[name] = "NOT INSTALLED"
    print(f"{name}: {packages[name]}")

print("\n=== EXISTING TOOL CHECKS ===")
tool_checks = {}

for name in ("mfa", "espeak-ng", "espeak"):
    executable = commands[name]
    if executable is None:
        continue

    arguments = (
        [executable, "--version"]
        if name == "mfa"
        else [executable, "--voices=te"]
    )

    try:
        result = subprocess.run(
            arguments,
            capture_output=True,
            text=True,
            timeout=15,
        )
        output = (result.stdout + result.stderr).strip()
        tool_checks[name] = {
            "exit_code": result.returncode,
            "output": output,
        }
        print(f"\n{name}:\n{output or '(no output)'}")
    except subprocess.TimeoutExpired:
        tool_checks[name] = {"status": "timed out"}
        print(f"{name}: check timed out")

record = {
    "python": sys.version,
    "commands": commands,
    "packages": packages,
    "tool_checks": tool_checks,
}

output_path = RECORDS_DIR / "alignment_tool_inventory.json"
output_path.write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("\nInventory saved:", output_path)
print("No packages installed; no alignment performed.")

from pathlib import Path
import hashlib
import json
import os
import platform
import shutil
import subprocess
import sys
import tarfile

import requests

RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)
TOOLS = Path("/content/fastspeech2_tools")
TOOLS.mkdir(parents=True, exist_ok=True)

if platform.machine() not in ("x86_64", "AMD64"):
    raise RuntimeError("This installation cell expects Linux x86_64.")

archive = TOOLS / "micromamba.tar.bz2"
binary = TOOLS / "micromamba"
prefix = TOOLS / "mfa_env"

# Download the official Micromamba archive.
if not binary.exists():
    url = "https://micro.mamba.pm/api/micromamba/linux-64/latest"
    print("Downloading Micromamba...", flush=True)

    with requests.get(url, stream=True, timeout=(30, 180)) as response:
        response.raise_for_status()
        with archive.open("wb") as file:
            for chunk in response.iter_content(1024 * 1024):
                if chunk:
                    file.write(chunk)

    # Extract only the expected executable, without unpacking other paths.
    with tarfile.open(archive, "r:bz2") as package:
        member = package.getmember("bin/micromamba")
        source = package.extractfile(member)
        if source is None:
            raise RuntimeError("Micromamba executable missing.")
        with source, binary.open("wb") as destination:
            shutil.copyfileobj(source, destination)

    binary.chmod(0o755)

version = subprocess.run(
    [str(binary), "--version"],
    capture_output=True,
    text=True,
    check=True,
).stdout.strip()

print("Micromamba:", version, flush=True)

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = str(TOOLS / "mamba_root")

command = [
    str(binary), "create",
    "--yes",
    "--prefix", str(prefix),
    "--override-channels",
    "--channel", "conda-forge",
    "python=3.11",
    "montreal-forced-aligner",
    "kalpy",
]

# On a successful rerun, reuse the existing environment.
if not (prefix / "bin/mfa").exists():
    print("Creating the isolated MFA environment...", flush=True)
    log_path = RECORDS / "mfa_install.log"

    with log_path.open("w", encoding="utf-8") as log:
        process = subprocess.Popen(
            command,
            env=environment,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        for line in process.stdout:
            print(line, end="", flush=True)
            log.write(line)
            log.flush()

        exit_code = process.wait()

    if exit_code != 0:
        raise RuntimeError(
            f"MFA installation failed with exit code {exit_code}. "
            "Share the complete error output."
        )
else:
    print("Reusing the existing MFA environment.", flush=True)

check = subprocess.run(
    [
        str(binary), "run", "--prefix", str(prefix),
        "mfa", "--version",
    ],
    env=environment,
    capture_output=True,
    text=True,
)

print("\n=== MFA VERSION CHECK ===")
print(check.stdout)
print(check.stderr)

if check.returncode != 0:
    raise RuntimeError(
        f"MFA version check failed: exit code {check.returncode}"
    )

# Capture exact resolved packages for reproducibility.
resolved = subprocess.run(
    [
        str(binary), "list", "--prefix", str(prefix),
        "--explicit",
    ],
    env=environment,
    capture_output=True,
    text=True,
    check=True,
)
(RECORDS / "mfa_environment_explicit.txt").write_text(
    resolved.stdout, encoding="utf-8"
)

record = {
    "micromamba_version": version,
    "micromamba_binary_sha256": hashlib.sha256(
        binary.read_bytes()
    ).hexdigest(),
    "micromamba_path": str(binary),
    "environment_prefix": str(prefix),
    "mamba_root_prefix": environment["MAMBA_ROOT_PREFIX"],
    "mfa_version_output": check.stdout.strip(),
    "notebook_python": sys.version,
}

(RECORDS / "mfa_environment.json").write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("MFA installation/version check: PASSED")
print("Notebook Python remains:", sys.version.split()[0])
print("No acoustic models downloaded; no alignment performed.")

