binary = TOOLS / "micromamba"
prefix = TOOLS / "mfa_env"

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = str(TOOLS / "mamba_root")

def run(arguments):
    return subprocess.run(
        arguments,
        env=environment,
        capture_output=True,
        text=True,
    )

# Obtain versions from Conda records, not Python distribution metadata.
package_check = run([
    str(binary), "list", "--prefix", str(prefix), "--json"
])

if package_check.returncode != 0:
    print(package_check.stdout)
    print(package_check.stderr)
    raise RuntimeError("Could not read environment package records.")

packages = json.loads(package_check.stdout)
wanted = {"python", "montreal-forced-aligner", "kalpy"}
versions = {
    package["name"]: package["version"]
    for package in packages
    if package["name"] in wanted
}

print("=== INSTALLED CONDA PACKAGES ===")
print(json.dumps(versions, indent=2))

missing = wanted - set(versions)
if missing:
    raise RuntimeError(f"Missing Conda package records: {sorted(missing)}")

# Verify that the installed modules actually import.
import_check = run([
    str(binary), "run", "--prefix", str(prefix),
    "python", "-c",
    (
        "import kalpy; "
        "import montreal_forced_aligner; "
        "print('Kalpy and MFA imports: PASSED')"
    ),
])

print("\n=== IMPORT CHECK ===")
print(import_check.stdout)
if import_check.stderr:
    print(import_check.stderr)

if import_check.returncode != 0:
    raise RuntimeError("Module import check failed. Share the traceback.")

help_check = run([
    str(binary), "run", "--prefix", str(prefix),
    "mfa", "--help",
])

(RECORDS / "mfa_help.txt").write_text(
    help_check.stdout + help_check.stderr,
    encoding="utf-8",
)

print("\n=== EXECUTABLE CHECK ===")
print("mfa --help exit code:", help_check.returncode)

if help_check.returncode != 0:
    print(help_check.stdout)
    print(help_check.stderr)
    raise RuntimeError("MFA executable check failed.")

resolved = run([
    str(binary), "list", "--prefix", str(prefix), "--explicit"
])

if resolved.returncode != 0:
    print(resolved.stderr)
    raise RuntimeError("Could not export the environment specification.")

(RECORDS / "mfa_environment_explicit.txt").write_text(
    resolved.stdout, encoding="utf-8"
)

record = {
    "micromamba_path": str(binary),
    "environment_prefix": str(prefix),
    "mamba_root_prefix": environment["MAMBA_ROOT_PREFIX"],
    "versions": versions,
    "module_import_check": "PASSED",
    "mfa_help_exit_code": help_check.returncode,
    "notebook_python": sys.version,
}

(RECORDS / "mfa_environment.json").write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

