metadata_dir = prefix / "conda-meta"
if not metadata_dir.is_dir():
    raise FileNotFoundError(
        "MFA environment package records are missing. Stop here."
    )

wanted = {"python", "montreal-forced-aligner", "kalpy"}
versions = {}

for path in metadata_dir.glob("*.json"):
    package = json.loads(path.read_text(encoding="utf-8"))
    if package.get("name") in wanted:
        versions[package["name"]] = package["version"]

print("=== INSTALLED PACKAGES ===")
print(json.dumps(versions, indent=2))

missing = wanted - set(versions)
if missing:
    raise RuntimeError(f"Missing package records: {sorted(missing)}")

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = str(TOOLS / "mamba_root")

def run_in_mfa(arguments):
    return subprocess.run(
        [str(binary), "run", "--prefix", str(prefix), *arguments],
        env=environment,
        capture_output=True,
        text=True,
    )

checks = {
    "imports": [
        "python", "-c",
        (
            "import kalpy; "
            "import montreal_forced_aligner; "
            "print('Kalpy and MFA imports: PASSED')"
        ),
    ],
    "help": ["mfa", "--help"],
}

for name, arguments in checks.items():
    result = run_in_mfa(arguments)

    (RECORDS / f"mfa_{name}_check.log").write_text(
        result.stdout + result.stderr,
        encoding="utf-8",
    )

    print(f"\n=== {name.upper()} CHECK ===")
