from pathlib import Path
import hashlib
import json
import os
import shutil
import subprocess

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
RECORDS = BASE / "project/reproducibility"

setup = json.loads(
    (RECORDS / "mfa_environment.json").read_text(encoding="utf-8")
)

binary = Path(setup["micromamba_path"])
prefix = Path(setup["environment_prefix"])

# Keep MFA's working files on Colab disk.
MFA_DATA = Path("/content/fastspeech2_tools/mfa_data")
MFA_DATA.mkdir(parents=True, exist_ok=True)

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = str(MFA_DATA)

def run_mfa(arguments, log_name):
    command = [
        str(binary), "run", "--prefix", str(prefix),
        "mfa", *arguments,
    ]

    print("\nRunning: mfa", " ".join(arguments), flush=True)

    with (RECORDS / log_name).open("w", encoding="utf-8") as log:
        process = subprocess.Popen(
            command,
            env=environment,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )

        for line in process.stdout:
            print(line, end="", flush=True)
            log.write(line)
            log.flush()

        exit_code = process.wait()

    if exit_code != 0:
        raise RuntimeError(
            f"MFA command failed with exit code {exit_code}. "
            "Share the complete output; do not continue."
        )

for resource_type in ("acoustic", "dictionary"):
    run_mfa(
        ["model", "download", resource_type, "english_us_arpa"],
        f"english_{resource_type}_download.log",
    )

    run_mfa(
        ["model", "inspect", resource_type, "english_us_arpa"],
        f"english_{resource_type}_inspection.log",
    )

# Preserve the downloaded resource files, excluding MFA working databases.
source_directory = MFA_DATA / "pretrained_models"
if not source_directory.is_dir():
    raise RuntimeError(
        "Expected resource directory was not found. "
        "Share the output before proceeding."
    )

saved_directory = BASE / "alignment_resources/mfa/pretrained_models"
saved_files = []

for source in sorted(source_directory.rglob("*")):
    if not source.is_file():
        continue

    relative = source.relative_to(source_directory)
    destination = saved_directory / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)

    saved_files.append({
        "relative_path": str(relative),
        "size_bytes": destination.stat().st_size,
        "sha256": hashlib.sha256(destination.read_bytes()).hexdigest(),
    })

if not saved_files:
    raise RuntimeError("No alignment resource files were found to save.")

record = {
    "resource_name": "english_us_arpa",
    "local_mfa_root": str(MFA_DATA),
    "saved_resource_directory": str(saved_directory),
    "files": saved_files,
    "corpus_alignment_completed": False,
}

(RECORDS / "english_alignment_resources.json").write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("\nEnglish resource download and inspection: PASSED")
print("Resources saved:", saved_directory)
print("No corpus aligned; no FastSpeech 2 training performed.")

from pathlib import Path
import hashlib
import json
import shutil
import zipfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
RECORDS = BASE / "project/reproducibility"
MFA_DATA = Path("/content/fastspeech2_tools/mfa_data")
SOURCE = MFA_DATA / "pretrained_models"
DESTINATION = BASE / "alignment_resources/mfa/pretrained_models"

if not SOURCE.is_dir():
    raise FileNotFoundError(
        "Downloaded resource directory is missing. Share this error."
    )

resources = sorted(
    path for path in SOURCE.rglob("*")
    if path.is_file() and "english_us_arpa" in path.name.lower()
)

print("=== DOWNLOADED ENGLISH RESOURCES ===")
for path in resources:
    print(path.relative_to(SOURCE), "| bytes:", path.stat().st_size)

dictionaries = [
    path for path in resources if path.suffix.lower() == ".dict"
]
acoustic_archives = [
    path for path in resources
    if path.suffix.lower() == ".zip"
    and "acoustic" in path.relative_to(SOURCE).parts
]

if len(dictionaries) != 1 or len(acoustic_archives) != 1:
    raise RuntimeError(
        "Expected one dictionary and one acoustic archive. "
        "Share the file listing above before proceeding."
    )

dictionary = dictionaries[0]
line_count = 0
preview = []

with dictionary.open(encoding="utf-8-sig") as file:
    for line in file:
        if line.strip() and not line.lstrip().startswith("#"):
            line_count += 1
            if len(preview) < 8:
                preview.append(line.rstrip("\n"))

if line_count == 0:
    raise RuntimeError("Dictionary contains no non-comment entries.")

print("\n=== DICTIONARY FILE CHECK ===")
print("Non-comment entries:", line_count)
print("First entries; repr makes tabs visible:")
for line in preview:
    print(repr(line))

print("\n=== ACOUSTIC ARCHIVE CHECK ===")
with zipfile.ZipFile(acoustic_archives[0]) as archive:
    bad_member = archive.testzip()
    if bad_member is not None:
        raise RuntimeError(f"Archive integrity error: {bad_member}")

    print("ZIP integrity: PASSED")
    print("Archive members:", archive.namelist())

    metadata_files = [
        name for name in archive.namelist()
        if Path(name).name in ("meta.yaml", "meta.yml", "meta.json")
    ]
    for name in metadata_files:
        print(f"\n--- {name} ---")
        print(archive.read(name).decode("utf-8"))

saved_files = []
for source in resources:
    relative = source.relative_to(SOURCE)
    destination = DESTINATION / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)

    saved_files.append({
        "relative_path": str(relative),
        "size_bytes": destination.stat().st_size,
        "sha256": hashlib.sha256(destination.read_bytes()).hexdigest(),
    })

record = {
    "resource_name": "english_us_arpa",
    "local_mfa_root": str(MFA_DATA),
    "saved_resource_directory": str(DESTINATION),
    "local_dictionary_path": str(dictionary),
    "local_acoustic_archive_path": str(acoustic_archives[0]),
    "files": saved_files,
    "dictionary_noncomment_entries": line_count,
    "dictionary_cli_inspection": "failed_inside_MFA",
    "direct_file_checks": "PASSED",
    "dictionary_phone_compatibility": "pending",
    "corpus_alignment_completed": False,
}

(RECORDS / "english_alignment_resources.json").write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("\nDirect resource checks and saving: PASSED")
print("Resources saved:", DESTINATION)
print("Dictionary compatibility and actual alignment remain unverified.")

from pathlib import Path
import json
import subprocess
import sys
import zipfile

RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)
REPO = Path("/content/FastSpeech2_reference")

resources = json.loads(
    (RECORDS / "english_alignment_resources.json").read_text(
        encoding="utf-8"
    )
)

dictionary_path = Path(resources["local_dictionary_path"])
acoustic_path = Path(resources["local_acoustic_archive_path"])

with zipfile.ZipFile(acoustic_path) as archive:
    metadata_names = [
        name for name in archive.namelist()
        if Path(name).name == "meta.json"
    ]
    if len(metadata_names) != 1:
        raise RuntimeError("Expected exactly one acoustic metadata file.")

    acoustic = json.loads(
        archive.read(metadata_names[0]).decode("utf-8")
    )

# Read the actual repository symbol list in a fresh process.
symbol_check = subprocess.run(
    [
        sys.executable, "-c",
        "import json; from text.symbols import symbols; "
        "print(json.dumps(symbols))",
    ],
    cwd=REPO,
    capture_output=True,
    text=True,
)

if symbol_check.returncode != 0:
    print(symbol_check.stderr)
    raise RuntimeError("Could not load repository symbols.")

symbols = set(json.loads(symbol_check.stdout))
repository_phones = {
    symbol[1:] for symbol in symbols if symbol.startswith("@")
}

dictionary_phones = set()
malformed = []
entry_count = 0

def is_number(value):
    try:
        float(value)
        return True
    except ValueError:
        return False

with dictionary_path.open(encoding="utf-8-sig") as file:
    for line_number, line in enumerate(file, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue

        fields = line.split()

        # Skip optional numeric probability/correction fields.
        phone_start = 1
        while phone_start < len(fields) and is_number(fields[phone_start]):
            phone_start += 1

        phones = fields[phone_start:]
        if not phones:
            malformed.append(line_number)
            continue

        dictionary_phones.update(phones)
        entry_count += 1

acoustic_phones = set(acoustic["phone_mapping"]) - {"<eps>"}
missing_acoustic = sorted(dictionary_phones - acoustic_phones)

# Silence handling must be checked separately from ordinary phones.
silence_phones = {"sil", "sp", "spn"}
missing_repository = sorted(
    dictionary_phones - silence_phones - repository_phones
)

report = {
    "dictionary_entries_checked": entry_count,
    "malformed_entry_count": len(malformed),
    "malformed_line_examples": malformed[:10],
    "dictionary_phone_count": len(dictionary_phones),
    "dictionary_phones": sorted(dictionary_phones),
    "phones_missing_from_acoustic_model": missing_acoustic,
    "ordinary_phones_missing_from_repository": missing_repository,
    "repository_silence_symbol_support": {
        phone: f"@{phone}" in symbols for phone in sorted(silence_phones)
    },
    "acoustic_feature_sample_rate": acoustic["features"]["sample_frequency"],
}

output_path = RECORDS / "english_phone_compatibility.json"
output_path.write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(report, indent=2))
print("\nReport saved:", output_path)

if malformed or missing_acoustic or missing_repository:
    print("Compatibility review required. Share the output.")
else:
    print("Dictionary/acoustic/repository phone inventory check: PASSED")

print("No corpus aligned; no source files modified.")

from pathlib import Path
from collections import Counter, defaultdict
import json
import re

import pyarrow.parquet as pq

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
CORPUS = Path("/content/fastspeech2_alignment/english_smoke/corpus")

resources = json.loads(
    (RECORDS / "english_alignment_resources.json").read_text(
        encoding="utf-8"
    )
)
download = json.loads(
    (RECORDS / "svarah_local_shards.json").read_text(encoding="utf-8")
)

# Dictionary vocabulary only; pronunciation probabilities are not needed here.
vocabulary = set()
with Path(resources["local_dictionary_path"]).open(
    encoding="utf-8-sig"
) as file:
    for line in file:
        fields = line.split()
        if fields and not line.lstrip().startswith("#"):
            vocabulary.add(fields[0].lower())

with (ROOT / "English/manifests/train_candidate_with_groups.jsonl").open(
    encoding="utf-8"
) as file:
    training = [json.loads(line) for line in file if line.strip()]

chosen = []
for row in training:
    if not 3 <= row["duration_seconds"] <= 8:
        continue

    # Smoke-test normalization only.
    # Exclude numbers/non-ASCII text rather than silently rewriting them.
    if not row["text"].isascii() or re.search(r"\d", row["text"]):
        continue

    words = re.findall(r"[a-z]+(?:'[a-z]+)*", row["text"].lower())
    if 5 <= len(words) <= 20 and all(word in vocabulary for word in words):
        entry = dict(row)
        entry["alignment_text"] = " ".join(words)
        chosen.append(entry)

    if len(chosen) == 5:
        break

if len(chosen) != 5:
    raise RuntimeError("Could not find five suitable smoke-test clips.")

# Keep this directory limited to the selected smoke-test inputs.
expected_files = set()
for row in chosen:
    stem = f"svarah_{row['index']:06d}"
    folder = CORPUS / row["conditioning_group"]
    expected_files.update({folder / f"{stem}.wav", folder / f"{stem}.lab"})

if CORPUS.exists():
    unexpected = {
        path for path in CORPUS.rglob("*") if path.is_file()
    } - expected_files
    if unexpected:
        raise RuntimeError(
            "Smoke corpus contains unexpected files. Share this error."
        )

# Locate selected records inside the pinned shards.
chosen_by_index = {row["index"]: row for row in chosen}
targets = defaultdict(dict)
local_counts = Counter()

with (RECORDS / "svarah_audio_audit.jsonl").open(encoding="utf-8") as file:
    for line in file:
        row = json.loads(line)
        local_index = local_counts[row["shard"]]
        local_counts[row["shard"]] += 1

        if row["index"] in chosen_by_index:
            targets[row["shard"]][local_index] = chosen_by_index[row["index"]]

written = []

for shard in download["files"]:
    wanted = dict(targets.get(shard["filename"], {}))
    if not wanted:
        continue

    offset = 0
    parquet = pq.ParquetFile(shard["local_path"])

    for batch in parquet.iter_batches(batch_size=8, columns=["audio_filepath"]):
        matching = [
            index for index in wanted
            if offset <= index < offset + batch.num_rows
        ]

        if matching:
            batch_rows = batch.to_pylist()

            for index in sorted(matching):
                row = wanted.pop(index)
                audio = batch_rows[index - offset]["audio_filepath"]

                if audio["path"] != row["original_path"]:
                    raise RuntimeError("Selected audio path mismatch.")

                folder = CORPUS / row["conditioning_group"]
                folder.mkdir(parents=True, exist_ok=True)
                stem = f"svarah_{row['index']:06d}"

                (folder / f"{stem}.wav").write_bytes(audio["bytes"])
                (folder / f"{stem}.lab").write_text(
                    row["alignment_text"], encoding="utf-8"
                )
                written.append(row)

        offset += batch.num_rows
        if not wanted:
            break

    if wanted:
        raise RuntimeError("Some selected recordings were not found.")

if len(written) != 5:
    raise RuntimeError("Expected exactly five exported clips.")

record = {
    "corpus_directory": str(CORPUS),
    "clips": sorted(written, key=lambda row: row["index"]),
    "purpose": "alignment_smoke_test_only",
    "audio_resampled": False,
}

(RECORDS / "english_alignment_smoke_inputs.json").write_text(
    json.dumps(record, indent=2, ensure_ascii=False), encoding="utf-8"
)

print("=== EXPORTED SMOKE-TEST INPUTS ===")
for row in record["clips"]:
    print(
        f"Index {row['index']} | {row['duration_seconds']:.2f}s | "
        f"{row['conditioning_group']}"
    )
    print("Alignment text:", row["alignment_text"])

print("\nFive WAV/LAB pairs prepared: PASSED")
print("Corpus:", CORPUS)
print("No alignment or training performed yet.")

