from pathlib import Path
import json
import math
import subprocess
import sys

import tgt

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
RECORDS = BASE / "project/reproducibility"
REPO = Path("/content/FastSpeech2_reference")

run_record = json.loads(
    (RECORDS / "english_alignment_smoke_run.json").read_text(
        encoding="utf-8"
    )
)
inputs = json.loads(
    (RECORDS / "english_alignment_smoke_inputs.json").read_text(
        encoding="utf-8"
    )
)

directory = Path(run_record["saved_textgrid_directory"])
textgrids = sorted(directory.rglob("*.TextGrid"))

if len(textgrids) != 5:
    raise RuntimeError("Expected five saved TextGrids.")

symbol_result = subprocess.run(
    [
        sys.executable, "-c",
        "import json; from text.symbols import symbols; "
        "print(json.dumps(symbols))",
    ],
    cwd=REPO,
    capture_output=True,
    text=True,
    check=True,
)
symbols = set(json.loads(symbol_result.stdout))

source_clips = {
    f"svarah_{row['index']:06d}": row
    for row in inputs["clips"]
}

sample_rate = 22050
hop_length = 256
silence_labels = {"", "sil", "sp", "spn"}
reports = []

for path in textgrids:
    grid = tgt.io.read_textgrid(
        str(path), include_empty_intervals=True
    )

    phone_tiers = [
        name for name in grid.get_tier_names()
        if name.lower() == "phones"
        or name.lower().endswith(" - phones")
    ]

    if len(phone_tiers) != 1:
        raise RuntimeError(
            f"{path.name}: expected one phones tier; "
            f"found {grid.get_tier_names()}"
        )

    intervals = list(
        grid.get_tier_by_name(phone_tiers[0]).intervals
    )
    if not intervals:
        raise RuntimeError(f"{path.name}: empty phone tier.")

    for interval in intervals:
        if not (
            math.isfinite(interval.start_time)
            and math.isfinite(interval.end_time)
            and interval.end_time > interval.start_time
        ):
            raise RuntimeError(f"{path.name}: invalid phone interval.")

    for previous, current in zip(intervals, intervals[1:]):
        if abs(current.start_time - previous.end_time) > 1e-5:
            raise RuntimeError(
                f"{path.name}: gap or overlap between phone intervals."
            )

    # Mirror upstream trimming of leading/trailing silence.
    speech_indices = [
        i for i, interval in enumerate(intervals)
        if interval.text not in silence_labels
    ]
    if not speech_indices:
        raise RuntimeError(f"{path.name}: no ordinary speech phones.")

    kept = intervals[speech_indices[0]:speech_indices[-1] + 1]
    phones = [
        interval.text if interval.text else "sp"
        for interval in kept
    ]

    unknown = sorted({
        phone for phone in phones if f"@{phone}" not in symbols
    })

    # Quantize absolute boundaries, then subtract adjacent boundaries.
    durations = [
        round(interval.end_time * sample_rate / hop_length)
        - round(interval.start_time * sample_rate / hop_length)
        for interval in kept
    ]

    if unknown or any(duration < 0 for duration in durations):
        raise RuntimeError(
            f"{path.name}: unknown phones={unknown} "
            "or negative frame duration."
        )

    start = kept[0].start_time
    end = kept[-1].end_time
    source = source_clips[path.stem]

    if start < -1e-5 or end > source["duration_seconds"] + 0.02:
        raise RuntimeError(f"{path.name}: boundaries exceed source audio.")

    expected_frames = (
        round(end * sample_rate / hop_length)
        - round(start * sample_rate / hop_length)
    )
    assert sum(durations) == expected_frames

    report = {
        "file": path.name,
        "tier_names": grid.get_tier_names(),
        "phone_count": len(phones),
        "unknown_phones": unknown,
        "speech_start_seconds": start,
        "speech_end_seconds": end,
        "total_duration_frames": sum(durations),
        "zero_frame_phone_count": sum(d == 0 for d in durations),
        "spn_count": phones.count("spn"),
        "phone_preview": phones[:20],
        "duration_frame_preview": durations[:20],
    }
    reports.append(report)
    print(json.dumps(report, indent=2))

output_path = RECORDS / "english_alignment_smoke_duration_checks.json"
output_path.write_text(
    json.dumps(reports, indent=2), encoding="utf-8"
)

print("\nFive TextGrid structural/frame-duration checks: PASSED")
print("Report saved:", output_path)
print("Boundary accuracy still requires visual/listening inspection.")
print("Actual mel-length consistency remains to be tested.")

from pathlib import Path
import json
import sys

import librosa
import numpy as np
import pyworld
import yaml

REPO = Path("/content/FastSpeech2_reference")
RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from audio.stft import TacotronSTFT
from audio.tools import get_mel_from_wav

inputs = json.loads(
    (RECORDS / "english_alignment_smoke_inputs.json").read_text(
        encoding="utf-8"
    )
)
alignment_checks = json.loads(
    (RECORDS / "english_alignment_smoke_duration_checks.json").read_text(
        encoding="utf-8"
    )
)
by_name = {
    Path(item["file"]).stem: item for item in alignment_checks
}

with (REPO / "config/LJSpeech/preprocess.yaml").open(
    encoding="utf-8"
) as file:
    settings = yaml.safe_load(file)["preprocessing"]

sr = settings["audio"]["sampling_rate"]
hop = settings["stft"]["hop_length"]

print("Constructing STFT...", flush=True)
stft = TacotronSTFT(
    filter_length=settings["stft"]["filter_length"],
    hop_length=hop,
    win_length=settings["stft"]["win_length"],
    n_mel_channels=settings["mel"]["n_mel_channels"],
    sampling_rate=sr,
    mel_fmin=settings["mel"]["mel_fmin"],
    mel_fmax=settings["mel"]["mel_fmax"],
)

reports = []

for clip in inputs["clips"]:
    stem = f"svarah_{clip['index']:06d}"
    check = by_name[stem]

    wav_path = (
        Path(inputs["corpus_directory"])
        / clip["conditioning_group"]
        / f"{stem}.wav"
    )

    # Explicit resampling; source file remains unchanged.
    waveform, loaded_sr = librosa.load(
        str(wav_path), sr=sr, mono=True
    )
    assert loaded_sr == sr

    start = check["speech_start_seconds"]
    end = check["speech_end_seconds"]
    waveform = np.ascontiguousarray(
        waveform[int(start * sr):int(end * sr)],
        dtype=np.float32,
    )

    mel, energy = get_mel_from_wav(waveform, stft)
    required_frames = check["total_duration_frames"]

    f0, times = pyworld.dio(
        waveform.astype(np.float64),
        sr,
        frame_period=hop / sr * 1000,
    )
    f0 = pyworld.stonemask(
        waveform.astype(np.float64), f0, times, sr
    )

    report = {
        "clip": stem,
        "required_duration_frames": required_frames,
        "raw_mel_frames": mel.shape[1],
        "raw_energy_frames": len(energy),
        "raw_f0_frames": len(f0),
        "mel_minus_required_frames": mel.shape[1] - required_frames,
        "voiced_frames": int(np.count_nonzero(f0[:required_frames] > 0)),
    }
    print(json.dumps(report, indent=2), flush=True)

    if min(mel.shape[1], len(energy), len(f0)) < required_frames:
        raise RuntimeError(
            f"{stem}: acoustic features are shorter than duration targets. "
            "Share this output; do not pad or change durations yet."
        )

    # Upstream-style truncation of surplus acoustic frames.
    mel = mel[:, :required_frames]
    energy = energy[:required_frames]
    f0 = f0[:required_frames]

    assert mel.shape == (80, required_frames)
    assert len(energy) == len(f0) == required_frames
    assert np.isfinite(mel).all()
    assert np.isfinite(energy).all()
    assert np.isfinite(f0).all()
    assert np.count_nonzero(f0 > 0) > 1

    report["feature_length_and_finiteness_checks"] = "PASSED"
    reports.append(report)

output = RECORDS / "english_alignment_acoustic_consistency.json"
output.write_text(
    json.dumps(reports, indent=2), encoding="utf-8"
)

print("\nFive-clip acoustic consistency check: PASSED")
print("Report saved:", output)
print("No normalization statistics fitted; no model trained.")

from pathlib import Path
from collections import Counter
import json
import re
import sys

REPO = Path("/content/FastSpeech2_reference")
ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "English/manifests"

if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from text.cleaners import english_cleaners

resources = json.loads(
    (RECORDS / "english_alignment_resources.json").read_text(
        encoding="utf-8"
    )
)

vocabulary = set()
with Path(resources["local_dictionary_path"]).open(
    encoding="utf-8-sig"
) as file:
    for line in file:
        fields = line.split()
        if fields and not line.lstrip().startswith("#"):
            vocabulary.add(fields[0].lower())

unknown_words = Counter()
unhandled_characters = Counter()
examples = []
prepared = {}
empty_records = []

for split in ("train", "validation"):
    source = MANIFESTS / f"{split}_candidate_with_groups.jsonl"
    with source.open(encoding="utf-8") as file:
        rows = [json.loads(line) for line in file if line.strip()]

    output_rows = []

    for row in rows:
        cleaned = english_cleaners(row["text"])

        # Audit characters before reducing punctuation to word boundaries.
        # Unexpected characters will require review.
        residual = re.sub(
            r"""[a-z\s'.,!?;:"()\[\]{}\-/]""",
            "",
            cleaned,
        )
        unhandled_characters.update(residual)

        words = re.findall(r"[a-z]+(?:'[a-z]+)*", cleaned)
        alignment_text = " ".join(words)

        if not alignment_text:
            empty_records.append(row["index"])

        unknown_words.update(
            word for word in words if word not in vocabulary
        )

        entry = dict(row)
        entry["cleaned_text_candidate"] = cleaned
        entry["alignment_text_candidate"] = alignment_text
        output_rows.append(entry)

        if len(examples) < 5 and cleaned != row["text"]:
            examples.append({
                "original": row["text"],
                "alignment_candidate": alignment_text,
            })

    prepared[split] = output_rows

report = {
    "status": "candidate_normalization_requires_review",
    "train_records": len(prepared["train"]),
    "validation_records": len(prepared["validation"]),
    "empty_alignment_text_indices": empty_records,
    "unhandled_characters": dict(unhandled_characters),
    "unknown_word_types": len(unknown_words),
    "unknown_word_occurrences": sum(unknown_words.values()),
    "unknown_words": dict(unknown_words.most_common()),
    "normalization_examples": examples,
}

for split, rows in prepared.items():
    path = MANIFESTS / f"{split}_alignment_text_candidate.jsonl"
    with path.open("w", encoding="utf-8") as file:
        for row in rows:
            file.write(json.dumps(row, ensure_ascii=False) + "\n")

(RECORDS / "english_vocabulary_audit.json").write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("=== ENGLISH VOCABULARY AUDIT ===")
print("Training records:", report["train_records"])
print("Validation records:", report["validation_records"])
print("Empty alignment text:", empty_records)
print("Unhandled characters:", dict(unhandled_characters))
print("Unknown word types:", len(unknown_words))
print("Unknown word occurrences:", sum(unknown_words.values()))

print("\n=== FIRST 30 UNKNOWN WORDS ===")
for word, count in unknown_words.most_common(30):
    print(f"{word}: {count}")

print("\n=== NORMALIZATION EXAMPLES ===")
print(json.dumps(examples, indent=2, ensure_ascii=False))

print("\nCandidate manifests and vocabulary report saved.")
print("Original transcripts preserved; no full-corpus alignment performed.")

from pathlib import Path
from collections import defaultdict
import json

MANIFESTS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/English/manifests"
)

symbols_to_check = ("+", "%", "&", "@", "_")
examples = defaultdict(list)
record_counts = {symbol: 0 for symbol in symbols_to_check}

for split in ("train", "validation"):
    path = MANIFESTS / f"{split}_alignment_text_candidate.jsonl"

    with path.open(encoding="utf-8") as file:
        for line in file:
            row = json.loads(line)
            cleaned = row["cleaned_text_candidate"]

            for symbol in symbols_to_check:
                if symbol not in cleaned:
                    continue

                record_counts[symbol] += 1

                if len(examples[symbol]) < 4:
                    position = cleaned.find(symbol)
                    examples[symbol].append({
                        "split": split,
                        "audit_index": row["index"],
                        "original_text": row["text"],
                        "cleaned_context": cleaned[
                            max(0, position - 80):position + 81
                        ],
                    })

print("=== SPECIAL-SYMBOL CONTEXTS ===")

for symbol in symbols_to_check:
    print(f"\nSYMBOL: {symbol!r}")
    print("Records containing it:", record_counts[symbol])
    print(json.dumps(examples[symbol], indent=2, ensure_ascii=False))

print("\nInspection complete. No files changed.")

