from pathlib import Path
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

corpus = Path("/content/fastspeech2_alignment/english_full/corpus/train")
output = Path("/content/fastspeech2_alignment/english_full/aligned/train")
work = Path("/content/fastspeech2_alignment/english_full/work/train")

with (ROOT / "English/manifests/train_alignment_selected.jsonl").open(
    encoding="utf-8"
) as file:
    selected = [json.loads(line) for line in file if line.strip()]

missing = []

for row in selected:
    stem = f"svarah_{row['index']:06d}"
    expected = output / row["conditioning_group"] / f"{stem}.TextGrid"

    if not expected.is_file():
        missing.append({
            "audit_index": row["index"],
            "stem": stem,
            "conditioning_group": row["conditioning_group"],
            "duration_seconds": row["duration_seconds"],
            "original_text": row["text"],
            "alignment_text": row["alignment_text_candidate"],
            "expected_textgrid": str(expected),
        })

print("=== MISSING EXPECTED TEXTGRIDS ===")
print(json.dumps(missing, indent=2, ensure_ascii=False))

# Check whether files were exported under a different directory.
print("\n=== ALTERNATE LOCATIONS ===")
for row in missing:
    matches = list(output.rglob(f"{row['stem']}.TextGrid"))
    print(row["stem"], ":", [str(path) for path in matches])

missing_stems = {row["stem"] for row in missing}

print("\n=== DIAGNOSTIC FILES ===")
diagnostic_paths = []

for directory in (output, work):
    if not directory.exists():
        continue

    for path in sorted(directory.rglob("*")):
        if not path.is_file():
            continue

        name = path.name.lower()
        if path.suffix.lower() in (".csv", ".log", ".txt") and any(
            term in name
            for term in (
                "unalign", "align", "error", "oov",
                "missing", "failed", "likelihood"
            )
        ):
            diagnostic_paths.append(path)
            print(path, "| bytes:", path.stat().st_size)

print("\n=== RELEVANT DIAGNOSTIC LINES ===")
printed = 0

for path in diagnostic_paths:
    with path.open(encoding="utf-8", errors="replace") as file:
        for number, line in enumerate(file, start=1):
            lower = line.lower()
            relevant = (
                any(stem in line for stem in missing_stems)
                or "error" in lower
                or "failed" in lower
                or "did not successfully" in lower
            )

            if relevant:
                print(f"{path.name}:{number}: {line.rstrip()[:1200]}")
                printed += 1
                if printed >= 60:
                    break

    if printed >= 60:
        print("Diagnostic preview limited to 60 matching lines.")
        break

report_path = RECORDS / "english_missing_training_alignments.json"
report_path.write_text(
    json.dumps(missing, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\nMissing-clip report saved:", report_path)
print("Existing TextGrids and manifests unchanged.")

from pathlib import Path
import json
import os
import shutil
import subprocess
import tarfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
RECORDS = BASE / "project/reproducibility"

setup = json.loads(
    (RECORDS / "mfa_environment.json").read_text(encoding="utf-8")
)
resources = json.loads(
    (RECORDS / "english_alignment_resources.json").read_text(
        encoding="utf-8"
    )
)
dictionary = json.loads(
    (RECORDS / "english_extended_dictionary.json").read_text(
        encoding="utf-8"
    )
)
missing = json.loads(
    (RECORDS / "english_missing_training_alignments.json").read_text(
        encoding="utf-8"
    )
)

original_corpus = Path(
    "/content/fastspeech2_alignment/english_full/corpus/train"
)
retry_root = Path("/content/fastspeech2_alignment/english_retry")
retry_corpus = retry_root / "corpus"
retry_output = retry_root / "aligned"

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = resources["local_mfa_root"]
environment["NO_COLOR"] = "1"

mfa_command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa",
]

# Verify these options exist in the installed CLI before using them.
help_result = subprocess.run(
    [*mfa_command, "align", "--help"],
    env=environment,
    capture_output=True,
    text=True,
    check=True,
)
help_text = help_result.stdout + help_result.stderr

if "--beam" not in help_text or "--retry_beam" not in help_text:
    print(help_text)
    raise RuntimeError(
        "Expected beam options were not found. Share this help output."
    )

expected_files = set()
for row in missing:
    folder = retry_corpus / row["conditioning_group"]
    for suffix in (".wav", ".lab"):
        expected_files.add(folder / f"{row['stem']}{suffix}")

if retry_corpus.exists():
    unexpected = {
        path for path in retry_corpus.rglob("*") if path.is_file()
    } - expected_files
    if unexpected:
        raise RuntimeError("Unexpected files in retry corpus. Stop here.")

for row in missing:
    relative = Path(row["conditioning_group"]) / row["stem"]
    destination_folder = retry_corpus / relative.parent
    destination_folder.mkdir(parents=True, exist_ok=True)

    for suffix in (".wav", ".lab"):
        source = original_corpus / f"{relative}{suffix}"
        destination = retry_corpus / f"{relative}{suffix}"
        if not source.is_file():
            raise FileNotFoundError(source)
        shutil.copyfile(source, destination)

command = [
    *mfa_command, "align",
    str(retry_corpus),
    dictionary["extended_dictionary_path"],
    resources["local_acoustic_archive_path"],
    str(retry_output),
    "--temporary_directory", str(retry_root / "work"),
    "--num_jobs", "2",
    "--beam", "100",
    "--retry_beam", "400",
    "--clean",
    "--overwrite",
]

print(f"Retrying {len(missing)} clips with wider search...", flush=True)
log_path = RECORDS / "english_missing_alignment_retry.log"

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()
    exit_code = process.wait()

recovered = []
still_missing = []

for row in missing:
    expected = (
        retry_output / row["conditioning_group"]
        / f"{row['stem']}.TextGrid"
    )
    if expected.is_file():
        recovered.append(row["audit_index"])
    else:
        still_missing.append(row["audit_index"])

archive_path = None
if retry_output.exists():
    archive_path = (
        BASE / "alignment_resources/English"
        / "missing_alignment_retry_output.tar.gz"
    )
    temporary = archive_path.with_suffix(".gz.partial")
    with tarfile.open(temporary, "w:gz") as archive:
        archive.add(retry_output, arcname="retry_output")
    temporary.replace(archive_path)

report = {
    "exit_code": exit_code,
    "beam": 100,
    "retry_beam": 400,
    "recovered_indices": recovered,
    "still_missing_indices": still_missing,
    "retry_output_directory": str(retry_output),
    "output_archive": str(archive_path) if archive_path else None,
    "transcripts_changed": False,
    "merged_into_main_output": False,
    "alignment_quality_verified": False,
    "time_reading_review_required": [2053],
}

(RECORDS / "english_missing_alignment_retry.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== TARGETED RETRY RESULT ===")
print(json.dumps(report, indent=2))
print("Original successful alignments remain unchanged.")
print("Recovered alignments require inspection before merging.")

