from pathlib import Path
import json
import os
import shutil
import subprocess
import tarfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"

def read_record(name):
    return json.loads(
        (RECORDS / name).read_text(encoding="utf-8")
    )

setup = read_record("mfa_environment.json")
resources = read_record("english_alignment_resources.json")
dictionary = read_record("english_extended_dictionary.json")
previous = read_record("english_validation_alignment_run.json")

with (ROOT / "English/manifests/validation_alignment_selected.jsonl").open(
    encoding="utf-8"
) as file:
    selected = [json.loads(line) for line in file if line.strip()]

missing_ids = set(previous["missing_indices"])
missing = [row for row in selected if row["index"] in missing_ids]

if not missing or len(missing) != len(missing_ids):
    raise RuntimeError("Missing-clip records are empty or inconsistent.")

source_corpus = Path(
    "/content/fastspeech2_alignment/english_full/corpus/validation"
)
retry_root = Path("/content/fastspeech2_alignment/english_validation_retry")
corpus = retry_root / "corpus"
output = retry_root / "aligned"

print("\n=== CLIPS TO RETRY ===")
for row in missing:
    print(f"\nIndex {row['index']} | {row['duration_seconds']:.3f} seconds")
    print("Original:", row["text"])
    print("Alignment text:", row["alignment_text_candidate"])

expected_files = set()
for row in missing:
    stem = f"svarah_{row['index']:06d}"
    for suffix in (".wav", ".lab"):
        expected_files.add(
            corpus / row["conditioning_group"] / f"{stem}{suffix}"
        )

if corpus.exists():
    unexpected = {
        path for path in corpus.rglob("*") if path.is_file()
    } - expected_files
    if unexpected:
        raise RuntimeError("Unexpected files in retry corpus. Stop here.")

for row in missing:
    stem = f"svarah_{row['index']:06d}"
    for suffix in (".wav", ".lab"):
        relative = Path(row["conditioning_group"]) / f"{stem}{suffix}"
        source = source_corpus / relative
        destination = corpus / relative

        if not source.is_file():
            raise FileNotFoundError(source)

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)

config_path = RECORDS / "english_validation_alignment_retry.yaml"
config_path.write_text(
    "beam: 100\nretry_beam: 400\n",
    encoding="utf-8",
)

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = resources["local_mfa_root"]

command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa", "align",
    str(corpus),
    dictionary["extended_dictionary_path"],
    resources["local_acoustic_archive_path"],
    str(output),
    "--config_path", str(config_path),
    "--temporary_directory", str(retry_root / "work"),
    "--num_jobs", "2",
    "--clean",
    "--overwrite",
]

log_path = RECORDS / "english_validation_alignment_retry.log"
print("\nStarting targeted retry...", flush=True)

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()
    exit_code = process.wait()

recovered, still_missing = [], []
for row in missing:
    path = (
        output / row["conditioning_group"]
        / f"svarah_{row['index']:06d}.TextGrid"
    )
    if path.is_file():
        recovered.append(row["index"])
    else:
        still_missing.append(row["index"])

archive_path = None
if output.exists():
    archive_dir = BASE / "alignment_resources/English"
    archive_dir.mkdir(parents=True, exist_ok=True)
    archive_path = archive_dir / "validation_retry_output.tar.gz"
    temporary = archive_dir / "validation_retry_output.tar.gz.partial"

    with tarfile.open(temporary, "w:gz") as archive:
        archive.add(output, arcname="validation_retry")
    temporary.replace(archive_path)

report = {
    "exit_code": exit_code,
    "beam": 100,
    "retry_beam": 400,
    "recovered_indices": recovered,
    "still_missing_indices": still_missing,
    "retry_output_directory": str(output),
    "output_archive": str(archive_path) if archive_path else None,
    "transcripts_changed": False,
    "merged_into_main_output": False,
    "alignment_quality_verified": False,
}

(RECORDS / "english_validation_alignment_retry.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== VALIDATION RETRY RESULT ===")
print(json.dumps(report, indent=2))
print("Original validation outputs remain unchanged.")

print("STEP 4.20 — VALIDATION ALIGNMENT AUDIT", flush=True)

from pathlib import Path
import json
import math
import shutil
import tarfile

import tgt

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "English/manifests"

retry = json.loads(
    (RECORDS / "english_validation_alignment_retry.json").read_text(
        encoding="utf-8"
    )
)
compatibility = json.loads(
    (RECORDS / "english_phone_compatibility.json").read_text(
        encoding="utf-8"
    )
)

main_dir = Path(
    "/content/fastspeech2_alignment/english_full/aligned/validation"
)
retry_dir = Path(retry["retry_output_directory"])
recovered = set(retry["recovered_indices"])

allowed = set(compatibility["dictionary_phones"]) | {"sil", "sp", "spn"}
silence = {"", "sil", "sp", "spn"}

with (MANIFESTS / "validation_alignment_selected.jsonl").open(
    encoding="utf-8"
) as file:
    selected = [json.loads(line) for line in file if line.strip()]

ready, failures, warnings, copies = [], [], [], []

for row in selected:
    relative = (
        Path(row["conditioning_group"])
        / f"svarah_{row['index']:06d}.TextGrid"
    )
    is_retry = row["index"] in recovered
    source = (retry_dir if is_retry else main_dir) / relative

    try:
        grid = tgt.io.read_textgrid(
            str(source), include_empty_intervals=True
        )
        tiers = [
            name for name in grid.get_tier_names()
            if name.lower() == "phones"
            or name.lower().endswith(" - phones")
        ]
        if len(tiers) != 1:
            raise ValueError("Expected one phones tier")

        intervals = list(grid.get_tier_by_name(tiers[0]).intervals)
        if not intervals:
            raise ValueError("Empty phone tier")

        for interval in intervals:
            if not (
                math.isfinite(interval.start_time)
                and math.isfinite(interval.end_time)
                and interval.end_time > interval.start_time
            ):
                raise ValueError("Invalid interval")

        for previous, current in zip(intervals, intervals[1:]):
            if abs(current.start_time - previous.end_time) > 1e-5:
                raise ValueError("Gap or overlap between intervals")

        speech = [
            i for i, interval in enumerate(intervals)
            if interval.text not in silence
        ]
        if not speech:
            raise ValueError("No ordinary speech phones")

        kept = intervals[speech[0]:speech[-1] + 1]
        phones = [interval.text or "sp" for interval in kept]
        unknown = sorted(set(phones) - allowed)
        if unknown:
            raise ValueError(f"Unsupported phones: {unknown}")

        start, end = kept[0].start_time, kept[-1].end_time
        if start < -1e-5 or end > row["duration_seconds"] + 0.02:
            raise ValueError("Boundaries exceed source audio")

        durations = [
            round(interval.end_time * 22050 / 256)
            - round(interval.start_time * 22050 / 256)
            for interval in kept
        ]
        if min(durations) < 0 or sum(durations) <= 0:
            raise ValueError("Invalid frame durations")

        zero_count = sum(value == 0 for value in durations)
        long_count = sum(
            interval.end_time - interval.start_time > 0.5
            for interval in kept if interval.text not in silence
        )

        if zero_count or long_count or "spn" in phones:
            warnings.append({
                "audit_index": row["index"],
                "zero_frame_phones": zero_count,
                "ordinary_phones_over_half_second": long_count,
                "spn_count": phones.count("spn"),
            })

        entry = dict(row)
        entry.update({
            "textgrid_path": str(main_dir / relative),
            "alignment_source": "wider_search_retry" if is_retry else "initial",
            "speech_start_seconds": start,
            "speech_end_seconds": end,
            "duration_frames": sum(durations),
            "alignment_status": "structural_checks_passed",
            "perceptual_boundary_accuracy_verified": False,
        })
        ready.append(entry)

        if is_retry:
            copies.append((source, main_dir / relative))

    except Exception as error:
        failures.append({
            "audit_index": row["index"],
            "error": f"{type(error).__name__}: {error}",
        })

report = {
    "selected_clips": len(selected),
    "structurally_valid_clips": len(ready),
    "structurally_valid_source_hours": sum(
        row["duration_seconds"] for row in ready
    ) / 3600,
    "hard_failures": failures,
    "warning_clip_count": len(warnings),
    "warnings": warnings,
    "retry_outputs_to_merge": len(copies),
    "retry_clips_requiring_listening_review": sorted(recovered),
}

(RECORDS / "english_validation_alignment_audit.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(
    {key: value for key, value in report.items() if key != "warnings"},
    indent=2,
))

if failures or len(ready) != 630:
    raise RuntimeError(
        "Audit needs review. Nothing merged; share the output."
    )

for source, destination in copies:
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)

with (MANIFESTS / "validation_alignment_available.jsonl").open(
    "w", encoding="utf-8"
) as file:
    for row in ready:
        file.write(json.dumps(row, ensure_ascii=False) + "\n")

archive_dir = BASE / "alignment_resources/English"
archive_path = archive_dir / "validation_alignment_merged.tar.gz"
temporary = archive_dir / "validation_alignment_merged.tar.gz.partial"

print("Saving merged validation archive...", flush=True)
with tarfile.open(temporary, "w:gz") as archive:
    archive.add(main_dir, arcname="validation")
temporary.replace(archive_path)

print("\nSTEP 4.20: PASSED")
print("Validation alignment manifest and archive saved.")
print("Structural checks do not verify transcript or boundary accuracy.")
print("No TTS normalization statistics fitted; no TTS model trained.")

print("STEP 4.21 — ALIGNMENT QUALITY REVIEW", flush=True)

