from pathlib import Path
import ast

REPO = Path("/content/FastSpeech2_reference")
RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

source_path = REPO / "preprocessor/preprocessor.py"
source = source_path.read_text(encoding="utf-8")
tree = ast.parse(source)

wanted = {
    "__init__",
    "process_utterance",
    "get_alignment",
    "remove_outlier",
    "normalize",
}

sections = []

for node in tree.body:
    if isinstance(node, ast.ClassDef) and node.name == "Preprocessor":
        for method in node.body:
            if isinstance(method, ast.FunctionDef) and method.name in wanted:
                section = (
                    f"\n=== Preprocessor.{method.name} ===\n"
                    + ast.get_source_segment(source, method)
                )
                sections.append(section)
                print(section)

if len(sections) != len(wanted):
    raise RuntimeError(
        "Some expected methods were not found. Share this output."
    )

output = RECORDS / "upstream_preprocessor_methods.txt"
output.write_text("\n".join(sections), encoding="utf-8")

