report = json.loads(report_path.read_text(encoding="utf-8"))
with manifest_path.open(encoding="utf-8") as file:
    extracted = [json.loads(line) for line in file if line.strip()]

if report["attempted_clips"] != 627:
    raise RuntimeError("Unexpected validation input count.")
if len(extracted) != report["successful_clips"]:
    raise RuntimeError("Extraction manifest/report count mismatch.")

# Archive only successful validation arrays, not training or smoke outputs.
archive_directory = ROOT.parent / "processed_data/English"
archive_directory.mkdir(parents=True, exist_ok=True)
archive_path = archive_directory / "validation_raw_features.tar.gz"
temporary = archive_directory / "validation_raw_features.tar.gz.partial"

print("Saving validation recovery archive...", flush=True)

with tarfile.open(temporary, "w:gz") as archive:
    archive.add(report_path, arcname=report_path.name)
    archive.add(manifest_path, arcname=manifest_path.name)

    for row in extracted:
        speaker = row["conditioning_group"]
        basename = f"svarah_{row['index']:06d}"

        for feature in ("mel", "pitch", "energy", "duration"):
            relative = Path(feature) / f"{speaker}-{feature}-{basename}.npy"
            archive.add(output / relative, arcname=str(relative))

temporary.replace(archive_path)

(RECORDS / "english_validation_raw_extraction_report.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== VALIDATION EXTRACTION SUMMARY ===")
print(json.dumps(report, indent=2))
print("Recovery archive:", archive_path)

if exit_code != 0 or report["rejected_clips"]:
    print("\nRejections require review. Do not rerun the full extraction yet.")
else:
    print("\nSTEP 4.29: PASSED")

print("Training features unchanged.")
print("No normalization statistics fitted; no TTS model trained.")

print("STEP 4.30 — DIAGNOSE VALIDATION CLIP 3754")

from pathlib import Path
import json
import sys

import librosa
import numpy as np
import pyworld
import tgt
from IPython.display import Audio, display

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

repo = "/content/FastSpeech2_reference"
if repo not in sys.path:
    sys.path.insert(0, repo)

from preprocessor.preprocessor import Preprocessor

with (
    ROOT / "English/manifests/validation_alignment_reviewed_candidate.jsonl"
).open(encoding="utf-8") as file:
    row = next(
        record for record in (
            json.loads(line) for line in file if line.strip()
        )
        if record["index"] == 3754
    )

wav_path = (
    Path("/content/fastspeech2_alignment/english_full/corpus/validation")
    / row["conditioning_group"]
    / "svarah_003754.wav"
)

grid = tgt.io.read_textgrid(
    row["textgrid_path"], include_empty_intervals=True
)

processor = Preprocessor.__new__(Preprocessor)
processor.sampling_rate = 22050
processor.hop_length = 256

phones, durations, start, end = processor.get_alignment(
    grid.get_tier_by_name("phones")
)

waveform, sr = librosa.load(str(wav_path), sr=22050, mono=True)
trimmed = np.ascontiguousarray(
    waveform[int(start * sr):int(end * sr)],
    dtype=np.float64,
)

report = {
    "audit_index": 3754,
    "original_text": row["text"],
    "alignment_text": row["alignment_text_candidate"],
    "speech_start_seconds": start,
    "speech_end_seconds": end,
    "phone_count": len(phones),
    "duration_frames": int(sum(durations)),
    "trimmed_samples": len(trimmed),
    "rejection_conditions": [],
}

if start >= end:
    report["rejection_conditions"].append("invalid_speech_boundaries")

if len(trimmed) == 0:
    report["rejection_conditions"].append("empty_trimmed_audio")
elif start < end:
    f0, times = pyworld.dio(
        trimmed,
        sr,
        frame_period=256 / sr * 1000,
    )
    f0 = pyworld.stonemask(trimmed, f0, times, sr)
    f0 = f0[:sum(durations)]

    report["voiced_f0_frames"] = int(np.count_nonzero(f0 > 0))
    report["total_f0_frames"] = len(f0)

    if np.count_nonzero(f0 > 0) <= 1:
        report["rejection_conditions"].append(
            "insufficient_voiced_frames_for_upstream_pitch_processing"
        )

print(json.dumps(report, indent=2, ensure_ascii=False))

(RECORDS / "english_rejected_validation_clip_3754_diagnosis.json").write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\nFull source recording:")
display(Audio(waveform, rate=sr, normalize=False))

print("Diagnosis saved. Successful features remain unchanged.")

print("STEP 4.31 — TRAINING-ONLY NORMALIZATION STATISTICS")

from pathlib import Path
import json

import numpy as np
import yaml
from sklearn.preprocessing import StandardScaler

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
CONFIG = ROOT / "English/config.yaml"

config = yaml.safe_load(CONFIG.read_text(encoding="utf-8"))
raw_dir = Path(config["path"]["preprocessed_path"])

diagnosis = json.loads(
    (RECORDS / "english_rejected_validation_clip_3754_diagnosis.json")
    .read_text(encoding="utf-8")
)
if (
    "insufficient_voiced_frames_for_upstream_pitch_processing"
    not in diagnosis["rejection_conditions"]
):
    raise RuntimeError("Unexpected rejection diagnosis. Stop here.")

(RECORDS / "english_validation_feature_exclusions.json").write_text(
    json.dumps([{
        "audit_index": 3754,
        "reason": "WORLD returned no voiced frames in the aligned segment.",
        "action": "excluded_from_pitch_conditioned_validation_features",
        "source_files_preserved": True,
    }], indent=2),
    encoding="utf-8",
)

def read_manifest(split):
    with (raw_dir / f"{split}_extracted.jsonl").open(
        encoding="utf-8"
    ) as file:
        return [json.loads(line) for line in file if line.strip()]

training = read_manifest("train")
validation = read_manifest("validation")

if len(training) != 3135 or len(validation) != 626:
    raise RuntimeError("Unexpected extracted-manifest counts.")

# Verify actual successful feature sets remain separate.
for field in (
    "index", "alignment_text_candidate",
    "recording_group_key", "waveform_sha256",
):
    if not {row[field] for row in training}.isdisjoint(
        {row[field] for row in validation}
    ):
        raise RuntimeError(f"Train/validation overlap: {field}")

missing_groups = (
    {row["conditioning_group"] for row in validation}
    - {row["conditioning_group"] for row in training}
)
if missing_groups:
    raise RuntimeError(
        f"Validation groups absent from training: {sorted(missing_groups)}"
    )

scalers = {
    "pitch": StandardScaler(),
    "energy": StandardScaler(),
}
counts = {"pitch": 0, "energy": 0}
zero_duration_positions = 0

for row in training:
    speaker = row["conditioning_group"]
    basename = f"svarah_{row['index']:06d}"

    duration = np.load(
        raw_dir / "duration" / f"{speaker}-duration-{basename}.npy"
    )
    valid_positions = duration > 0
    zero_duration_positions += int(np.count_nonzero(~valid_positions))

    for feature, scaler in scalers.items():
        values = np.load(
            raw_dir / feature / f"{speaker}-{feature}-{basename}.npy"
        )

        if values.shape != duration.shape or not np.isfinite(values).all():
            raise RuntimeError(f"Invalid {feature} array: {basename}")

        values = values[valid_positions]
        if values.size:
            scaler.partial_fit(values.reshape(-1, 1))
            counts[feature] += int(values.size)

statistics = {}

for feature, scaler in scalers.items():
    if counts[feature] == 0:
        raise RuntimeError(f"No training observations for {feature}.")

    mean = float(scaler.mean_[0])
    std = float(np.sqrt(scaler.var_[0]))

    if not np.isfinite(mean) or not np.isfinite(std) or std <= 0:
        raise RuntimeError(f"Invalid training statistics for {feature}.")

    statistics[feature] = {
        "mean": mean,
        "std": std,
        "training_phone_observations": counts[feature],
    }

record = {
    "fit_split": "train",
    "training_clips": len(training),
    "validation_clips_not_used_for_fitting": len(validation),
    "feature_level": "phoneme",
    "zero_duration_positions_excluded": zero_duration_positions,
    "outlier_filter": "none",
    "statistics": statistics,
    "raw_arrays_modified": False,
}

output_path = RECORDS / "english_training_normalization_statistics.json"
output_path.write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print(json.dumps(record, indent=2))
print("\nStatistics saved:", output_path)
print("Raw feature arrays unchanged.")
print("STEP 4.31: PASSED")

