from pathlib import Path
import json
import tarfile

import numpy as np
import yaml

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

config = yaml.safe_load(
    (ROOT / "English/config.yaml").read_text(encoding="utf-8")
)
run = json.loads(
    (RECORDS / "english_normalization_run.json").read_text(
        encoding="utf-8"
    )
)
fit = json.loads(
    (RECORDS / "english_training_normalization_statistics.json").read_text(
        encoding="utf-8"
    )
)

raw = Path(config["path"]["preprocessed_path"])
processed = Path(run["output_directory"])
speakers = json.loads(
    (processed / "speakers.json").read_text(encoding="utf-8")
)

split_rows = {}
train_moments = {
    feature: {"count": 0, "sum": 0.0, "sum_squares": 0.0}
    for feature in ("pitch", "energy")
}
summary = {}

for split, metadata_name in (("train", "train.txt"), ("validation", "val.txt")):
    with (raw / f"{split}_extracted.jsonl").open(encoding="utf-8") as file:
        rows = [json.loads(line) for line in file if line.strip()]
    split_rows[split] = rows

    metadata = (processed / metadata_name).read_text(
        encoding="utf-8"
    ).splitlines()

    if len(metadata) != len(rows):
        raise ValueError(f"{split}: metadata count mismatch")

    for row, line in zip(rows, metadata):
        fields = line.split("|")
        basename = f"svarah_{row['index']:06d}"
        speaker = row["conditioning_group"]

        if len(fields) != 4 or fields[:2] != [basename, speaker]:
            raise ValueError(f"Invalid metadata: {basename}")
        if speaker not in speakers:
            raise ValueError(f"Missing conditioning group: {speaker}")

        phones = fields[2].strip("{}").split()

        def feature_path(root, feature):
            return root / feature / f"{speaker}-{feature}-{basename}.npy"

        duration = np.load(feature_path(processed, "duration"))
        mel = np.load(feature_path(processed, "mel"))

        if not np.array_equal(
            duration, np.load(feature_path(raw, "duration"))
        ):
            raise ValueError(f"Duration changed: {basename}")
        if not np.array_equal(mel, np.load(feature_path(raw, "mel"))):
            raise ValueError(f"Mel changed: {basename}")
        if mel.shape != (int(duration.sum()), 80):
            raise ValueError(f"Mel/duration mismatch: {basename}")
        if len(duration) != len(phones) or np.any(duration < 0):
            raise ValueError(f"Phone/duration mismatch: {basename}")
        if not np.isfinite(mel).all():
            raise ValueError(f"Non-finite mel: {basename}")

        valid = duration > 0

        for feature in ("pitch", "energy"):
            original = np.load(feature_path(raw, feature))
            actual = np.load(feature_path(processed, feature))
            stats = fit["statistics"][feature]

            expected = (
                (original.astype(np.float64) - stats["mean"]) / stats["std"]
            )
            expected[~valid] = 0.0
            expected = expected.astype(np.float32)

            if actual.shape != duration.shape:
                raise ValueError(f"Shape mismatch: {basename}/{feature}")
            if not np.isfinite(actual).all():
                raise ValueError(f"Non-finite values: {basename}/{feature}")
            if not np.allclose(actual, expected, rtol=1e-6, atol=1e-6):
                raise ValueError(f"Normalization mismatch: {basename}/{feature}")

            if split == "train":
                values = actual[valid].astype(np.float64)
                moment = train_moments[feature]
                moment["count"] += len(values)
                moment["sum"] += float(values.sum())
                moment["sum_squares"] += float(np.square(values).sum())

    summary[split] = {"verified_clips": len(rows)}

for field in (
    "index", "alignment_text_candidate",
    "recording_group_key", "waveform_sha256",
):
    if not {r[field] for r in split_rows["train"]}.isdisjoint(
        {r[field] for r in split_rows["validation"]}
    ):
        raise ValueError(f"Split overlap: {field}")

normalized_moments = {}
for feature, moment in train_moments.items():
    mean = moment["sum"] / moment["count"]
    variance = moment["sum_squares"] / moment["count"] - mean ** 2
    std = float(np.sqrt(max(variance, 0.0)))

    if abs(mean) > 1e-5 or abs(std - 1.0) > 1e-5:
        raise ValueError(f"Unexpected normalized training moments: {feature}")

    normalized_moments[feature] = {"mean": mean, "std": std}

print("Array, normalization, metadata, and separation checks: PASSED")
print(json.dumps(normalized_moments, indent=2))

archive_dir = ROOT.parent / "processed_data/English"
archive_dir.mkdir(parents=True, exist_ok=True)
archive_path = archive_dir / "english_processed.tar.gz"
temporary = archive_dir / "english_processed.tar.gz.partial"

print("Saving processed-data archive...", flush=True)
with tarfile.open(temporary, "w:gz") as archive:
    archive.add(processed, arcname="english_processed")
temporary.replace(archive_path)

report = {
    "checks": "PASSED",
    "splits": summary,
    "normalized_training_moments": normalized_moments,
    "conditioning_groups": len(speakers),
    "processed_directory": str(processed),
    "recovery_archive": str(archive_path),
    "archive_size_bytes": archive_path.stat().st_size,
    "perceptual_quality_review_complete": False,
}

(RECORDS / "english_processed_verification.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== PROCESSED DATA SUMMARY ===")
print(json.dumps(report, indent=2))
print("\nSTEP 4.33: PASSED")
print("No TTS model trained.")

print("STEP 4.34 — ENGLISH MODEL CONFIGURATION")

from pathlib import Path
import inspect
import json
import sys

import yaml

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
REPO = Path("/content/FastSpeech2_reference")
CONFIG_DIR = ROOT / "English/config"
RECORDS = ROOT / "reproducibility"

verification = json.loads(
    (RECORDS / "english_processed_verification.json").read_text(
        encoding="utf-8"
    )
)
if verification["checks"] != "PASSED":
    raise RuntimeError("Processed data verification has not passed.")

def load_yaml(path):
    return yaml.safe_load(path.read_text(encoding="utf-8"))

preprocess = load_yaml(ROOT / "English/config.yaml")
preprocess.pop("workflow", None)
