from pathlib import Path
import json
import random
import sys

import numpy as np
import torch
import yaml

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
REPO = Path("/content/FastSpeech2_reference")
CONFIG_DIR = ROOT / "English/config"

if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from dataset import Dataset
from model import FastSpeech2, FastSpeech2Loss
from utils.tools import to_device

if not torch.cuda.is_available():
    raise RuntimeError("GPU unavailable. Stop and check the runtime.")

random.seed(42)
np.random.seed(42)
torch.manual_seed(42)
torch.cuda.manual_seed_all(42)

def load_config(name):
    return yaml.safe_load(
        (CONFIG_DIR / name).read_text(encoding="utf-8")
    )

preprocess_config = load_config("preprocess.yaml")
model_config = load_config("model.yaml")
train_config = load_config("train.yaml")

dataset = Dataset(
    "train.txt",
    preprocess_config,
    train_config,
    sort=True,
    drop_last=False,
)

if len(dataset) != 3135:
    raise RuntimeError(f"Unexpected training dataset size: {len(dataset)}")

# Use the repository's own collation and device-conversion functions.
samples = [dataset[index] for index in range(4)]
groups = dataset.collate_fn(samples)

if not groups:
    raise RuntimeError("Collation produced no batches.")

device = torch.device("cuda")
batch = to_device(groups[0], device)

print("Dataset clips:", len(dataset))
print("Batch utterances:", len(batch[0]))
print("Batch source lengths:", batch[4].detach().cpu().tolist())
print("Batch mel lengths:", batch[7].detach().cpu().tolist())

model = FastSpeech2(preprocess_config, model_config).to(device)
criterion = FastSpeech2Loss(preprocess_config, model_config).to(device)

model.train()
model.zero_grad(set_to_none=True)
torch.cuda.reset_peak_memory_stats()

print("Running forward pass...", flush=True)

predictions = model(*(batch[2:]))
losses = criterion(batch, predictions)

loss_names = (
    "total", "mel", "postnet_mel", "pitch", "energy", "duration"
)

if len(losses) != len(loss_names):
    raise RuntimeError(f"Unexpected loss output count: {len(losses)}")

loss_values = {}
for name, loss in zip(loss_names, losses):
    if not torch.isfinite(loss).all():
        raise RuntimeError(f"Non-finite {name} loss.")
    loss_values[name] = float(loss.detach().cpu())

print("Losses:", json.dumps(loss_values, indent=2))
print("Running backward pass...", flush=True)

losses[0].backward()

gradient_tensors = 0
nonzero_gradient_tensors = 0

for name, parameter in model.named_parameters():
    if parameter.grad is None:
        continue

    gradient_tensors += 1
    if not torch.isfinite(parameter.grad).all():
        raise RuntimeError(f"Non-finite gradients: {name}")
    if torch.count_nonzero(parameter.grad).item() > 0:
        nonzero_gradient_tensors += 1

if nonzero_gradient_tensors == 0:
    raise RuntimeError("No nonzero gradients were produced.")

report = {
    "dataset_clips": len(dataset),
    "batch_size": len(batch[0]),
    "losses": loss_values,
    "parameters": sum(p.numel() for p in model.parameters()),
    "gradient_tensors": gradient_tensors,
    "nonzero_gradient_tensors": nonzero_gradient_tensors,
    "peak_gpu_memory_gib": torch.cuda.max_memory_allocated() / 1024**3,
    "optimizer_updates": 0,
    "checkpoint_saved": False,
    "status": "PASSED",
}

(ROOT / "reproducibility/english_model_smoke_test.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== MODEL SMOKE TEST ===")
print(json.dumps(report, indent=2))

# Release this disposable, randomly initialized model.
model.zero_grad(set_to_none=True)
del predictions, losses, batch, groups, samples, criterion, model
torch.cuda.empty_cache()

print("\nSTEP 4.35: PASSED")
print("No model training run or optimizer update performed.")

