from pathlib import Path
import json
import re
import shutil
import subprocess

RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

executable = shutil.which("espeak-ng")
if executable is None:
    raise RuntimeError("espeak-ng is missing.")

# Individual words: suitable for inspecting dictionary pronunciation units.
words = [
    "తెలుగు",
    "తాడుపై",
    "పట్టు",
    "చీరను",
    "ధరించి",
    "వచ్చింది",
]

results = []

for word in words:
    result = subprocess.run(
        [executable, "-q", "-v", "te", "--ipa", "--sep=|", word],
        capture_output=True,
        text=True,
        check=True,
    )

    raw = result.stdout.strip()
    if not raw or "|" not in raw:
        raise RuntimeError(
            f"Expected separated phonemes for {word!r}; got {raw!r}"
        )

    # Split only on explicit separators or whitespace.
    # Keep length/aspiration marks attached to their phoneme.
    tokens_with_stress = [
        token for token in re.split(r"[|\s]+", raw) if token
    ]

    # Proposed baseline: remove eSpeak-generated stress marks.
    # Telugu vowel length and aspiration marks remain intact.
    tokens = [
        token.replace("ˈ", "").replace("ˌ", "")
        for token in tokens_with_stress
    ]
    tokens = [token for token in tokens if token]

    record = {
        "word": word,
        "raw_separated_ipa": raw,
        "tokens_with_stress": tokens_with_stress,
        "candidate_tokens_without_stress": tokens,
        "contains_joiner": any(
            "\u200d" in token or "\u200c" in token for token in tokens
        ),
    }
    results.append(record)
    print(json.dumps(record, indent=2, ensure_ascii=False))

output_path = RECORDS / "telugu_phoneme_boundary_checks.json"
output_path.write_text(
    json.dumps(results, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\nBoundary-output check: PASSED")
print("Saved:", output_path)
print("Tokenization policy remains provisional.")
print("No full lexicon, alignment, or model training performed.")

print("STEP 5.3 — TELUGU TEXT AUDIT")

from pathlib import Path
from collections import Counter, defaultdict
import json
import re
import unicodedata

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
MANIFESTS = ROOT / "Telugu/manifests"
RECORDS = ROOT / "reproducibility"

examples = defaultdict(list)
counts = defaultdict(Counter)
vocabularies = {}
normalized_texts = {}

def word_candidate(text):
    # Candidate word boundaries only; original text remains untouched.
    text = unicodedata.normalize("NFC", text)
    return re.sub(
        r"\s+", " ",
        "".join(
            " " if unicodedata.category(c).startswith("P") else c
            for c in text
        ),
    ).strip()

for split in ("train", "validation"):
    with (MANIFESTS / f"{split}_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        rows = [json.loads(line) for line in file if line.strip()]

    vocabulary = Counter()
    comparison_texts = set()

    for row in rows:
        text = row["text"]
        normalized = word_candidate(text)
        vocabulary.update(normalized.split())
        comparison_texts.add(normalized)

        flags = []

        if not normalized:
            flags.append("empty_candidate_text")
        if re.search(r"[A-Za-z]", text):
            flags.append("latin_letters")
        if any(c.isdecimal() for c in text):
            flags.append("digits")
        if any(unicodedata.category(c) == "Cf" for c in text):
            flags.append("format_characters")
        if any(
            unicodedata.category(c) == "Cc" and not c.isspace()
            for c in text
        ):
            flags.append("non_whitespace_control_characters")

        other = {
            c for c in text
            if not (
                "\u0c00" <= c <= "\u0c7f"
                or c.isspace()
                or unicodedata.category(c).startswith("P")
                or c.isdecimal()
                or ("A" <= c <= "Z")
                or ("a" <= c <= "z")
            )
        }
        if other:
            flags.append("other_characters")
            counts[split].update({
                f"character_U+{ord(c):04X}": text.count(c)
                for c in other
            })

        for flag in flags:
            counts[split][flag] += 1
            key = f"{split}/{flag}"
            if len(examples[key]) < 3:
                examples[key].append({
                    "audit_index": row["index"],
                    "text": text,
                    "text_repr": repr(text),
                })

    counts[split]["clips"] = len(rows)
    counts[split]["unique_candidate_words"] = len(vocabulary)
    vocabularies[split] = vocabulary
    normalized_texts[split] = comparison_texts

report = {
    "counts": {split: dict(value) for split, value in counts.items()},
    "candidate_normalized_text_overlap": len(
        normalized_texts["train"] & normalized_texts["validation"]
    ),
    "validation_word_types_absent_from_training": len(
        set(vocabularies["validation"]) - set(vocabularies["train"])
    ),
    "examples": dict(examples),
    "transcripts_modified": False,
}

output_path = RECORDS / "telugu_text_audit.json"
output_path.write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print(json.dumps(report, indent=2, ensure_ascii=False))
print("\nAudit saved:", output_path)
print("No lexicon generated or alignment performed.")

print("STEP 5.4 — TELUGU TEXT FRONTEND")

from pathlib import Path
import importlib.util
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
TELUGU = ROOT / "Telugu"
MANIFESTS = TELUGU / "manifests"
RECORDS = ROOT / "reproducibility"

frontend_source = r'''
"""Conservative Telugu normalization and eSpeak pronunciation candidates."""
import re
import subprocess
import unicodedata

def normalize_training_text(text):
    text = unicodedata.normalize("NFC", text)
    unsupported = sorted({
        c for c in text
        if not (
            "\u0c00" <= c <= "\u0c7f"
            or c.isspace()
            or unicodedata.category(c).startswith("P")
        )
    })
    if unsupported:
        raise ValueError(
            "Characters requiring review: "
            + ", ".join(f"U+{ord(c):04X}" for c in unsupported)
        )

    text = "".join(
        " " if unicodedata.category(c).startswith("P") else c
        for c in text
    )
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        raise ValueError("Empty normalized text")
    return text

def phonemize_word(word):
    result = subprocess.run(
        ["espeak-ng", "-q", "-v", "te", "--ipa", "--sep=|", word],
        capture_output=True, text=True, check=True,
    )
    raw = result.stdout.strip()
    if not raw:
        raise ValueError(f"Empty pronunciation for {word!r}")

    tokens = [
        token.replace("ˈ", "").replace("ˌ", "")
        for token in re.split(r"[|\s]+", raw) if token
    ]
    tokens = [token for token in tokens if token]

    if not tokens or any(
        "\u200d" in token or "\u200c" in token for token in tokens
    ):
        raise ValueError(f"Unexpected pronunciation encoding: {raw!r}")
    return tokens
'''

frontend_path = TELUGU / "text_frontend.py"
if frontend_path.exists():
    raise RuntimeError(
        "text_frontend.py already exists. Share this output "
        "before replacing it."
    )

compile(frontend_source, str(frontend_path), "exec")
frontend_path.write_text(frontend_source, encoding="utf-8")

spec = importlib.util.spec_from_file_location(
    "assignment_telugu_frontend", frontend_path
)
frontend = importlib.util.module_from_spec(spec)
spec.loader.exec_module(frontend)

prepared = {}
deferred = []
summary = {}

for split in ("train", "validation"):
    with (MANIFESTS / f"{split}_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        rows = [json.loads(line) for line in file if line.strip()]

    accepted = []

    for row in rows:
        try:
            normalized = frontend.normalize_training_text(row["text"])
        except ValueError as error:
            deferred.append({
                "split": split,
                "audit_index": row["index"],
                "original_text": row["text"],
                "reason": str(error),
                "action": "deferred_for_transcript_review",
            })
            continue

        if row["gender_label"] not in ("female", "male"):
            raise ValueError("Unexpected speaker label.")

        entry = dict(row)
        entry["alignment_text_candidate"] = normalized
        entry["conditioning_group"] = f"telugu_{row['gender_label']}"
        accepted.append(entry)

    prepared[split] = accepted
    summary[split] = {
        "retained_clips": len(accepted),
        "source_hours": sum(
            row["duration_seconds"] for row in accepted
        ) / 3600,
    }

overlap = (
    {row["alignment_text_candidate"] for row in prepared["train"]}
    & {row["alignment_text_candidate"] for row in prepared["validation"]}
)
if overlap:
    raise RuntimeError("Normalization introduced transcript overlap.")

for split, rows in prepared.items():
    with (MANIFESTS / f"{split}_normalized_candidate.jsonl").open(
        "w", encoding="utf-8"
    ) as file:
        for row in rows:
            file.write(json.dumps(row, ensure_ascii=False) + "\n")

report = {
    "splits": summary,
    "deferred": deferred,
    "normalized_transcript_overlap": 0,
    "original_transcripts_preserved": True,
    "pronunciations_verified": False,
}

(RECORDS / "telugu_normalization_selection.json").write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print(json.dumps(report, indent=2, ensure_ascii=False))
print("\nFrontend test — తెలుగు:", frontend.phonemize_word("తెలుగు"))
print("\nSTEP 5.4: PASSED")
print("No full lexicon generated; no alignment or training performed.")

print("STEP 5.5 — TELUGU LEXICON CANDIDATES", flush=True)

from pathlib import Path
from collections import Counter
import hashlib
import importlib.util
import json
import unicodedata

from tqdm.auto import tqdm

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
TELUGU = ROOT / "Telugu"
MANIFESTS = TELUGU / "manifests"
LEXICON = TELUGU / "lexicon"
RECORDS = ROOT / "reproducibility"
LEXICON.mkdir(parents=True, exist_ok=True)

frontend_path = TELUGU / "text_frontend.py"
frontend_hash = hashlib.sha256(frontend_path.read_bytes()).hexdigest()

spec = importlib.util.spec_from_file_location(
    "assignment_telugu_frontend", frontend_path
)
frontend = importlib.util.module_from_spec(spec)
spec.loader.exec_module(frontend)

vocabularies = {}
for split in ("train", "validation"):
    vocabulary = Counter()
    with (MANIFESTS / f"{split}_normalized_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        for line in file:
            row = json.loads(line)
            vocabulary.update(row["alignment_text_candidate"].split())
    vocabularies[split] = vocabulary

words = sorted(
    set(vocabularies["train"]) | set(vocabularies["validation"])
)

cache_path = LEXICON / "pronunciation_candidate_cache.json"
if cache_path.exists():
    saved = json.loads(cache_path.read_text(encoding="utf-8"))
    if saved["frontend_sha256"] != frontend_hash:
        raise RuntimeError("Frontend changed; existing cache needs review.")
    cache = saved["pronunciations"]
else:
    cache = {}

failures = []

def save_cache():
    temporary = cache_path.with_suffix(".json.partial")
    temporary.write_text(
        json.dumps({
            "frontend_sha256": frontend_hash,
            "pronunciations": cache,
        }, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    temporary.replace(cache_path)

for number, word in enumerate(
    tqdm(words, desc="Telugu pronunciation candidates", unit="word"),
    start=1,
):
    if word not in cache:
        try:
            tokens = frontend.phonemize_word(word)

            if any(
                not token
                or any(c.isspace() for c in token)
                or any(c in token for c in ("|", "{", "}"))
                or any(unicodedata.category(c).startswith("C") for c in token)
                for token in tokens
            ):
                raise ValueError("Unexpected phone-token characters")

            cache[word] = tokens
        except Exception as error:
            failures.append({
                "word": word,
                "reason": f"{type(error).__name__}: {error}",
            })

    if number % 250 == 0:
        save_cache()

save_cache()

phone_counts = Counter()
training_phones = set()
validation_phones = set()

for split, vocabulary in vocabularies.items():
    for word, occurrences in vocabulary.items():
        if word not in cache:
            continue
        phones = cache[word]
        phone_counts.update({
            phone: phones.count(phone) * occurrences
            for phone in set(phones)
        })
        if split == "train":
            training_phones.update(phones)
        else:
            validation_phones.update(phones)

candidate_path = LEXICON / "telugu_ipa_candidates.dict"
with candidate_path.open("w", encoding="utf-8") as file:
    for word in words:
        if word in cache:
            file.write(word + "\t" + " ".join(cache[word]) + "\n")

report = {
    "training_word_types": len(vocabularies["train"]),
    "validation_word_types": len(vocabularies["validation"]),
    "combined_word_types": len(words),
    "successful_word_types": sum(word in cache for word in words),
    "failed_word_types": failures,
    "training_phone_types": len(training_phones),
    "combined_phone_types": len(training_phones | validation_phones),
    "phones_absent_from_training_but_present_in_validation": sorted(
        validation_phones - training_phones
    ),
    "phones": sorted(training_phones | validation_phones),
    "frontend_sha256": frontend_hash,
    "pronunciation_accuracy_verified": False,
}

(RECORDS / "telugu_lexicon_candidate_audit.json").write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("\n=== TELUGU LEXICON AUDIT ===")
print(json.dumps(report, indent=2, ensure_ascii=False))

print("\n=== FREQUENT TRAINING-WORD EXAMPLES ===")
for word, count in vocabularies["train"].most_common(15):
    print(word, f"({count})", ":", " ".join(cache.get(word, ["FAILED"])))

print("\nCandidate dictionary:", candidate_path)
print("No repository symbols changed; no alignment or training performed.")

if failures:
    print("Some pronunciations require review before proceeding.")
else:
    print("STEP 5.5 generation: PASSED")

print("STEP 5.6 — TELUGU PHONE COVERAGE REVIEW")

from pathlib import Path
from collections import Counter
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
MANIFESTS = ROOT / "Telugu/manifests"
LEXICON = ROOT / "Telugu/lexicon"
RECORDS = ROOT / "reproducibility"

cache = json.loads(
    (LEXICON / "pronunciation_candidate_cache.json").read_text(
        encoding="utf-8"
    )
)["pronunciations"]

audit = json.loads(
    (RECORDS / "telugu_lexicon_candidate_audit.json").read_text(
        encoding="utf-8"
    )
)

unseen = set(
    audit["phones_absent_from_training_but_present_in_validation"]
)
review_phones = unseen | {"ʲ"}
report = {}

for split in ("train", "validation"):
    with (MANIFESTS / f"{split}_normalized_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        rows = [json.loads(line) for line in file if line.strip()]

    affected = []
    word_counts = Counter()

    for row in rows:
        matches = []

        for word in row["alignment_text_candidate"].split():
            phones = cache[word]
            flagged = sorted(set(phones) & review_phones)

            if flagged:
                matches.append({
                    "word": word,
                    "phones": phones,
                    "review_phones": flagged,
                })
                word_counts[word] += 1

        if matches:
            affected.append({
                "audit_index": row["index"],
                "duration_seconds": row["duration_seconds"],
                "conditioning_group": row["conditioning_group"],
                "text": row["text"],
                "affected_words": matches,
            })

    report[split] = {
        "affected_clip_count": len(affected),
        "affected_word_counts": dict(word_counts),
        "affected_clips": affected,
    }

output = RECORDS / "telugu_phone_coverage_review.json"
output.write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

for split, details in report.items():
    print(f"\n=== {split.upper()} ===")
    print("Affected clips:", details["affected_clip_count"])
    print("Affected words:", json.dumps(
        details["affected_word_counts"], ensure_ascii=False
    ))
    print("First 8 affected clips:")
    print(json.dumps(
        details["affected_clips"][:8],
        indent=2,
        ensure_ascii=False,
    ))

print("\nReview saved:", output)
print("No phones remapped; no recordings moved between splits.")

print("STEP 5.7 — TRAINING-SUPPORTED TELUGU PHONE INVENTORY")

from pathlib import Path
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
MANIFESTS = ROOT / "Telugu/manifests"
LEXICON = ROOT / "Telugu/lexicon"
RECORDS = ROOT / "reproducibility"

cache = json.loads(
    (LEXICON / "pronunciation_candidate_cache.json").read_text(
        encoding="utf-8"
    )
)["pronunciations"]

def read_rows(split):
    with (MANIFESTS / f"{split}_normalized_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        return [json.loads(line) for line in file if line.strip()]

training = read_rows("train")
validation = read_rows("validation")

training_words = {
    word
    for row in training
    for word in row["alignment_text_candidate"].split()
}
training_phones = {
    phone for word in training_words for phone in cache[word]
}

retained_validation = []
deferred = []

for row in validation:
    unsupported_words = []

    for word in row["alignment_text_candidate"].split():
        unseen = sorted(set(cache[word]) - training_phones)
        if unseen:
            unsupported_words.append({
                "word": word,
                "phones_absent_from_training": unseen,
            })

    if unsupported_words:
        deferred.append({
            "audit_index": row["index"],
            "original_text": row["text"],
            "duration_seconds": row["duration_seconds"],
            "affected_words": unsupported_words,
            "reason": "Pronunciation contains phones absent from training.",
            "action": "deferred_from_validation_alignment_candidate",
        })
    else:
        retained_validation.append(row)

# Alphabetic aliases avoid IPA encoding and numeric-stress ambiguity.
phones = sorted(training_phones)
if len(phones) > 26 * 26:
    raise RuntimeError("Phone inventory exceeds alias scheme capacity.")

ipa_to_token = {
    phone: f"TE{chr(65 + i // 26)}{chr(65 + i % 26)}"
    for i, phone in enumerate(phones)
}
token_to_ipa = {token: phone for phone, token in ipa_to_token.items()}

assert len(token_to_ipa) == len(ipa_to_token)

retained_words = training_words | {
    word
    for row in retained_validation
    for word in row["alignment_text_candidate"].split()
}

for word in retained_words:
    if set(cache[word]) - training_phones:
        raise RuntimeError(f"Unsupported phone remains in {word!r}")

train_texts = {row["alignment_text_candidate"] for row in training}
val_texts = {
    row["alignment_text_candidate"] for row in retained_validation
}
if train_texts & val_texts:
    raise RuntimeError("Normalized train/validation transcript overlap.")

mapping = {
    "inventory_source": "training_pronunciation_candidates_only",
    "ipa_to_token": ipa_to_token,
    "token_to_ipa": token_to_ipa,
    "stress_marks_removed": True,
    "standalone_palatalization_token_preserved": "ʲ" in ipa_to_token,
    "pronunciation_accuracy_verified": False,
}

(LEXICON / "phone_mapping.json").write_text(
    json.dumps(mapping, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

dictionary_path = LEXICON / "telugu_alignment_candidates.dict"
with dictionary_path.open("w", encoding="utf-8") as file:
    for word in sorted(retained_words):
        tokens = [ipa_to_token[phone] for phone in cache[word]]
        file.write(word + "\t" + " ".join(tokens) + "\n")

for split, rows in (
    ("train", training),
    ("validation", retained_validation),
):
    with (MANIFESTS / f"{split}_alignment_candidate.jsonl").open(
        "w", encoding="utf-8"
    ) as file:
        for row in rows:
            file.write(json.dumps(row, ensure_ascii=False) + "\n")

report = {
    "training_clips": len(training),
    "training_source_hours": sum(
        row["duration_seconds"] for row in training
    ) / 3600,
    "validation_clips": len(retained_validation),
    "validation_source_hours": sum(
        row["duration_seconds"] for row in retained_validation
    ) / 3600,
    "training_phone_types": len(phones),
    "dictionary_word_types": len(retained_words),
    "remaining_validation_phones_absent_from_training": [],
    "deferred_validation_clips": deferred,
    "original_manifests_preserved": True,
    "repository_symbols_modified": False,
}

(RECORDS / "telugu_alignment_inventory_selection.json").write_text(
    json.dumps(report, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print(json.dumps(report, indent=2, ensure_ascii=False))
print("\nPhone mapping examples:")
for phone in phones[:12]:
    print(repr(phone), "->", ipa_to_token[phone])

print("\nDictionary saved:", dictionary_path)
print("STEP 5.7: PASSED")
print("No acoustic aligner or FastSpeech 2 model trained.")

print("STEP 5.8 — EXPORT TELUGU ALIGNMENT INPUTS", flush=True)

from pathlib import Path
import io
import json
import tarfile

import librosa
import numpy as np
import pyarrow.parquet as pq
import soundfile as sf
from tqdm.auto import tqdm

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "Telugu/manifests"

CORPUS = Path("/content/fastspeech2_alignment/telugu_full/corpus")
TARGET_SR = 16000

download = json.loads(
    (RECORDS / "telugu_local_shards.json").read_text(encoding="utf-8")
)

selected = {}
expected_files = set()

for split in ("train", "validation"):
    with (MANIFESTS / f"{split}_alignment_candidate.jsonl").open(
        encoding="utf-8"
    ) as file:
        for line in file:
            row = json.loads(line)
            if row["index"] in selected:
                raise RuntimeError("Duplicate selected audit index.")

            entry = dict(row)
            entry["split"] = split
            selected[row["index"]] = entry

            folder = CORPUS / split / row["conditioning_group"]
            stem = f"telugu_{row['index']:06d}"
            expected_files.update({
                folder / f"{stem}.wav",
                folder / f"{stem}.lab",
            })

if len(selected) != 2240:
    raise RuntimeError(f"Expected 2,240 clips; found {len(selected)}.")

if CORPUS.exists():
    unexpected = {
        path for path in CORPUS.rglob("*") if path.is_file()
    } - expected_files
    if unexpected:
        raise RuntimeError("Unexpected export files. Nothing deleted.")

exported = []
global_index = 0

for shard in download["files"]:
    parquet = pq.ParquetFile(shard["local_path"])
    print(f"\nReading {Path(shard['local_path']).name}", flush=True)

    with tqdm(total=parquet.metadata.num_rows, unit="clip") as progress:
        for batch in parquet.iter_batches(
            batch_size=8, columns=["audio"]
        ):
            for item in batch.to_pylist():
                row = selected.get(global_index)

                if row is not None:
                    audio = item["audio"]
                    if audio["path"] != row["original_path"]:
                        raise RuntimeError(
                            f"Source path mismatch at index {global_index}."
                        )

                    with io.BytesIO(audio["bytes"]) as buffer:
                        waveform, source_sr = sf.read(
                            buffer, dtype="float32", always_2d=True
                        )

                    if waveform.shape[1] != 1:
                        raise RuntimeError("Expected mono source audio.")
                    waveform = waveform[:, 0]

                    if abs(
                        len(waveform) / source_sr - row["duration_seconds"]
                    ) > 0.02:
                        raise RuntimeError("Source duration mismatch.")

                    if source_sr != TARGET_SR:
                        waveform = librosa.resample(
                            waveform,
                            orig_sr=source_sr,
                            target_sr=TARGET_SR,
                        )

                    if not np.isfinite(waveform).all():
                        raise RuntimeError("Non-finite resampled audio.")
                    if np.max(np.abs(waveform)) > 1:
                        raise RuntimeError(
                            "Resampling produced out-of-range samples. "
                            "Share this error before clipping or scaling."
                        )

                    folder = (
                        CORPUS / row["split"] / row["conditioning_group"]
                    )
                    folder.mkdir(parents=True, exist_ok=True)
                    stem = f"telugu_{global_index:06d}"
                    wav_path = folder / f"{stem}.wav"
                    lab_path = folder / f"{stem}.lab"

                    sf.write(wav_path, waveform, TARGET_SR, subtype="PCM_16")
                    lab_path.write_text(
                        row["alignment_text_candidate"], encoding="utf-8"
                    )

                    saved = sf.info(wav_path)
                    if saved.samplerate != TARGET_SR or saved.channels != 1:
                        raise RuntimeError("Exported audio format mismatch.")

                    exported.append({
                        "audit_index": global_index,
                        "split": row["split"],
                        "conditioning_group": row["conditioning_group"],
                        "source_sample_rate": source_sr,
                        "alignment_sample_rate": TARGET_SR,
                        "source_duration_seconds": row["duration_seconds"],
                        "exported_duration_seconds": saved.duration,
                        "wav_path": str(wav_path),
                        "lab_path": str(lab_path),
                    })

                global_index += 1
                progress.update(1)

if global_index != 8576 or len(exported) != len(selected):
    raise RuntimeError("Corpus traversal or export count mismatch.")

counts = {}
for split, expected in (("train", 1880), ("validation", 360)):
    folder = CORPUS / split
    wav_count = len(list(folder.rglob("*.wav")))
    lab_count = len(list(folder.rglob("*.lab")))

    if wav_count != expected or lab_count != expected:
        raise RuntimeError(f"Unexpected {split} WAV/LAB counts.")

    counts[split] = {"wav": wav_count, "lab": lab_count}

archive_dir = BASE / "alignment_resources/Telugu"
archive_dir.mkdir(parents=True, exist_ok=True)
archive_path = archive_dir / "telugu_alignment_inputs.tar.gz"
temporary = archive_dir / "telugu_alignment_inputs.tar.gz.partial"

print("\nSaving recovery archive...", flush=True)
with tarfile.open(temporary, "w:gz") as archive:
    archive.add(CORPUS, arcname="corpus")
temporary.replace(archive_path)

record = {
    "corpus_root": str(CORPUS),
    "alignment_sample_rate": TARGET_SR,
    "counts": counts,
    "recovery_archive": str(archive_path),
    "clips": exported,
}

(RECORDS / "telugu_alignment_inputs.json").write_text(
    json.dumps(record, indent=2), encoding="utf-8"
)

print("\n=== EXPORT COUNTS ===")
print(json.dumps(counts, indent=2))
print("Recovery archive:", archive_path)
print("STEP 5.8: PASSED")
print("No acoustic aligner or TTS model trained.")

import json
import numpy as np

if "waveform" not in globals() or "row" not in globals():
    raise RuntimeError(
        "The failed cell's variables are unavailable. "
        "Tell me whether the runtime restarted."
    )

peak = float(np.max(np.abs(waveform)))

diagnosis = {
    "audit_index": row["index"],
    "conditioning_group": row["conditioning_group"],
    "source_sample_rate": int(source_sr),
    "target_sample_rate": int(TARGET_SR),
    "resampled_peak": peak,
    "samples_outside_pcm_range": int(
        np.count_nonzero(np.abs(waveform) > 1)
    ),
    "total_samples": int(waveform.size),
    "suggested_uniform_gain_to_peak_0_999": (
        0.999 / peak if peak > 1 else 1.0
    ),
}

print(json.dumps(diagnosis, indent=2))
print("No samples clipped or scaled; no files changed.")

