setup = json.loads(
    (RECORDS / "mfa_environment.json").read_text(encoding="utf-8")
)

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = (
    "/content/fastspeech2_tools/mfa_telugu_data"
)
environment["COLUMNS"] = "160"
environment["NO_COLOR"] = "1"

base_command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
]

for command in ("train", "validate"):
    result = subprocess.run(
        [*base_command, "mfa", command, "--help"],
        env=environment,
        capture_output=True,
        text=True,
    )

    text = result.stdout + result.stderr
    (RECORDS / f"mfa_{command}_help.txt").write_text(
        text, encoding="utf-8"
    )

    print(f"\n=== MFA {command.upper()} HELP ===")
    print(text)

    if result.returncode != 0:
        raise RuntimeError(
            f"MFA {command} help failed. Share this output."
        )

# Inspect defaults from the installed MFA version.
inspection_code = r'''
import inspect
from montreal_forced_aligner.acoustic_modeling.trainer import TrainableAligner

print("=== TrainableAligner.__init__ signature ===")
print(inspect.signature(TrainableAligner.__init__))

print("\n=== TrainableAligner.default_training_config ===")
member = inspect.getattr_static(
    TrainableAligner, "default_training_config", None
)

if member is None:
    print("No member with this name; inspect actual installed API next.")
else:
    if isinstance(member, property):
        member = member.fget
    elif isinstance(member, (classmethod, staticmethod)):
        member = member.__func__

    try:
        print(inspect.getsource(member))
    except (TypeError, OSError):
        print(repr(member))
'''

result = subprocess.run(
    [*base_command, "python", "-c", inspection_code],
    env=environment,
    capture_output=True,
    text=True,
)

text = result.stdout + result.stderr
(RECORDS / "mfa_training_defaults_inspection.txt").write_text(
    text, encoding="utf-8"
)
print("\n=== INSTALLED TRAINING DEFAULTS ===")
print(text)

if result.returncode != 0:
    raise RuntimeError(
        "Training-default inspection failed. Share the traceback."
    )

print("\nSTEP 5.9 inspection: PASSED")
print("No validation audio used for fitting; no aligner or TTS model trained.")

