dictionary = ROOT / "Telugu/lexicon/telugu_alignment_candidates.dict"
output = Path("/content/fastspeech2_alignment/telugu_validation_checks")
work = Path("/content/fastspeech2_alignment/telugu_validation_work")

if len(list(corpus.rglob("*.wav"))) != 1880:
    raise RuntimeError("Expected 1,880 training WAV files.")
if len(list(corpus.rglob("*.lab"))) != 1880:
    raise RuntimeError("Expected 1,880 training LAB files.")
if not dictionary.is_file():
    raise FileNotFoundError(dictionary)

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = (
    "/content/fastspeech2_tools/mfa_telugu_data"
)

command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa", "validate",
    str(corpus),
    str(dictionary),
    "--ignore_acoustics",
    "--phone_set", "UNKNOWN",
    "--output_directory", str(output),
    "--temporary_directory", str(work),
    "--num_jobs", "2",
    "--clean",
]

# UNKNOWN prevents treating our opaque aliases as ARPAbet or IPA.
# This option is supported but marked deprecated in the installed CLI.
log_path = RECORDS / "telugu_corpus_dictionary_validation.log"

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )

    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()

    exit_code = process.wait()

print("\nValidation command exit code:", exit_code)

diagnostics = []
if output.exists():
    for path in sorted(output.rglob("*")):
        if not path.is_file():
            continue

        diagnostics.append({
            "path": str(path),
            "size_bytes": path.stat().st_size,
        })
        print("\nDiagnostic file:", path.name)
        print("Size:", path.stat().st_size, "bytes")

        if path.suffix.lower() in (".csv", ".txt") and path.stat().st_size:
            lines = path.read_text(
                encoding="utf-8", errors="replace"
            ).splitlines()
            print("\n".join(lines[:12]))
            if len(lines) > 12:
                print("[Preview limited to 12 lines]")

report = {
    "exit_code": exit_code,
    "corpus_split": "train",
    "expected_training_clips": 1880,
    "acoustic_checks_skipped": True,
    "dictionary_path": str(dictionary),
    "output_directory": str(output),
    "diagnostics": diagnostics,
    "command": command,
    "diagnostics_reviewed": False,
}

(RECORDS / "telugu_corpus_dictionary_validation.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

if exit_code != 0:
    raise RuntimeError(
        "Corpus validation command failed. Share the complete error."
    )

print("\nSTEP 5.10 execution: PASSED")
print("Diagnostics still require review.")
print("No acoustic aligner or TTS model trained.")

