from pathlib import Path
import hashlib
import json
import os
import shutil
import subprocess
import tarfile
import zipfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"

setup = json.loads(
    (RECORDS / "mfa_environment.json").read_text(encoding="utf-8")
)
inputs = json.loads(
    (RECORDS / "telugu_alignment_inputs.json").read_text(
        encoding="utf-8"
    )
)

corpus = Path(inputs["corpus_root"]) / "train"
dictionary = ROOT / "Telugu/lexicon/telugu_training.dict"
config = ROOT / "Telugu/config/mfa_train.yaml"

RUN_ROOT = Path("/content/fastspeech2_alignment/telugu_mfa_training")
model_path = RUN_ROOT / "telugu_aligner.zip"
alignment_output = RUN_ROOT / "aligned"
work = RUN_ROOT / "work"
RUN_ROOT.mkdir(parents=True, exist_ok=True)

if len(list(corpus.rglob("*.wav"))) != 1880:
    raise RuntimeError("Expected 1,880 training WAV files.")
if len(list(corpus.rglob("*.lab"))) != 1880:
    raise RuntimeError("Expected 1,880 training LAB files.")
if not dictionary.is_file() or not config.is_file():
    raise FileNotFoundError("Training dictionary or configuration missing.")

# Avoid unintentionally replacing a completed trained aligner.
if model_path.exists():
    raise RuntimeError(
        "An aligner model already exists at the output path. "
        "Share this message before retraining."
    )

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = "/content/fastspeech2_tools/mfa_telugu_data"

command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa", "train",
    str(corpus),
    str(dictionary),
    str(model_path),
    "--output_directory", str(alignment_output),
    "--config_path", str(config),
    "--phone_set", "UNKNOWN",
    "--temporary_directory", str(work),
    "--num_jobs", "2",
    "--clean",
]

log_path = RECORDS / "telugu_mfa_training.log"

print("Starting training-only MFA acoustic modeling...", flush=True)

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )

    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()

    exit_code = process.wait()

print("\nMFA training exit code:", exit_code)
print("Log saved:", log_path)

save_dir = BASE / "alignment_resources/Telugu"
save_dir.mkdir(parents=True, exist_ok=True)

saved_model = None
model_sha256 = None
archive_integrity = False

if model_path.is_file():
    saved_model = save_dir / "telugu_aligner.zip"
    shutil.copyfile(model_path, saved_model)
    model_sha256 = hashlib.sha256(saved_model.read_bytes()).hexdigest()

    if zipfile.is_zipfile(saved_model):
        with zipfile.ZipFile(saved_model) as archive:
            archive_integrity = archive.testzip() is None

textgrids = (
    sorted(alignment_output.rglob("*.TextGrid"))
    if alignment_output.exists() else []
)

with (
    ROOT / "Telugu/manifests/train_alignment_candidate.jsonl"
).open(encoding="utf-8") as file:
    selected = [json.loads(line) for line in file if line.strip()]

missing = [
    row["index"]
    for row in selected
    if not (
        alignment_output / row["conditioning_group"]
        / f"telugu_{row['index']:06d}.TextGrid"
    ).is_file()
]

output_archive = None
if alignment_output.exists():
    output_archive = save_dir / "telugu_training_alignment_output.tar.gz"
    temporary = save_dir / "telugu_training_alignment_output.tar.gz.partial"

    print("Saving training alignment outputs...", flush=True)
    with tarfile.open(temporary, "w:gz") as archive:
        archive.add(alignment_output, arcname="train")
    temporary.replace(output_archive)

report = {
    "exit_code": exit_code,
    "training_split_only": True,
    "expected_training_clips": 1880,
    "saved_model": str(saved_model) if saved_model else None,
    "model_sha256": model_sha256,
    "model_zip_integrity_passed": archive_integrity,
    "training_textgrid_count": len(textgrids),
    "missing_training_indices": missing,
    "local_alignment_directory": str(alignment_output),
    "alignment_output_archive": (
        str(output_archive) if output_archive else None
    ),
    "command": command,
    "alignment_quality_verified": False,
    "fastspeech2_training_started": False,
}

(RECORDS / "telugu_mfa_training_run.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== TELUGU ALIGNER TRAINING RESULT ===")
print(json.dumps(report, indent=2))

if exit_code != 0:
    print("Training failed. Share the error and traceback; do not reinstall.")
elif not saved_model or not archive_integrity:
    print("Model export needs investigation. Share this report.")
elif missing or len(textgrids) != 1880:
    print("Model exported, but some training alignments need investigation.")
else:
    print("STEP 5.12 execution: PASSED")

print("Validation audio was not used for acoustic-model training.")
print("No FastSpeech 2 model trained.")

