from pathlib import Path
import json
import os
import shutil
import subprocess
import tarfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"

def read_record(name):
    return json.loads(
        (RECORDS / name).read_text(encoding="utf-8")
    )

setup = read_record("mfa_environment.json")
training_run = read_record("telugu_mfa_training_run.json")
inputs = read_record("telugu_alignment_inputs.json")

if (
    training_run["exit_code"] != 0
    or not training_run["model_zip_integrity_passed"]
):
    raise RuntimeError("A successfully exported aligner is required.")

model = Path(training_run["saved_model"])
dictionary = ROOT / "Telugu/lexicon/telugu_training.dict"
source_corpus = Path(inputs["corpus_root"]) / "train"

with (ROOT / "Telugu/manifests/train_alignment_candidate.jsonl").open(
    encoding="utf-8"
) as file:
    rows = [json.loads(line) for line in file if line.strip()]

missing_ids = set(training_run["missing_training_indices"])
missing = [row for row in rows if row["index"] in missing_ids]

if len(missing) != len(missing_ids) or not missing:
    raise RuntimeError("Missing-clip list is empty or inconsistent.")
if not model.is_file():
    raise FileNotFoundError(model)

retry_root = Path("/content/fastspeech2_alignment/telugu_training_retry")
corpus = retry_root / "corpus"
output = retry_root / "aligned"

expected_files = set()
for row in missing:
    stem = f"telugu_{row['index']:06d}"
    for suffix in (".wav", ".lab"):
        expected_files.add(
            corpus / row["conditioning_group"] / f"{stem}{suffix}"
        )

if corpus.exists():
    unexpected = {
        path for path in corpus.rglob("*") if path.is_file()
    } - expected_files
    if unexpected:
        raise RuntimeError("Unexpected retry files. Nothing deleted.")

print("Missing indices:", sorted(missing_ids))
print(
    "Combined missing duration:",
    round(sum(row["duration_seconds"] for row in missing), 3),
    "seconds",
)

for row in missing:
    stem = f"telugu_{row['index']:06d}"
    for suffix in (".wav", ".lab"):
        relative = Path(row["conditioning_group"]) / f"{stem}{suffix}"
        source = source_corpus / relative
        destination = corpus / relative

        if not source.is_file():
            raise FileNotFoundError(source)

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)

config = ROOT / "Telugu/config/mfa_alignment_retry.yaml"
config.write_text("beam: 100\nretry_beam: 400\n", encoding="utf-8")

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = "/content/fastspeech2_tools/mfa_telugu_data"

command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa", "align",
    str(corpus), str(dictionary), str(model), str(output),
    "--config_path", str(config),
    "--temporary_directory", str(retry_root / "work"),
    "--num_jobs", "2",
    "--clean",
    "--overwrite",
]

log_path = RECORDS / "telugu_training_alignment_retry.log"

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()
    exit_code = process.wait()

recovered, still_missing = [], []

for row in missing:
    path = (
        output / row["conditioning_group"]
        / f"telugu_{row['index']:06d}.TextGrid"
    )
    if path.is_file():
        recovered.append(row["index"])
    else:
        still_missing.append(row["index"])

archive_path = None
if output.exists():
    archive_dir = BASE / "alignment_resources/Telugu"
    archive_path = archive_dir / "training_alignment_retry.tar.gz"
    temporary = archive_dir / "training_alignment_retry.tar.gz.partial"

    with tarfile.open(temporary, "w:gz") as archive:
        archive.add(output, arcname="training_retry")
    temporary.replace(archive_path)

report = {
    "exit_code": exit_code,
    "requested_indices": sorted(missing_ids),
    "recovered_indices": recovered,
    "still_missing_indices": still_missing,
    "retry_output_directory": str(output),
    "output_archive": str(archive_path) if archive_path else None,
    "beam": 100,
    "retry_beam": 400,
    "merged_into_main_output": False,
    "alignment_quality_verified": False,
    "new_model_training_performed": False,
}

(RECORDS / "telugu_training_alignment_retry.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== TELUGU RETRY RESULT ===")
print(json.dumps(report, indent=2))
print("Existing alignments and trained model unchanged.")

print("STEP 5.14 — REVIEW UNRESOLVED TELUGU ALIGNMENTS")

