from pathlib import Path
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
MANIFESTS = ROOT / "Telugu/manifests"
RECORDS = ROOT / "reproducibility"

excluded_indices = {191, 913, 2652}

def read_manifest(name):
    with (MANIFESTS / name).open(encoding="utf-8") as file:
        return [json.loads(line) for line in file if line.strip()]

training = read_manifest("train_alignment_candidate.jsonl")
validation = read_manifest("validation_alignment_candidate.jsonl")

by_index = {row["index"]: row for row in training}
if not excluded_indices.issubset(by_index):
    raise RuntimeError("Expected exclusion records are missing. Nothing saved.")

retained = [
    row for row in training if row["index"] not in excluded_indices
]

for field in ("index", "alignment_text_candidate", "waveform_sha256"):
    if not {row[field] for row in retained}.isdisjoint(
        {row[field] for row in validation}
    ):
        raise RuntimeError(f"Train/validation overlap: {field}")

missing_groups = (
    {row["conditioning_group"] for row in validation}
    - {row["conditioning_group"] for row in retained}
)
if missing_groups:
    raise RuntimeError("Validation speaker group absent from training.")

decisions = [
    {
        "audit_index": index,
        "original_text": by_index[index]["text"],
        "duration_seconds": by_index[index]["duration_seconds"],
        "evidence_source": "user_listening_observation",
        "observation": "Speech does not match the transcript.",
        "action": "excluded_from_current_training_candidate",
        "original_files_preserved": True,
    }
    for index in sorted(excluded_indices)
]

output = MANIFESTS / "train_alignment_reviewed_candidate.jsonl"
with output.open("w", encoding="utf-8") as file:
    for row in retained:
        file.write(json.dumps(row, ensure_ascii=False) + "\n")

summary = {
    "input_training_clips": len(training),
    "excluded_indices": sorted(excluded_indices),
    "retained_training_clips": len(retained),
    "retained_training_source_hours": sum(
        row["duration_seconds"] for row in retained
    ) / 3600,
    "validation_clips": len(validation),
    "validation_source_hours": sum(
        row["duration_seconds"] for row in validation
    ) / 3600,
    "overlap_checks": "PASSED",
    "conditioning_group_coverage": "PASSED",
    "recovered_retry_alignments_quality_verified": False,
    "entire_training_set_listening_verified": False,
}

(RECORDS / "telugu_training_listening_exclusions.json").write_text(
    json.dumps(decisions, indent=2, ensure_ascii=False),
    encoding="utf-8",
)
(RECORDS / "telugu_training_reviewed_selection.json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print(json.dumps(summary, indent=2))
print("\nReviewed candidate manifest:", output)
print("Original audio, transcripts, and alignments preserved.")
print("No model retrained.")

