from pathlib import Path
import json
import math
import shutil
import tarfile

import tgt

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "Telugu/manifests"

def read_record(name):
    return json.loads(
        (RECORDS / name).read_text(encoding="utf-8")
    )

training_run = read_record("telugu_mfa_training_run.json")
retry = read_record("telugu_training_alignment_retry.json")

mapping = json.loads(
    (ROOT / "Telugu/lexicon/phone_mapping.json").read_text(
        encoding="utf-8"
    )
)

allowed = set(mapping["token_to_ipa"]) | {"sil", "sp", "spn"}
silence = {"", "sil", "sp", "spn"}

main_dir = Path(training_run["local_alignment_directory"])
retry_dir = Path(retry["retry_output_directory"])
recovered = set(retry["recovered_indices"])

with (MANIFESTS / "train_alignment_reviewed_candidate.jsonl").open(
    encoding="utf-8"
) as file:
    selected = [json.loads(line) for line in file if line.strip()]

ready, failures, warnings, copies = [], [], [], []

for row in selected:
    relative = (
        Path(row["conditioning_group"])
        / f"telugu_{row['index']:06d}.TextGrid"
    )
    is_retry = row["index"] in recovered
    source = (retry_dir if is_retry else main_dir) / relative

    try:
        grid = tgt.io.read_textgrid(
            str(source), include_empty_intervals=True
        )
        tiers = [
            name for name in grid.get_tier_names()
            if name.lower() == "phones"
            or name.lower().endswith(" - phones")
        ]
        if len(tiers) != 1:
            raise ValueError("Expected one phones tier")

        intervals = list(grid.get_tier_by_name(tiers[0]).intervals)
        if not intervals:
            raise ValueError("Empty phone tier")

        for interval in intervals:
            if not (
                math.isfinite(interval.start_time)
                and math.isfinite(interval.end_time)
                and interval.end_time > interval.start_time
            ):
                raise ValueError("Invalid interval")

        for previous, current in zip(intervals, intervals[1:]):
            if abs(current.start_time - previous.end_time) > 1e-5:
                raise ValueError("Gap or overlap between intervals")

        speech = [
            i for i, interval in enumerate(intervals)
            if interval.text not in silence
        ]
        if not speech:
            raise ValueError("No ordinary speech phones")

        kept = intervals[speech[0]:speech[-1] + 1]
        phones = [interval.text or "sp" for interval in kept]

        unknown = sorted(set(phones) - allowed)
        if unknown:
            raise ValueError(f"Unsupported phone labels: {unknown}")

        start, end = kept[0].start_time, kept[-1].end_time
        if start < -1e-5 or end > row["duration_seconds"] + 0.02:
            raise ValueError("Boundaries exceed source audio")

        # Future FastSpeech 2 feature configuration: 22,050 Hz / hop 256.
        durations = [
            round(interval.end_time * 22050 / 256)
            - round(interval.start_time * 22050 / 256)
            for interval in kept
        ]
        if min(durations) < 0 or sum(durations) <= 0:
            raise ValueError("Invalid frame-duration targets")

        zero_count = sum(value == 0 for value in durations)
        long_count = sum(
            interval.end_time - interval.start_time > 0.5
            for interval in kept if interval.text not in silence
        )
        if zero_count or long_count or "spn" in phones:
            warnings.append({
                "audit_index": row["index"],
                "zero_frame_phones": zero_count,
                "ordinary_phones_over_half_second": long_count,
                "spn_count": phones.count("spn"),
            })

        entry = dict(row)
        entry.update({
            "textgrid_path": str(main_dir / relative),
            "alignment_source": "wider_search_retry" if is_retry else "initial",
            "speech_start_seconds": start,
            "speech_end_seconds": end,
            "duration_frames": sum(durations),
            "alignment_status": "structural_checks_passed",
            "perceptual_boundary_accuracy_verified": False,
        })
        ready.append(entry)

        if is_retry:
            copies.append((source, main_dir / relative))

    except Exception as error:
        failures.append({
            "audit_index": row["index"],
            "error": f"{type(error).__name__}: {error}",
        })

report = {
    "selected_clips": len(selected),
    "structurally_valid_clips": len(ready),
    "structurally_valid_source_hours": sum(
        row["duration_seconds"] for row in ready
    ) / 3600,
    "hard_failures": failures,
    "warning_clip_count": len(warnings),
    "warnings": warnings,
    "retry_outputs_to_merge": len(copies),
    "retry_listening_review_pending": sorted(recovered),
}

(RECORDS / "telugu_training_alignment_audit.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(
    {key: value for key, value in report.items() if key != "warnings"},
    indent=2,
))

if failures or len(ready) != 1877:
    raise RuntimeError(
        "Structural audit needs review. Nothing merged; share the output."
    )

for source, destination in copies:
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)

with (MANIFESTS / "train_alignment_available.jsonl").open(
    "w", encoding="utf-8"
) as file:
    for row in ready:
        file.write(json.dumps(row, ensure_ascii=False) + "\n")

archive_dir = BASE / "alignment_resources/Telugu"
archive_path = archive_dir / "training_alignment_merged.tar.gz"
temporary = archive_dir / "training_alignment_merged.tar.gz.partial"

print("Saving merged alignment archive...", flush=True)
with tarfile.open(temporary, "w:gz") as archive:
    archive.add(main_dir, arcname="train")
temporary.replace(archive_path)

print("\nSTEP 5.16: PASSED")
print("Manifest and merged archive saved.")
print("Structural validity does not establish pronunciation/boundary accuracy.")
print("No FastSpeech 2 model trained.")

print("STEP 5.17 — TELUGU VALIDATION ALIGNMENT", flush=True)

from pathlib import Path
import json
import os
import subprocess
import tarfile

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
ROOT = BASE / "project"
RECORDS = ROOT / "reproducibility"

def read_record(name):
    return json.loads(
        (RECORDS / name).read_text(encoding="utf-8")
    )

setup = read_record("mfa_environment.json")
training_run = read_record("telugu_mfa_training_run.json")
inputs = read_record("telugu_alignment_inputs.json")

model = Path(training_run["saved_model"])
dictionary = ROOT / "Telugu/lexicon/telugu_alignment_candidates.dict"
corpus = Path(inputs["corpus_root"]) / "validation"

output = Path("/content/fastspeech2_alignment/telugu_validation/aligned")
work = Path("/content/fastspeech2_alignment/telugu_validation/work")

if not model.is_file() or not dictionary.is_file():
    raise FileNotFoundError("Trained aligner or alignment dictionary missing.")

if len(list(corpus.rglob("*.wav"))) != 360:
    raise RuntimeError("Expected 360 validation WAV files.")
if len(list(corpus.rglob("*.lab"))) != 360:
    raise RuntimeError("Expected 360 validation LAB files.")

environment = os.environ.copy()
environment["MAMBA_ROOT_PREFIX"] = setup["mamba_root_prefix"]
environment["MFA_ROOT_DIR"] = "/content/fastspeech2_tools/mfa_telugu_data"

command = [
    setup["micromamba_path"],
    "run", "--prefix", setup["environment_prefix"],
    "mfa", "align",
    str(corpus), str(dictionary), str(model), str(output),
    "--temporary_directory", str(work),
    "--num_jobs", "2",
    "--clean",
    "--overwrite",
]

log_path = RECORDS / "telugu_validation_alignment.log"

with log_path.open("w", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    for line in process.stdout:
        print(line, end="", flush=True)
        log.write(line)
        log.flush()
    exit_code = process.wait()

with (
    ROOT / "Telugu/manifests/validation_alignment_candidate.jsonl"
).open(encoding="utf-8") as file:
    selected = [json.loads(line) for line in file if line.strip()]

missing = [
    row["index"]
    for row in selected
    if not (
        output / row["conditioning_group"]
        / f"telugu_{row['index']:06d}.TextGrid"
    ).is_file()
]

textgrid_count = (
    len(list(output.rglob("*.TextGrid"))) if output.exists() else 0
)

archive_path = None
if output.exists():
    archive_dir = BASE / "alignment_resources/Telugu"
    archive_dir.mkdir(parents=True, exist_ok=True)
    archive_path = archive_dir / "validation_alignment_output.tar.gz"
    temporary = archive_dir / "validation_alignment_output.tar.gz.partial"

    print("Saving validation outputs...", flush=True)
    with tarfile.open(temporary, "w:gz") as archive:
        archive.add(output, arcname="validation")
    temporary.replace(archive_path)

report = {
    "exit_code": exit_code,
    "expected_clips": 360,
    "textgrid_count": textgrid_count,
    "missing_indices": missing,
    "local_output_directory": str(output),
    "output_archive": str(archive_path) if archive_path else None,
    "acoustic_model_retrained": False,
    "alignment_quality_verified": False,
    "command": command,
}

(RECORDS / "telugu_validation_alignment_run.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== TELUGU VALIDATION ALIGNMENT RESULT ===")
print(json.dumps(report, indent=2))

if exit_code != 0:
    print("Alignment command failed. Share the error output.")
elif missing or textgrid_count != 360:
    print("Missing alignments need investigation; do not rerun the full split.")
else:
    print("STEP 5.17 execution: PASSED")
    print("Validation TextGrid structural checks remain pending.")

print("No FastSpeech 2 model trained.")

