from pathlib import Path
import json
import math

import tgt

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
MANIFESTS = ROOT / "Telugu/manifests"

mapping = json.loads(
    (ROOT / "Telugu/lexicon/phone_mapping.json").read_text(
        encoding="utf-8"
    )
)
run = json.loads(
    (RECORDS / "telugu_validation_alignment_run.json").read_text(
        encoding="utf-8"
    )
)

allowed = set(mapping["token_to_ipa"]) | {"sil", "sp", "spn"}
silence = {"", "sil", "sp", "spn"}
alignment_dir = Path(run["local_output_directory"])

with (
    MANIFESTS / "validation_alignment_reviewed_candidate.jsonl"
).open(encoding="utf-8") as file:
    rows = [json.loads(line) for line in file if line.strip()]

ready, failures, warnings = [], [], []

for row in rows:
    path = (
        alignment_dir / row["conditioning_group"]
        / f"telugu_{row['index']:06d}.TextGrid"
    )

    try:
        grid = tgt.io.read_textgrid(
            str(path), include_empty_intervals=True
        )
        tiers = [
            name for name in grid.get_tier_names()
            if name.lower() == "phones"
            or name.lower().endswith(" - phones")
        ]
        if len(tiers) != 1:
            raise ValueError("Expected one phones tier")

        intervals = list(grid.get_tier_by_name(tiers[0]).intervals)
        if not intervals:
            raise ValueError("Empty phone tier")

        for interval in intervals:
            if not (
                math.isfinite(interval.start_time)
                and math.isfinite(interval.end_time)
                and interval.end_time > interval.start_time
            ):
                raise ValueError("Invalid interval")

        for previous, current in zip(intervals, intervals[1:]):
            if abs(current.start_time - previous.end_time) > 1e-5:
                raise ValueError("Gap or overlap between intervals")

        speech = [
            i for i, interval in enumerate(intervals)
            if interval.text not in silence
        ]
        if not speech:
            raise ValueError("No ordinary speech phones")

        kept = intervals[speech[0]:speech[-1] + 1]
        phones = [interval.text or "sp" for interval in kept]

        unknown = sorted(set(phones) - allowed)
        if unknown:
            raise ValueError(f"Unsupported phones: {unknown}")

        start, end = kept[0].start_time, kept[-1].end_time
        if start < -1e-5 or end > row["duration_seconds"] + 0.02:
            raise ValueError("Boundaries exceed source audio")

        durations = [
            round(interval.end_time * 22050 / 256)
            - round(interval.start_time * 22050 / 256)
            for interval in kept
        ]
        if min(durations) < 0 or sum(durations) <= 0:
            raise ValueError("Invalid frame durations")

        zero_count = sum(value == 0 for value in durations)
        long_count = sum(
            interval.end_time - interval.start_time > 0.5
            for interval in kept if interval.text not in silence
        )

        if zero_count or long_count or "spn" in phones:
            warnings.append({
                "audit_index": row["index"],
                "zero_frame_phones": zero_count,
                "ordinary_phones_over_half_second": long_count,
                "spn_count": phones.count("spn"),
            })

        entry = dict(row)
        entry.update({
            "textgrid_path": str(path),
            "alignment_source": "trained_telugu_aligner",
            "speech_start_seconds": start,
            "speech_end_seconds": end,
            "duration_frames": sum(durations),
            "alignment_status": "structural_checks_passed",
            "perceptual_boundary_accuracy_verified": False,
        })
        ready.append(entry)

    except Exception as error:
        failures.append({
            "audit_index": row["index"],
            "error": f"{type(error).__name__}: {error}",
        })

report = {
    "selected_clips": len(rows),
    "structurally_valid_clips": len(ready),
    "structurally_valid_source_hours": sum(
        row["duration_seconds"] for row in ready
    ) / 3600,
    "hard_failures": failures,
    "warning_clip_count": len(warnings),
    "warnings": warnings,
}

(RECORDS / "telugu_validation_alignment_audit.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(
    {key: value for key, value in report.items() if key != "warnings"},
    indent=2,
))

if failures or len(ready) != 357:
    raise RuntimeError(
        "Audit needs review. No available-manifest written; share the output."
    )

output = MANIFESTS / "validation_alignment_available.jsonl"
with output.open("w", encoding="utf-8") as file:
    for row in ready:
        file.write(json.dumps(row, ensure_ascii=False) + "\n")

print("\nSTEP 5.20: PASSED")
print("Manifest saved:", output)
print("Structural checks do not establish perceptual alignment accuracy.")
print("No FastSpeech 2 model trained.")

print("STEP 5.21 — ISOLATED TELUGU SYMBOL SUPPORT", flush=True)

from pathlib import Path
import hashlib
import json
import shutil
import subprocess
import sys

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
ENGLISH_REPO = Path("/content/FastSpeech2_reference")
TELUGU_REPO = Path("/content/FastSpeech2_telugu")

mapping = json.loads(
    (ROOT / "Telugu/lexicon/phone_mapping.json").read_text(
        encoding="utf-8"
    )
)
aliases = sorted(mapping["token_to_ipa"])

if len(aliases) != 45:
    raise RuntimeError("Expected 45 Telugu phone aliases.")

def read_symbols(repo):
    result = subprocess.run(
        [
            sys.executable, "-c",
            "import json; from text.symbols import symbols; "
            "print(json.dumps(symbols))",
        ],
        cwd=repo,
        capture_output=True,
        text=True,
        check=True,
    )
    return json.loads(result.stdout)

english_before = read_symbols(ENGLISH_REPO)

if TELUGU_REPO.exists():
    raise RuntimeError(
        "The Telugu repository copy already exists. "
        "Share this output before replacing it."
    )

shutil.copytree(
    ENGLISH_REPO,
    TELUGU_REPO,
    ignore=shutil.ignore_patterns(
        ".git", "__pycache__", "*.pyc",
        "raw_data", "output",
    ),
)

# Confirm that the verified compatibility patches were carried over.
patched_files = [
    "audio/stft.py",
    "audio/audio_processing.py",
    "preprocessor/preprocessor.py",
]
for relative in patched_files:
    expected = ROOT / "upstream_modified" / relative
    copied = TELUGU_REPO / relative
    if copied.read_bytes() != expected.read_bytes():
        raise RuntimeError(f"Compatibility patch mismatch: {relative}")

symbol_path = TELUGU_REPO / "text/symbols.py"
source = symbol_path.read_text(encoding="utf-8")

additions = ["@" + alias for alias in aliases]
if set(additions) & set(english_before):
    raise RuntimeError("A Telugu alias conflicts with an existing symbol.")

source += (
    "\n\n# Assignment: Telugu phone aliases; preserve existing token IDs.\n"
    "symbols += " + repr(additions) + "\n"
)
compile(source, str(symbol_path), "exec")
symbol_path.write_text(source, encoding="utf-8")

test_code = r'''
import json
import sys
from text import text_to_sequence, sequence_to_text
from text.symbols import symbols

aliases = json.loads(sys.argv[1])
cleaners = ["english_cleaners"]

for alias in aliases:
    sequence = text_to_sequence("{" + alias + "}", cleaners)
    if len(sequence) != 1:
        raise RuntimeError(f"Phone did not encode as one token: {alias}")

text = "{" + " ".join(aliases) + "}"
sequence = text_to_sequence(text, cleaners)
if len(sequence) != len(aliases):
    raise RuntimeError("Combined phone sequence lost tokens.")

decoded = sequence_to_text(sequence)
if text_to_sequence(decoded, cleaners) != sequence:
    raise RuntimeError("Phone-token round trip failed.")

print(json.dumps({
    "symbols": symbols,
    "tested_telugu_phones": len(aliases),
    "round_trip": "PASSED",
}))
'''

result = subprocess.run(
    [sys.executable, "-c", test_code, json.dumps(aliases)],
    cwd=TELUGU_REPO,
    capture_output=True,
    text=True,
)

if result.returncode != 0:
    print(result.stdout)
    print(result.stderr)
    raise RuntimeError("Telugu symbol test failed. Share the traceback.")

tested = json.loads(result.stdout)
english_after = read_symbols(ENGLISH_REPO)

if english_before != english_after:
    raise RuntimeError("English symbol inventory changed unexpectedly.")

if tested["symbols"] != english_before + additions:
    raise RuntimeError("Unexpected Telugu token ordering.")

saved_symbol_path = ROOT / "Telugu/upstream_modified/text/symbols.py"
saved_symbol_path.parent.mkdir(parents=True, exist_ok=True)
saved_symbol_path.write_text(source, encoding="utf-8")

inventory_path = ROOT / "Telugu/lexicon/model_symbols.json"
inventory_path.write_text(
    json.dumps(tested["symbols"], indent=2, ensure_ascii=False),
    encoding="utf-8",
)

report = {
    "telugu_reference_repo": str(TELUGU_REPO),
    "english_reference_repo": str(ENGLISH_REPO),
    "original_symbol_count": len(english_before),
    "telugu_symbol_count": len(tested["symbols"]),
    "appended_phone_count": len(aliases),
    "phone_round_trip": tested["round_trip"],
    "english_inventory_unchanged": True,
    "saved_symbol_inventory": str(inventory_path),
    "symbol_source_sha256": hashlib.sha256(
        symbol_path.read_bytes()
    ).hexdigest(),
}

(RECORDS / "telugu_symbol_integration.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(report, indent=2))
print("\nSTEP 5.21: PASSED")
print("No Telugu features extracted; no FastSpeech 2 model trained.")

print("STEP 5.22 — TELUGU FEATURE SMOKE TEST", flush=True)

