from pathlib import Path
import json

import numpy as np
import yaml
from sklearn.preprocessing import StandardScaler

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

config = yaml.safe_load(
    (ROOT / "Telugu/config.yaml").read_text(encoding="utf-8")
)
raw = Path(config["path"]["preprocessed_path"])

def read_manifest(split):
    with (raw / f"{split}_extracted.jsonl").open(
        encoding="utf-8"
    ) as file:
        return [json.loads(line) for line in file if line.strip()]

training = read_manifest("train")
validation = read_manifest("validation")

if len(training) != 1877 or len(validation) != 357:
    raise RuntimeError("Unexpected extracted-manifest counts.")

for field in ("index", "alignment_text_candidate", "waveform_sha256"):
    if not {row[field] for row in training}.isdisjoint(
        {row[field] for row in validation}
    ):
        raise RuntimeError(f"Train/validation overlap: {field}")

if not {row["conditioning_group"] for row in validation}.issubset(
    {row["conditioning_group"] for row in training}
):
    raise RuntimeError("Validation conditioning group absent from training.")

scalers = {
    "pitch": StandardScaler(),
    "energy": StandardScaler(),
}
counts = {"pitch": 0, "energy": 0}
zero_duration_positions = 0

for row in training:
    speaker = row["conditioning_group"]
    basename = f"telugu_{row['index']:06d}"

    duration = np.load(
        raw / "duration" / f"{speaker}-duration-{basename}.npy"
    )
    if np.any(duration < 0):
        raise RuntimeError(f"Negative durations: {basename}")

    valid = duration > 0
    zero_duration_positions += int(np.count_nonzero(~valid))

    for feature, scaler in scalers.items():
        values = np.load(
            raw / feature / f"{speaker}-{feature}-{basename}.npy"
        )

        if values.shape != duration.shape or not np.isfinite(values).all():
            raise RuntimeError(f"Invalid {feature} array: {basename}")

        selected = values[valid]
        if selected.size:
            scaler.partial_fit(selected.reshape(-1, 1))
            counts[feature] += int(selected.size)

statistics = {}

for feature, scaler in scalers.items():
    if counts[feature] == 0:
        raise RuntimeError(f"No training observations for {feature}.")

    mean = float(scaler.mean_[0])
    std = float(np.sqrt(scaler.var_[0]))

    if not np.isfinite(mean) or not np.isfinite(std) or std <= 0:
        raise RuntimeError(f"Invalid statistics for {feature}.")

    statistics[feature] = {
        "mean": mean,
        "std": std,
        "training_phone_observations": counts[feature],
    }

report = {
    "fit_split": "train",
    "training_clips": len(training),
    "validation_clips_not_used_for_fitting": len(validation),
    "feature_level": "phoneme",
    "zero_duration_positions_excluded": zero_duration_positions,
    "outlier_filter": "none",
    "statistics": statistics,
    "raw_arrays_modified": False,
}

output = RECORDS / "telugu_training_normalization_statistics.json"
output.write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(report, indent=2))
print("\nStatistics saved:", output)
print("STEP 5.25: PASSED")
print("No validation features used for fitting; no TTS model trained.")

print("STEP 5.26 — TELUGU NORMALIZATION", flush=True)

from pathlib import Path
import subprocess
import sys

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

source_path = ROOT / "English/normalize.py"
destination = ROOT / "Telugu/normalize.py"

if destination.exists():
    raise RuntimeError(
        "Telugu/normalize.py already exists. "
        "Share this output before replacing it."
    )

source = source_path.read_text(encoding="utf-8")

# Require the repaired single-line metadata handling.
if 'original.replace("\\r\\n", " ")' not in source:
    raise RuntimeError(
        "English normalization script lacks the verified line-break repair."
    )

replacements = [
    (
        "english_training_normalization_statistics.json",
        "telugu_training_normalization_statistics.json",
    ),
    ("english_processed", "telugu_processed"),
    (
        'len(manifests["train"]) != 3135',
        'len(manifests["train"]) != 1877',
    ),
    (
        'len(manifests["validation"]) != 626',
        'len(manifests["validation"]) != 357',
    ),
    (
        'f"svarah_{row[\'index\']:06d}"',
        'f"telugu_{row[\'index\']:06d}"',
    ),
    ("english_normalization_run.json", "telugu_normalization_run.json"),
    (
        "English normalization and metadata creation: PASSED",
        "Telugu normalization and metadata creation: PASSED",
    ),
]

for old, new in replacements:
    if source.count(old) != 1:
        raise RuntimeError(
            f"Unexpected source occurrence count for: {old!r}. "
            "No script written."
        )
    source = source.replace(old, new, 1)

compile(source, str(destination), "exec")
destination.write_text(source, encoding="utf-8")

print("Saved reusable script:", destination)
print("Normalizing from raw Telugu arrays...", flush=True)

result = subprocess.run(
    [
        sys.executable, "-u", str(destination),
        "--config", str(ROOT / "Telugu/config.yaml"),
    ],
    capture_output=True,
    text=True,
)

output = result.stdout + result.stderr
(RECORDS / "telugu_normalization_run.log").write_text(
    output, encoding="utf-8"
)

print(output)
print("Exit code:", result.returncode)

if result.returncode != 0:
    raise RuntimeError(
        "Telugu normalization needs review. Script is saved; "
        "do not rerun this creation cell."
    )

print("STEP 5.26: PASSED")
print("Raw arrays unchanged; no FastSpeech 2 model trained.")

