from pathlib import Path
import json
import subprocess
import sys
import tarfile

import numpy as np
import yaml

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

config = yaml.safe_load(
    (ROOT / "Telugu/config.yaml").read_text(encoding="utf-8")
)
run = json.loads(
    (RECORDS / "telugu_normalization_run.json").read_text(
        encoding="utf-8"
    )
)
fit = json.loads(
    (RECORDS / "telugu_training_normalization_statistics.json").read_text(
        encoding="utf-8"
    )
)

raw = Path(config["path"]["preprocessed_path"])
processed = Path(run["output_directory"])
speakers = json.loads(
    (processed / "speakers.json").read_text(encoding="utf-8")
)

rows_by_split = {}
moments = {
    feature: {"count": 0, "sum": 0.0, "squares": 0.0}
    for feature in ("pitch", "energy")
}
summary = {}

for split, metadata_name, expected_count in (
    ("train", "train.txt", 1877),
    ("validation", "val.txt", 357),
):
    with (raw / f"{split}_extracted.jsonl").open(encoding="utf-8") as file:
        rows = [json.loads(line) for line in file if line.strip()]
    rows_by_split[split] = rows

    lines = (processed / metadata_name).read_text(
        encoding="utf-8"
    ).splitlines()

    if len(rows) != expected_count or len(lines) != expected_count:
        raise ValueError(f"{split}: unexpected record count")

    for row, line in zip(rows, lines):
        basename = f"telugu_{row['index']:06d}"
        speaker = row["conditioning_group"]
        fields = line.split("|")

        if len(fields) != 4 or fields[:2] != [basename, speaker]:
            raise ValueError(f"Invalid metadata: {basename}")
        if speaker not in speakers:
            raise ValueError(f"Unknown speaker group: {speaker}")

        phones = fields[2].strip("{}").split()

        def path(root, feature):
            return root / feature / f"{speaker}-{feature}-{basename}.npy"

        duration = np.load(path(processed, "duration"))
        mel = np.load(path(processed, "mel"))

        if not np.array_equal(duration, np.load(path(raw, "duration"))):
            raise ValueError(f"Duration changed: {basename}")
        if not np.array_equal(mel, np.load(path(raw, "mel"))):
            raise ValueError(f"Mel changed: {basename}")
        if mel.shape != (int(duration.sum()), 80):
            raise ValueError(f"Mel/duration mismatch: {basename}")
        if len(duration) != len(phones) or np.any(duration < 0):
            raise ValueError(f"Phone/duration mismatch: {basename}")
        if not np.isfinite(mel).all():
            raise ValueError(f"Non-finite mel: {basename}")

        valid = duration > 0

        for feature in ("pitch", "energy"):
            original = np.load(path(raw, feature))
            actual = np.load(path(processed, feature))
            stats = fit["statistics"][feature]

            expected = (
                (original.astype(np.float64) - stats["mean"]) / stats["std"]
            )
            expected[~valid] = 0
            expected = expected.astype(np.float32)

            if actual.shape != duration.shape:
                raise ValueError(f"Feature shape mismatch: {basename}")
            if not np.isfinite(actual).all():
                raise ValueError(f"Non-finite {feature}: {basename}")
            if not np.allclose(actual, expected, rtol=1e-6, atol=1e-6):
                raise ValueError(f"Normalization mismatch: {basename}/{feature}")

            if split == "train":
                values = actual[valid].astype(np.float64)
                moments[feature]["count"] += len(values)
                moments[feature]["sum"] += float(values.sum())
                moments[feature]["squares"] += float(np.square(values).sum())

    summary[split] = {"verified_clips": len(rows)}

for field in ("index", "alignment_text_candidate", "waveform_sha256"):
    if not {r[field] for r in rows_by_split["train"]}.isdisjoint(
        {r[field] for r in rows_by_split["validation"]}
    ):
        raise ValueError(f"Split overlap: {field}")

normalized_moments = {}
for feature, values in moments.items():
    mean = values["sum"] / values["count"]
    variance = values["squares"] / values["count"] - mean ** 2
    std = float(np.sqrt(max(variance, 0)))

    if abs(mean) > 1e-5 or abs(std - 1) > 1e-5:
        raise ValueError(f"Unexpected training moments: {feature}")

    normalized_moments[feature] = {"mean": mean, "std": std}

# Use a fresh process to load Telugu's isolated symbol inventory.
token_check = r'''
from pathlib import Path
import sys
from text import text_to_sequence

root = Path(sys.argv[1])
count = 0
for name in ("train.txt", "val.txt"):
    for line in (root / name).read_text(encoding="utf-8").splitlines():
        phone_text = line.split("|")[2]
        expected = len(phone_text.strip("{}").split())
        encoded = text_to_sequence(phone_text, ["english_cleaners"])
        if len(encoded) != expected:
            raise ValueError("Phone tokens lost during encoding")
        count += 1
print(f"Phone encoding: PASSED for {count} records")
'''

result = subprocess.run(
    [sys.executable, "-c", token_check, str(processed)],
    cwd=config["workflow"]["reference_repo"],
    capture_output=True,
    text=True,
)
print(result.stdout)
if result.returncode != 0:
    print(result.stderr)
    raise RuntimeError("Telugu token-encoding check failed.")

archive_dir = ROOT.parent / "processed_data/Telugu"
archive_dir.mkdir(parents=True, exist_ok=True)
archive_path = archive_dir / "telugu_processed.tar.gz"
temporary = archive_dir / "telugu_processed.tar.gz.partial"

print("Saving processed-data archive...", flush=True)
with tarfile.open(temporary, "w:gz") as archive:
    archive.add(processed, arcname="telugu_processed")
temporary.replace(archive_path)

report = {
    "checks": "PASSED",
    "splits": summary,
    "normalized_training_moments": normalized_moments,
    "conditioning_groups": len(speakers),
    "processed_directory": str(processed),
    "recovery_archive": str(archive_path),
    "archive_size_bytes": archive_path.stat().st_size,
    "perceptual_quality_review_complete": False,
}

(RECORDS / "telugu_processed_verification.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(report, indent=2))
print("\nSTEP 5.27: PASSED")
print("No FastSpeech 2 model trained.")

print("STEP 5.28 — TELUGU MODEL CONFIGURATION")

from pathlib import Path
import copy
import json

import yaml

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"
CONFIG_DIR = ROOT / "Telugu/config"

verification = json.loads(
    (RECORDS / "telugu_processed_verification.json").read_text(
        encoding="utf-8"
    )
)
integration = json.loads(
    (RECORDS / "telugu_symbol_integration.json").read_text(
        encoding="utf-8"
    )
)

if verification["checks"] != "PASSED":
    raise RuntimeError("Processed Telugu data has not passed verification.")

def load_yaml(path):
    return yaml.safe_load(path.read_text(encoding="utf-8"))

preprocess = load_yaml(ROOT / "Telugu/config.yaml")
preprocess.pop("workflow", None)
preprocess["path"]["preprocessed_path"] = verification["processed_directory"]
preprocess["preprocessing"]["val_size"] = 357

model = copy.deepcopy(load_yaml(ROOT / "English/config/model.yaml"))
model["multi_speaker"] = True

train = copy.deepcopy(load_yaml(ROOT / "English/config/train.yaml"))
train["path"] = {
    "ckpt_path": str(ROOT / "Telugu/checkpoints"),
    "log_path": str(ROOT / "Telugu/logs"),
    "result_path": str(ROOT / "Results/Telugu"),
}

configs = {
    "preprocess.yaml": preprocess,
    "model.yaml": model,
    "train.yaml": train,
}

existing = [
    name for name in configs if (CONFIG_DIR / name).exists()
]
if existing:
    raise RuntimeError(
        f"Configuration files already exist: {existing}. "
        "Share this output before replacing them."
    )

processed = Path(verification["processed_directory"])
speakers = json.loads(
    (processed / "speakers.json").read_text(encoding="utf-8")
)

if set(speakers) != {"telugu_female", "telugu_male"}:
    raise RuntimeError(f"Unexpected speaker mapping: {speakers}")

for name in ("train.txt", "val.txt", "stats.json", "speakers.json"):
    if not (processed / name).is_file():
        raise FileNotFoundError(processed / name)

if not Path(integration["telugu_reference_repo"]).is_dir():
    raise FileNotFoundError("Isolated Telugu repository is missing.")

CONFIG_DIR.mkdir(parents=True, exist_ok=True)
for name, config in configs.items():
    (CONFIG_DIR / name).write_text(
        yaml.safe_dump(config, sort_keys=False), encoding="utf-8"
    )

for path in train["path"].values():
    Path(path).mkdir(parents=True, exist_ok=True)

summary = {
    "configuration_directory": str(CONFIG_DIR),
    "reference_repo": integration["telugu_reference_repo"],
    "processed_directory": str(processed),
    "speakers": speakers,
    "multi_speaker": model["multi_speaker"],
    "batch_size": train["optimizer"]["batch_size"],
    "initial_maximum_steps": train["step"]["total_step"],
    "checkpoint_interval": train["step"]["save_step"],
    "vocoder_checkpoint_verified": False,
}

(RECORDS / "telugu_model_configuration.json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print(json.dumps(summary, indent=2))
