import gdown

BASE = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
RECORDS = BASE / "project/reproducibility"
DESTINATION = BASE / "vocoder/UNIVERSAL_V1"
DESTINATION.mkdir(parents=True, exist_ok=True)

inventory = json.loads(
    (RECORDS / "official_hifigan_file_inventory.json").read_text(
        encoding="utf-8"
    )
)

files_by_name = {}
for item in inventory["universal_v1_candidates"]:
    if item["name"] in files_by_name:
        raise RuntimeError(f"Ambiguous file name: {item['name']}")
    files_by_name[item["name"]] = item

saved = {}

for name in ("config.json", "g_02500000"):
    item = files_by_name[name]
    destination = DESTINATION / name

    if not destination.exists():
        temporary = DESTINATION / f"{name}.partial"
        result = gdown.download(
            id=item["file_id"],
            output=str(temporary),
            quiet=False,
        )
        if result is None or not temporary.is_file():
            raise RuntimeError(f"Download failed: {name}")
        temporary.replace(destination)
    else:
        print("Reusing existing file:", destination)

    if destination.stat().st_size == 0:
        raise RuntimeError(f"Downloaded file is empty: {name}")

    saved[name] = {
        "file_id": item["file_id"],
        "path": str(destination),
        "size_bytes": destination.stat().st_size,
        "sha256": hashlib.sha256(destination.read_bytes()).hexdigest(),
    }

official = json.loads(
    (DESTINATION / "config.json").read_text(encoding="utf-8")
)

keys = [
    "resblock",
    "upsample_rates",
    "upsample_kernel_sizes",
    "upsample_initial_channel",
    "resblock_kernel_sizes",
    "resblock_dilation_sizes",
    "num_mels",
    "n_fft",
    "hop_size",
    "win_size",
    "sampling_rate",
    "fmin",
    "fmax",
]

comparisons = {}

for language, repo in (
    ("English", Path("/content/FastSpeech2_reference")),
    ("Telugu", Path("/content/FastSpeech2_telugu")),
):
    local = json.loads(
        (repo / "hifigan/config.json").read_text(encoding="utf-8")
    )

    mismatches = {}
    for key in keys:
        if key not in official or key not in local:
            mismatches[key] = {
                "official_present": key in official,
                "repository_present": key in local,
            }
        elif official[key] != local[key]:
            mismatches[key] = {
                "official": official[key],
                "repository": local[key],
            }

    comparisons[language] = {
        "compared_keys": keys,
        "mismatches": mismatches,
    }

report = {
    "source_repository": inventory["source_repository"],
    "official_folder": inventory["official_folder"],
    "files": saved,
    "configuration_comparison": comparisons,
    "checkpoint_loaded": False,
    "waveform_generation_tested": False,
}

(RECORDS / "universal_vocoder_download.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print("\n=== VOCODER DOWNLOAD AND CONFIGURATION CHECK ===")
print(json.dumps(report, indent=2))

if any(result["mismatches"] for result in comparisons.values()):
    print("\nConfiguration differences require review before loading.")
else:
    print("\nConfiguration comparison: PASSED")

