from pathlib import Path
import ast

REPO = Path("/content/FastSpeech2_reference")
RECORDS = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/"
    "project/reproducibility"
)

requests = {
    "train.py": {"main"},
    "utils/model.py": {"get_model", "get_vocoder"},
    "model/optimizer.py": {"ScheduledOptim"},
}

sections = []

for relative_path, names in requests.items():
    path = REPO / relative_path
    source = path.read_text(encoding="utf-8")
    tree = ast.parse(source)
    found = set()

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            if node.name in names:
                found.add(node.name)
                section = (
                    f"\n=== {relative_path}: {node.name} ===\n"
                    + ast.get_source_segment(source, node)
                )
                sections.append(section)
                print(section)

    missing = names - found
    if missing:
        raise RuntimeError(
            f"Expected definitions missing from {relative_path}: {missing}"
        )

# Include the command-line entry point.
train_source = (REPO / "train.py").read_text(encoding="utf-8")
train_tree = ast.parse(train_source)

for node in train_tree.body:
    if isinstance(node, ast.If) and "__name__" in ast.unparse(node.test):
        section = (
            "\n=== train.py: command-line entry point ===\n"
            + ast.get_source_segment(train_source, node)
        )
        sections.append(section)
        print(section)

output = RECORDS / "upstream_training_source_inspection.txt"
output.write_text("\n".join(sections), encoding="utf-8")

print("\nSTEP 6.5: PASSED")
print("Inspection saved:", output)
print("No optimizer updates or training performed.")

print("STEP 6.6 — CHECKPOINT COMPATIBILITY PATCH")

from pathlib import Path
import json

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

patches = {
    "utils/model.py": [
        (
            "ckpt = torch.load(ckpt_path)",
            'ckpt = torch.load(ckpt_path, map_location="cpu", weights_only=True)',
        ),
    ],
    "model/optimizer.py": [
        (
            'param_group["lr"] = lr',
            'param_group["lr"] = float(lr)',
        ),
    ],
}

prepared = []

# Validate every patch before writing any source files.
for language, repo in (
    ("English", Path("/content/FastSpeech2_reference")),
    ("Telugu", Path("/content/FastSpeech2_telugu")),
):
    for relative, edits in patches.items():
        path = repo / relative
        source = path.read_text(encoding="utf-8")

        for old, new in edits:
            if source.count(new) == 1:
                continue
            if source.count(old) != 1:
                raise RuntimeError(
                    f"Unexpected source: {language}/{relative}. "
                    "No patches written."
                )
            source = source.replace(old, new, 1)

        compile(source, str(path), "exec")
        prepared.append((language, path, relative, source))

saved = []

for language, path, relative, source in prepared:
    path.write_text(source, encoding="utf-8")

    destination = ROOT / language / "upstream_modified" / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(source, encoding="utf-8")

    saved.append({
        "language": language,
        "modified_file": relative,
        "saved_source": str(destination),
    })

report = {
    "files": saved,
    "checkpoint_loading": {
        "map_location": "cpu",
        "weights_only": True,
    },
    "scheduler_learning_rate_type": "Python float",
    "optimizer_updates_performed": 0,
    "checkpoint_round_trip_verified": False,
}

(RECORDS / "checkpoint_compatibility_patch.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)

print(json.dumps(report, indent=2))
print("\nSTEP 6.6: PASSED")
print("No model checkpoint loaded or training performed.")

print("STEP 6.7 — OPTIMIZER/CHECKPOINT ROUND-TRIP TEST", flush=True)

from pathlib import Path
import subprocess
import sys

ROOT = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/project"
)
RECORDS = ROOT / "reproducibility"

test_code = r'''
from pathlib import Path
from types import SimpleNamespace
import json
import random
import sys

import numpy as np
import torch
import yaml

from dataset import Dataset
from model import FastSpeech2Loss
from utils.model import get_model
from utils.tools import to_device

language = sys.argv[1]
root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
config_dir = root / language / "config"

def load(name):
    return yaml.safe_load(
        (config_dir / name).read_text(encoding="utf-8")
    )

preprocess, model_config, train = [
    load(name) for name in ("preprocess.yaml", "model.yaml", "train.yaml")
]

# Override checkpoint path in memory only.
smoke_dir = records / "smoke_checkpoints" / language
smoke_dir.mkdir(parents=True, exist_ok=True)
train["path"]["ckpt_path"] = str(smoke_dir)

if train["optimizer"]["grad_acc_step"] != 1:
    raise RuntimeError("This smoke test expects grad_acc_step=1.")
if not torch.cuda.is_available():
    raise RuntimeError("GPU unavailable.")

random.seed(42)
np.random.seed(42)
torch.manual_seed(42)
torch.cuda.manual_seed_all(42)

device = torch.device("cuda")
configs = (preprocess, model_config, train)

dataset = Dataset(
    "train.txt", preprocess, train, sort=True, drop_last=False
)

if language == "Telugu":
    lines = (
        Path(preprocess["path"]["preprocessed_path"]) / "train.txt"
    ).read_text(encoding="utf-8").splitlines()
    indices = []
    for speaker in ("telugu_female", "telugu_male"):
        indices.extend([
            i for i, line in enumerate(lines)
            if line.split("|")[1] == speaker
        ][:2])
else:
    indices = list(range(4))

batch = to_device(
    dataset.collate_fn([dataset[i] for i in indices])[0], device
)
model, optimizer = get_model(
    SimpleNamespace(restore_step=0), configs, device, train=True
)
criterion = FastSpeech2Loss(preprocess, model_config).to(device)

# Track one trainable tensor to verify that updates change parameters.
tracked_name, tracked_parameter = next(model.named_parameters())
before = tracked_parameter.detach().cpu().clone()

def update(current_model, current_optimizer):
    current_model.train()
    current_optimizer.zero_grad()
    predictions = current_model(*(batch[2:]))
    losses = criterion(batch, predictions)
    if not all(torch.isfinite(loss).all() for loss in losses):
        raise RuntimeError("Non-finite loss.")
    losses[0].backward()
    norm = torch.nn.utils.clip_grad_norm_(
        current_model.parameters(),
        train["optimizer"]["grad_clip_thresh"],
        error_if_nonfinite=True,
    )
    current_optimizer.step_and_update_lr()
    current_optimizer.zero_grad()
    return float(losses[0].detach().cpu()), float(norm.detach().cpu())

loss_history = []
for _ in range(2):
    loss, norm = update(model, optimizer)
    loss_history.append(loss)

after = dict(model.named_parameters())[tracked_name].detach().cpu()
if torch.equal(before, after):
    raise RuntimeError("Tracked parameters did not change.")

checkpoint_path = smoke_dir / "2.pth.tar"
torch.save({
    "model": model.state_dict(),
    "optimizer": optimizer._optimizer.state_dict(),
    "step": 2,
    "purpose": "disposable_checkpoint_smoke_test",
}, checkpoint_path)

saved = torch.load(
    checkpoint_path, map_location="cpu", weights_only=True
)

restored, restored_optimizer = get_model(
    SimpleNamespace(restore_step=2), configs, device, train=True
)

for name, value in restored.state_dict().items():
    if not torch.equal(value.detach().cpu(), saved["model"][name]):
        raise RuntimeError(f"Restored model mismatch: {name}")

def equal_state(a, b):
    if isinstance(a, torch.Tensor) and isinstance(b, torch.Tensor):
        return torch.equal(a.detach().cpu(), b.detach().cpu())
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            equal_state(a[key], b[key]) for key in a
        )
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return len(a) == len(b) and all(
            equal_state(x, y) for x, y in zip(a, b)
        )
    return a == b

if not equal_state(
    saved["optimizer"], restored_optimizer._optimizer.state_dict()
):
    raise RuntimeError("Restored optimizer state mismatch.")

if restored_optimizer.current_step != 2:
    raise RuntimeError("Scheduler step was not restored.")

resumed_loss, resumed_gradient_norm = update(restored, restored_optimizer)
if restored_optimizer.current_step != 3:
    raise RuntimeError("Resumed scheduler did not advance to step 3.")

report = {
    "language": language,
    "updates_before_save": 2,
    "updates_after_restore": 1,
    "model_state_restoration": "PASSED",
    "optimizer_state_restoration": "PASSED",
    "resumed_scheduler_step": restored_optimizer.current_step,
    "learning_rate": restored_optimizer._optimizer.param_groups[0]["lr"],
    "smoke_total_losses": loss_history + [resumed_loss],
    "smoke_checkpoint": str(checkpoint_path),
    "full_training_run": False,
    "status": "PASSED",
}

(records / f"{language.lower()}_checkpoint_smoke_test.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2), flush=True)
'''

script_path = RECORDS / "optimizer_checkpoint_smoke.py"
script_path.write_text(test_code, encoding="utf-8")

for language, repo in (
    ("English", "/content/FastSpeech2_reference"),
    ("Telugu", "/content/FastSpeech2_telugu"),
):
    print(f"\n=== {language.upper()} ===", flush=True)
    log_path = RECORDS / f"{language.lower()}_checkpoint_smoke_test.log"

    with log_path.open("w", encoding="utf-8") as log:
        process = subprocess.Popen(
            [sys.executable, "-u", str(script_path), language],
            cwd=repo,
            env={
                **__import__("os").environ,
                "PYTHONPATH": repo,
            },
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        for line in process.stdout:
            print(line, end="", flush=True)
            log.write(line)
            log.flush()
        exit_code = process.wait()

    if exit_code != 0:
        raise RuntimeError(
            f"{language} checkpoint test failed. Share the full traceback."
        )

print("\nSTEP 6.7: PASSED")
print("Only disposable smoke-test updates performed.")

