new_before = """# Track every trainable tensor; frozen parameters need not change.
before = {
    name: parameter.detach().cpu().clone()
    for name, parameter in model.named_parameters()
    if parameter.requires_grad
}
if not before:
    raise RuntimeError("No trainable parameters found.")
print("Trainable tensors tracked:", len(before), flush=True)"""

old_after = """after = dict(model.named_parameters())[tracked_name].detach().cpu()
if torch.equal(before, after):
    raise RuntimeError("Tracked parameters did not change.")"""

new_after = """changed_names = [
    name
    for name, parameter in model.named_parameters()
    if name in before
    and not torch.equal(before[name], parameter.detach().cpu())
]
print("Changed trainable tensors:", len(changed_names), flush=True)
print("First changed tensors:", changed_names[:5], flush=True)
if not changed_names:
    raise RuntimeError("No trainable parameters changed after two updates.")
del before"""

if old_before in source and old_after in source:
    backup = script.with_name("optimizer_checkpoint_smoke_before_tracking_fix.py")
