from pathlib import Path
import json
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
checkpoint_path = root / "English/checkpoints/1000.pth.tar"

print("STEP 7.3 — VERIFY ENGLISH STEP-1000 CHECKPOINT")
checkpoint = torch.load(
    checkpoint_path,
    map_location="cpu",
    weights_only=True,
)

for key in ("model", "optimizer"):
    if key not in checkpoint:
        raise RuntimeError(f"Missing checkpoint key: {key}")

model_state = checkpoint["model"]
optimizer_state = checkpoint["optimizer"]

bad_model_tensors = [
    name for name, value in model_state.items()
    if torch.is_tensor(value)
    and (value.is_floating_point() or value.is_complex())
    and not torch.isfinite(value).all().item()
]
if bad_model_tensors:
    raise RuntimeError(f"Non-finite model tensors: {bad_model_tensors}")

states = optimizer_state["state"]
if not states:
    raise RuntimeError("Optimizer state is empty.")

steps = []
for parameter_id, state in states.items():
    if "step" not in state:
        raise RuntimeError(f"Missing Adam step: parameter {parameter_id}")

    step = state["step"]
    steps.append(int(step.item() if torch.is_tensor(step) else step))

    for name, value in state.items():
        if torch.is_tensor(value) and not torch.isfinite(value).all().item():
            raise RuntimeError(
                f"Non-finite optimizer state: {parameter_id}/{name}"
            )

if set(steps) != {1000}:
    raise RuntimeError(f"Unexpected Adam update counts: {sorted(set(steps))}")

learning_rates = [
    float(group["lr"]) for group in optimizer_state["param_groups"]
]
if not all(0 < rate < float("inf") for rate in learning_rates):
    raise RuntimeError(f"Invalid learning rates: {learning_rates}")

report = {
    "language": "English",
    "checkpoint": str(checkpoint_path),
    "checkpoint_bytes": checkpoint_path.stat().st_size,
    "model_tensor_count": len(model_state),
    "optimizer_parameter_states": len(states),
    "adam_update_counts": sorted(set(steps)),
    "saved_learning_rates": learning_rates,
    "model_and_optimizer_tensors_finite": True,
    "status": "PASSED",
}

report_path = root / "reproducibility/english_checkpoint_1000_verification.json"
report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")

print(json.dumps(report, indent=2))
print("Report saved:", report_path)
print("No optimizer updates performed.")

