from pathlib import Path
import hashlib
import shutil
import tarfile
import tempfile

base = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
root = base / "project"
repo = Path("/content/FastSpeech2_reference")
data = Path("/content/fastspeech2_features/english_processed")

source_archive = root / "reproducibility/FastSpeech2_upstream_d4e79eb52e8b.tar.gz"
data_archive = base / "processed_data/English/english_processed.tar.gz"
vocoder = base / "vocoder/UNIVERSAL_V1/g_02500000"

patches = {
    "audio/audio_processing.py":
        root / "upstream_modified/audio/audio_processing.py",
    "audio/stft.py":
        root / "upstream_modified/audio/stft.py",
    "preprocessor/preprocessor.py":
        root / "upstream_modified/preprocessor/preprocessor.py",
    "model/optimizer.py":
        root / "English/upstream_modified/model/optimizer.py",
    "utils/model.py":
        root / "English/upstream_modified/utils/model.py",
}

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

if repo.exists() or data.exists():
    raise RuntimeError(
        "A restoration destination already exists. "
        "Share this output before replacing files."
    )

for path in [source_archive, data_archive, vocoder, *patches.values()]:
    if not path.is_file():
        raise FileNotFoundError(path)

if sha256(source_archive) != (
    "48a507d44986adf54a401e58f4ad8be87"
    "bb4f4602621aa4da0d7a05af85f3ac6"
):
    raise RuntimeError("Source archive hash mismatch.")

vocoder_hash = (
    "771eaf4876485a35e25577563d390c262"
    "e23c2421e4a8c929eacfde34a5b7a60"
)
if sha256(vocoder) != vocoder_hash:
    raise RuntimeError("Vocoder hash mismatch.")

print("Restoring repository...", flush=True)
with tempfile.TemporaryDirectory(dir="/content") as temporary:
    temporary = Path(temporary)
    with tarfile.open(source_archive, "r:gz") as archive:
        archive.extractall(temporary, filter="data")

    extracted = temporary / "FastSpeech2"
    if not (extracted / "train.py").is_file():
        raise RuntimeError("Unexpected repository archive layout.")

    for relative, saved in patches.items():
        target = extracted / relative
        if not target.is_file():
            raise FileNotFoundError(target)
        shutil.copy2(saved, target)
        if sha256(target) != sha256(saved):
            raise RuntimeError(f"Patch copy failed: {relative}")
        compile(target.read_text(encoding="utf-8"), str(target), "exec")

    target_vocoder = extracted / "hifigan/generator_universal.pth.tar"
    shutil.copy2(vocoder, target_vocoder)
    if sha256(target_vocoder) != vocoder_hash:
        raise RuntimeError("Vocoder copy verification failed.")

    shutil.move(str(extracted), str(repo))

print("Restoring processed data...", flush=True)
data.parent.mkdir(parents=True, exist_ok=True)
with tempfile.TemporaryDirectory(dir="/content") as temporary:
    temporary = Path(temporary)
    with tarfile.open(data_archive, "r:gz") as archive:
        archive.extractall(temporary, filter="data")

    candidates = list(temporary.rglob("train.txt"))
    if len(candidates) != 1:
        raise RuntimeError("Unexpected processed-data archive layout.")
    extracted = candidates[0].parent

    for filename, expected in [("train.txt", 3135), ("val.txt", 626)]:
        lines = (extracted / filename).read_text(
            encoding="utf-8"
        ).splitlines()
        if len(lines) != expected:
            raise RuntimeError(f"Unexpected record count: {filename}")

    for filename in ("stats.json", "speakers.json"):
        if not (extracted / filename).is_file():
            raise FileNotFoundError(extracted / filename)

    shutil.move(str(extracted), str(data))

print("\nRepository restored:", repo)
print("Compatibility patches verified:", len(patches))
print("Universal vocoder hash: PASSED")
print("Training metadata records: 3135")
print("Validation metadata records: 626")
print("Processed data restored:", data)
print("Feature-array verification and imports remain pending.")
print("No packages installed; no training started.")

