from pathlib import Path
from datetime import datetime, timezone
import json
import os
import subprocess
import sys
import time
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
checkpoint_dir = root / "English/checkpoints"

start_step, stop_step = 6000, 10000
source_checkpoint = checkpoint_dir / f"{start_step}.pth.tar"
final_checkpoint = checkpoint_dir / f"{stop_step}.pth.tar"

if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable. Do not start training.")
if not source_checkpoint.is_file():
    raise FileNotFoundError(source_checkpoint)

newer = [
    path.name for path in checkpoint_dir.glob("*.pth.tar")
    if path.name.split(".")[0].isdigit()
    and int(path.name.split(".")[0]) > start_step
]
if newer:
    raise RuntimeError(
        f"Newer checkpoints exist: {newer}. Share this output before resuming."
    )

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
log_path = records / f"english_training_6000_to_10000_{stamp}.log"
summary_path = log_path.with_suffix(".json")

command = [
    sys.executable, "-u", str(root / "English/train.py"),
    "--restore_step", str(start_step),
    "--stop_step", str(stop_step),
    "--seed", "42",
]
environment = os.environ.copy()
environment["PYTHONUNBUFFERED"] = "1"

print("ENGLISH TRAINING: 6000 → 10000", flush=True)
print("GPU:", torch.cuda.get_device_name(0), flush=True)
print("Full log:", log_path, flush=True)
started = time.monotonic()

with log_path.open("x", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    try:
        for line in process.stdout:
            log.write(line)
            log.flush()
            if line.strip() and not line.lstrip().startswith(
                ("Training:", "Epoch ")
            ):
                print(line, end="", flush=True)
        exit_code = process.wait()
    except KeyboardInterrupt:
        process.terminate()
        process.wait()
        print("\nInterrupted. Preserve all saved checkpoints.", flush=True)
        raise

summary = {
    "language": "English",
    "restore_step": start_step,
    "requested_final_step": stop_step,
    "exit_code": exit_code,
    "elapsed_minutes": (time.monotonic() - started) / 60,
    "checkpoint": str(final_checkpoint),
    "checkpoint_exists": final_checkpoint.is_file(),
    "checkpoint_bytes": (
        final_checkpoint.stat().st_size
        if final_checkpoint.is_file() else None
    ),
    "console_log": str(log_path),
    "checkpoint_contents_verified": False,
}
summary_path.write_text(json.dumps(summary, indent=2), encoding="utf-8")
print("\n=== EXECUTION SUMMARY ===")
print(json.dumps(summary, indent=2))

if exit_code != 0:
    raise RuntimeError("Training failed. Share the complete traceback.")
if not final_checkpoint.is_file() or final_checkpoint.stat().st_size == 0:
    raise RuntimeError("Final checkpoint is missing or empty.")

print("Segment completed. Checkpoint and loss trends need review.")

from pathlib import Path
import csv
import gc
import json
import re

import matplotlib.pyplot as plt
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
results = root / "Results/English"

print("=== CHECKPOINT VERIFICATION ===")
verified = []

for expected_step in (9000, 10000):
    path = root / f"English/checkpoints/{expected_step}.pth.tar"
    checkpoint = torch.load(path, map_location="cpu", weights_only=True)

    for value in checkpoint["model"].values():
        if torch.is_tensor(value) and not torch.isfinite(value).all().item():
            raise RuntimeError(f"Non-finite model tensor at step {expected_step}")

    states = checkpoint["optimizer"]["state"]
    if not states:
        raise RuntimeError("Empty optimizer state.")

    steps = set()
    for state in states.values():
        step = state["step"]
        steps.add(int(step.item() if torch.is_tensor(step) else step))
        for value in state.values():
            if torch.is_tensor(value) and not torch.isfinite(value).all().item():
                raise RuntimeError(
                    f"Non-finite optimizer state at step {expected_step}"
                )

    if steps != {expected_step}:
        raise RuntimeError(f"Unexpected Adam update counts: {steps}")

    verified.append(expected_step)
    print(f"[PASS] Step {expected_step}: model, optimizer and update counts")
    del checkpoint, states, state, value
    gc.collect()

# Retain the previously audited history only through checkpoint 6000.
csv_path = results / "loss_history.csv"
names = ["total", "mel", "postnet_mel", "pitch", "energy", "duration"]
rows = {}

with csv_path.open(newline="", encoding="utf-8") as file:
    for row in csv.DictReader(file):
        step = int(row["step"])
        if step <= 6000:
            rows[(row["split"], step)] = {
                "split": row["split"],
                "step": step,
                **{name: float(row[name]) for name in names},
            }

log_path = records / (
    "english_training_6000_to_10000_20261102T105353454424Z.log"
)
number = r"([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)"
pattern = re.compile(
    r"(Validation Step|Step)\s+(\d+)(?:/\d+)?,\s*"
    r"Total Loss:\s*" + number +
    r",\s*Mel Loss:\s*" + number +
    r",\s*Mel PostNet Loss:\s*" + number +
    r",\s*Pitch Loss:\s*" + number +
    r",\s*Energy Loss:\s*" + number +
    r",\s*Duration Loss:\s*" + number
)

for match in pattern.finditer(log_path.read_text(encoding="utf-8")):
    step = int(match.group(2))
    if not 6000 < step <= 10000:
        continue
    split = (
        "validation" if match.group(1).startswith("Validation") else "train"
    )
    row = {
        "split": split,
        "step": step,
        **dict(zip(names, map(float, match.groups()[2:]))),
    }
    key = (split, step)
    if key in rows and rows[key] != row:
        raise RuntimeError(f"Conflicting loss record: {key}")
    rows[key] = row

training = sorted(
    [r for r in rows.values() if r["split"] == "train"],
    key=lambda r: r["step"],
)
validation = sorted(
    [r for r in rows.values() if r["split"] == "validation"],
    key=lambda r: r["step"],
)

if [r["step"] for r in training] != list(range(100, 10001, 100)):
    raise RuntimeError("Training history is incomplete.")
if [r["step"] for r in validation] != list(range(1000, 10001, 1000)):
    raise RuntimeError("Validation history is incomplete.")

with csv_path.open("w", newline="", encoding="utf-8") as file:
    writer = csv.DictWriter(file, fieldnames=["split", "step", *names])
    writer.writeheader()
    writer.writerows(training + validation)

for data, filename, title in [
    (training, "training_loss.png", "English training — logged minibatches"),
    (validation, "validation_loss.png", "English validation — full split"),
]:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.plot([r["step"] for r in data], [r["total"] for r in data], marker=".")
    ax.set(xlabel="Optimizer step", ylabel="Total loss", title=title)
    ax.grid(alpha=0.3)
    fig.tight_layout()
    fig.savefig(results / filename, dpi=160)
    plt.show()
    plt.close(fig)

best = min(validation, key=lambda r: r["total"])
report = {
    "verified_checkpoints": verified,
    "training_points": len(training),
    "validation_points": len(validation),
    "best_validation_step_so_far": best["step"],
    "best_validation_total_loss": best["total"],
    "final_model_selected": False,
    "status": "PASSED",
}
(records / "english_training_10000_review.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2))
print("No optimizer updates performed.")

from pathlib import Path
import csv
import re

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
csv_path = root / "Results/English/loss_history.csv"

print("=== EXISTING CSV ===")
csv_steps = {"train": set(), "validation": set()}

if csv_path.is_file():
    with csv_path.open(newline="", encoding="utf-8") as file:
        for row in csv.DictReader(file):
            split = row["split"]
            if split not in csv_steps:
                raise RuntimeError(f"Unexpected split label: {split!r}")
            csv_steps[split].add(int(row["step"]))

    for split, steps in csv_steps.items():
        print(
            split,
            "| records:", len(steps),
            "| first:", min(steps) if steps else None,
            "| last:", max(steps) if steps else None,
        )
else:
    print("CSV missing.")

print("\n=== AVAILABLE CONSOLE LOG RECORDS ===")
header = re.compile(
    r"(Validation Step|Step)\s+(\d+)(?:/\d+)?,\s*Total Loss:"
)

for path in sorted(records.glob("english_training*.log")):
    found = {"train": set(), "validation": set()}
    text = path.read_text(encoding="utf-8", errors="replace")

    for match in header.finditer(text):
        split = (
            "validation"
            if match.group(1).startswith("Validation") else "train"
        )
        found[split].add(int(match.group(2)))

    print("\nLog:", path.name)
    for split, steps in found.items():
        print(
            split,
            "| records:", len(steps),
            "| first:", min(steps) if steps else None,
            "| last:", max(steps) if steps else None,
        )

    # Diagnose the exact successful resumed segment.
    if path.name == (
        "english_training_6000_to_10000_20261102T105353454424Z.log"
    ):
        combined_train = {
            step for step in csv_steps["train"] if step <= 6000
        } | {
            step for step in found["train"] if 6000 < step <= 10000
        }
        combined_val = {
            step for step in csv_steps["validation"] if step <= 6000
        } | {
            step for step in found["validation"] if 6000 < step <= 10000
        }
        print("Missing training steps:", sorted(
            set(range(100, 10001, 100)) - combined_train
        ))
        print("Missing validation steps:", sorted(
            set(range(1000, 10001, 1000)) - combined_val
        ))

print("\nNo files changed; no training performed.")

from pathlib import Path
from datetime import datetime, timezone
import csv
import json
import re
import shutil
import matplotlib.pyplot as plt

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
results = root / "Results/English"
csv_path = results / "loss_history.csv"

segments = [
    ("english_training_0_to_1000.log", 1, 1000),
    ("english_training_1000_to_5000.log", 1001, 5000),
    ("english_training_5000_to_10000.log", 5001, 6000),
    (
        "english_training_6000_to_10000_20261102T105353454424Z.log",
        6001, 10000,
    ),
]

names = ["total", "mel", "postnet_mel", "pitch", "energy", "duration"]
number = r"([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)"
pattern = re.compile(
    r"(Validation Step|Step)\s+(\d+)(?:/\d+)?,\s*"
    r"Total Loss:\s*" + number +
    r",\s*Mel Loss:\s*" + number +
    r",\s*Mel PostNet Loss:\s*" + number +
    r",\s*Pitch Loss:\s*" + number +
    r",\s*Energy Loss:\s*" + number +
    r",\s*Duration Loss:\s*" + number
)

rows = {}
provenance = []

for filename, first_step, last_step in segments:
    path = records / filename
    text = path.read_text(encoding="utf-8", errors="replace")
    accepted = 0

    for match in pattern.finditer(text):
        step = int(match.group(2))
        if not first_step <= step <= last_step:
            continue

        split = (
            "validation"
            if match.group(1).startswith("Validation") else "train"
        )
        row = {
            "split": split,
            "step": step,
            **dict(zip(names, map(float, match.groups()[2:]))),
        }
        key = (split, step)
        if key in rows and rows[key] != row:
            raise RuntimeError(f"Conflicting loss record: {key}")
        rows[key] = row
        accepted += 1

    provenance.append({
        "log": filename,
        "accepted_step_range": [first_step, last_step],
        "matched_records": accepted,
    })

training = sorted(
    [r for r in rows.values() if r["split"] == "train"],
    key=lambda r: r["step"],
)
validation = sorted(
    [r for r in rows.values() if r["split"] == "validation"],
    key=lambda r: r["step"],
)

if [r["step"] for r in training] != list(range(100, 10001, 100)):
    raise RuntimeError("Training history remains incomplete. No CSV replaced.")
if [r["step"] for r in validation] != list(range(1000, 10001, 1000)):
    raise RuntimeError("Validation history remains incomplete. No CSV replaced.")

if csv_path.exists():
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = results / f"loss_history_backup_{stamp}.csv"
    shutil.copy2(csv_path, backup)
    print("Previous CSV backed up:", backup.name)

with csv_path.open("w", newline="", encoding="utf-8") as file:
    writer = csv.DictWriter(file, fieldnames=["split", "step", *names])
    writer.writeheader()
    writer.writerows(training + validation)

for data, filename, title in [
    (training, "training_loss.png", "English training — logged minibatches"),
    (validation, "validation_loss.png", "English validation — full split"),
]:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.plot([r["step"] for r in data], [r["total"] for r in data], marker=".")
    ax.set_xlabel("Optimizer step")
    ax.set_ylabel("Total loss (repository objective)")
    ax.set_title(title)
    for resume_step in (1000, 6000):
        ax.axvline(resume_step, color="gray", linestyle=":", alpha=0.5)
    ax.grid(alpha=0.3)
    fig.tight_layout()
    fig.savefig(results / filename, dpi=160)
    plt.show()
    plt.close(fig)

best = min(validation, key=lambda r: r["total"])
report = {
    "training_points": len(training),
    "validation_points": len(validation),
    "best_validation_step_so_far": best["step"],
    "best_validation_total_loss": best["total"],
    "resume_boundaries": [1000, 6000],
    "source_segments": provenance,
    "status": "PASSED",
}
(records / "english_loss_history_through_10000.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2))
print("CSV and graphs updated. No training performed.")

