from pathlib import Path
import os
import subprocess
import sys

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
repo = Path("/content/FastSpeech2_reference")

code = r'''
from pathlib import Path
from types import SimpleNamespace
import json
import numpy as np
import soundfile as sf
import torch
import yaml

from utils.model import get_model, get_vocoder, vocoder_infer

print("GENERATING CHECKPOINT-9000 AUDIO", flush=True)

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable. Share this output.")

device = torch.device("cuda")
configs = tuple(
    yaml.safe_load((root / "English/config" / name).read_text(encoding="utf-8"))
    for name in ("preprocess.yaml", "model.yaml", "train.yaml")
)
preprocess, model_config, train = configs
data = Path(preprocess["path"]["preprocessed_path"])
out_dir = root / "Results/English/diagnostics/step_9000"
out_dir.mkdir(parents=True, exist_ok=True)

previous = json.loads(
    (root / "Results/English/diagnostics/step_6000/sample_record.json")
    .read_text(encoding="utf-8")
)
speaker_id = previous["conditioning_group_id"]
entries = json.loads(
    (root / "English/manifests/test_sentences_tokenized.json")
    .read_text(encoding="utf-8")
)["sentences"]

selected = [entry for entry in entries if entry["id"] in ("E2a", "E2b")]
if sorted(entry["id"] for entry in selected) != ["E2a", "E2b"]:
    raise RuntimeError("Expected E2a and E2b token records are missing.")

model = get_model(
    SimpleNamespace(restore_step=9000), configs, device, train=False
)
model.eval()
vocoder = get_vocoder(model_config, device)
sample_rate = preprocess["preprocessing"]["audio"]["sampling_rate"]

def save_audio(mel, filename):
    if not torch.isfinite(mel).all().item():
        raise RuntimeError("Non-finite mel values.")
    with torch.no_grad():
        waveform = np.asarray(
            vocoder_infer(mel, vocoder, model_config, preprocess)[0]
        )
    if waveform.size == 0 or not np.isfinite(waveform).all():
        raise RuntimeError("Invalid generated waveform.")

    path = out_dir / filename
    sf.write(path, waveform, sample_rate, subtype="PCM_16")
    print("Saved:", path, flush=True)
    return str(path)

matches = [
    line.split("|")
    for line in (data / "val.txt").read_text(encoding="utf-8").splitlines()
    if line.split("|")[0] == previous["utterance"]
]
if len(matches) != 1:
    raise RuntimeError("Reference utterance not uniquely located.")

basename, speaker, _, reference_text = matches[0]
reference_mel = np.load(
    data / "mel" / f"{speaker}-mel-{basename}.npy",
    allow_pickle=False,
)
reference_path = save_audio(
    torch.from_numpy(reference_mel.T.copy()).float().unsqueeze(0).to(device),
    "reference_reconstruction.wav",
)

outputs = []
for entry in selected:
    tokens = torch.tensor([entry["token_ids"]], dtype=torch.long, device=device)
    lengths = torch.tensor([tokens.shape[1]], dtype=torch.long, device=device)
    speakers = torch.tensor([speaker_id], dtype=torch.long, device=device)

    with torch.no_grad():
        prediction = model(speakers, tokens, lengths, tokens.shape[1])

    frames = int(prediction[9][0].item())
    if not 0 < frames <= 4000:
        raise RuntimeError(f"Unexpected predicted length: {frames}")

    path = save_audio(
        prediction[1][0, :frames].transpose(0, 1).unsqueeze(0),
        entry["id"] + ".wav",
    )
    outputs.append({
        "id": entry["id"],
        "original_text": entry["original_text"],
        "synthesis_text": entry["synthesis_text"],
        "checkpoint_step": 9000,
        "conditioning_group_id": speaker_id,
        "wav_path": path,
        "listening_verified": False,
        "final_assignment_sample": False,
    })

(out_dir / "listening_comparison.json").write_text(
    json.dumps({
        "reference_text": reference_text,
        "reference_wav": reference_path,
        "predictions": outputs,
        "optimizer_updates": 0,
    }, indent=2, ensure_ascii=False),
    encoding="utf-8",
)
print("CHECKPOINT-9000 AUDIO GENERATION: PASSED", flush=True)
'''

environment = os.environ.copy()
environment["PYTHONPATH"] = str(repo)
result = subprocess.run(
    [sys.executable, "-u", "-c", code],
    cwd=str(repo),
    env=environment,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
)
print(result.stdout)
print("Exit code:", result.returncode)

(root / "reproducibility/english_step_9000_listening_generation.log").write_text(
    result.stdout, encoding="utf-8"
)
if result.returncode != 0:
    raise RuntimeError("Audio generation failed. Share the complete output.")

from IPython.display import Audio, display

folder = root / "Results/English/diagnostics/step_9000"
for filename in ["reference_reconstruction.wav", "E2a.wav", "E2b.wav"]:
    print(filename)
    display(Audio(filename=str(folder / filename)))

print("No training performed.")

