from pathlib import Path
import io
import re
import zipfile

import pyarrow.parquet as pq
import soundfile as sf
from google.colab import files

base = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
folder = base / "project/Results/English/diagnostics/step_9000"
shard = (
    base / "datasets/Svarah/"
    "ebbf7777fe771490696a3f7b007097606fa8c924/"
    "data/test-00000-of-00003.parquet"
)

if not shard.is_file():
    raise FileNotFoundError(shard)

# Audit index 18 is in the first shard.
batch = next(pq.ParquetFile(shard).iter_batches(
    batch_size=32,
    columns=["audio_filepath", "text"],
))
record = batch.to_pylist()[18]

words = re.findall(r"[a-z]+", record["text"].lower())
if words != ["define", "the", "word", "absolute"]:
    raise RuntimeError(
        "Unexpected source transcript. No audio exported: "
        + repr(record["text"])
    )

encoded = record["audio_filepath"]
if not isinstance(encoded, dict) or not encoded.get("bytes"):
    raise RuntimeError("Expected embedded audio bytes are unavailable.")

audio, sample_rate = sf.read(
    io.BytesIO(encoded["bytes"]),
    dtype="float32",
)
source_path = folder / "original_dataset_recording.wav"
sf.write(source_path, audio, sample_rate, subtype="PCM_16")

reconstruction = folder / "reference_reconstruction.wav"
if not reconstruction.is_file():
    raise FileNotFoundError(reconstruction)

archive = Path("/content/original_vs_reconstruction.zip")
with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as bundle:
    bundle.write(source_path, arcname="A_original_recording.wav")
    bundle.write(reconstruction, arcname="B_vocoder_reconstruction.wav")

print("Source transcript:", record["text"])
print("Original sample rate:", sample_rate)
print("A: original dataset recording")
print("B: real mel passed through the vocoder")
print("No training performed.")
files.download(str(archive))

from pathlib import Path
