import sys

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
repo = Path("/content/FastSpeech2_telugu")

code = r'''
from pathlib import Path
import json
import numpy as np
import torch
import yaml

from dataset import Dataset
from model import FastSpeech2, FastSpeech2Loss
from text import text_to_sequence
from text.symbols import symbols
from utils.tools import to_device

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
config_dir = root / "Telugu/config"
preprocess, model_config, train = tuple(
    yaml.safe_load((config_dir / name).read_text(encoding="utf-8"))
    for name in ("preprocess.yaml", "model.yaml", "train.yaml")
)
data = Path(preprocess["path"]["preprocessed_path"])

if len(symbols) != 405:
    raise RuntimeError(f"Unexpected Telugu symbol count: {len(symbols)}")
symbol_ids = {symbol: index for index, symbol in enumerate(symbols)}
speakers = json.loads((data / "speakers.json").read_text(encoding="utf-8"))
if speakers != {"telugu_female": 0, "telugu_male": 1}:
    raise RuntimeError(f"Unexpected speaker mapping: {speakers}")

keys = {}
metadata = {}
moments = {"pitch": [], "energy": []}

print("TELUGU — RESTORED DATA AND MODEL CHECK", flush=True)

for split, filename, expected in [
    ("train", "train.txt", 1877),
    ("validation", "val.txt", 357),
]:
    lines = (data / filename).read_text(encoding="utf-8").splitlines()
    if len(lines) != expected:
        raise RuntimeError(f"Unexpected {split} count.")
    metadata[split] = lines
    split_keys = set()

    for line in lines:
        fields = line.split("|")
        if len(fields) != 4:
            raise RuntimeError("Malformed metadata.")
        basename, speaker, phone_text, _ = fields
        if speaker not in speakers:
            raise RuntimeError(f"Unknown speaker: {speaker}")
        key = (speaker, basename)
        if key in split_keys:
            raise RuntimeError(f"Duplicate record: {key}")
        split_keys.add(key)

        if not (phone_text.startswith("{") and phone_text.endswith("}")):
            raise RuntimeError(f"Malformed phones: {basename}")
        phones = phone_text[1:-1].split()
        if any("@" + phone not in symbol_ids for phone in phones):
            raise RuntimeError(f"Unsupported phone: {basename}")
        encoded = text_to_sequence(
            phone_text, preprocess["preprocessing"]["text"]["text_cleaners"]
        )
        if encoded != [symbol_ids["@" + phone] for phone in phones]:
            raise RuntimeError(f"Phone encoding mismatch: {basename}")

        arrays = {
            feature: np.load(
                data / feature / f"{speaker}-{feature}-{basename}.npy",
                allow_pickle=False,
            )
            for feature in ("mel", "duration", "pitch", "energy")
        }
        if any(a.size == 0 or not np.isfinite(a).all() for a in arrays.values()):
            raise RuntimeError(f"Invalid feature values: {basename}")

        duration = arrays["duration"]
        mel = arrays["mel"]
        if (
            duration.shape != (len(phones),)
            or not np.issubdtype(duration.dtype, np.integer)
            or (duration < 0).any()
            or mel.ndim != 2
            or mel.shape != (int(duration.sum()), 80)
        ):
            raise RuntimeError(f"Duration/mel mismatch: {basename}")

        for feature in ("pitch", "energy"):
            if arrays[feature].shape != duration.shape:
                raise RuntimeError(f"Feature shape mismatch: {basename}")
            if split == "train":
                moments[feature].append(
                    arrays[feature][duration > 0].astype(np.float64)
                )

    keys[split] = split_keys
    print("[PASS]", split, len(lines), flush=True)

if keys["train"] & keys["validation"]:
    raise RuntimeError("Training/validation record overlap.")

normalized_moments = {}
for feature, chunks in moments.items():
    values = np.concatenate(chunks)
    mean, std = float(values.mean()), float(values.std())
    if abs(mean) > 1e-6 or abs(std - 1) > 1e-6:
        raise RuntimeError(f"Unexpected normalized moments: {feature}")
    normalized_moments[feature] = {"mean": mean, "std": std}

if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable.")
device = torch.device("cuda")
torch.manual_seed(42)
torch.cuda.manual_seed_all(42)

indices = []
for speaker in ("telugu_female", "telugu_male"):
    selected = [
        i for i, line in enumerate(metadata["train"])
        if line.split("|")[1] == speaker
    ][:2]
    if len(selected) != 2:
        raise RuntimeError(f"Insufficient examples: {speaker}")
    indices.extend(selected)

dataset = Dataset(
    "train.txt", preprocess, train, sort=True, drop_last=False
)
batch = to_device(
    dataset.collate_fn([dataset[i] for i in indices])[0], device
)
model = FastSpeech2(preprocess, model_config).to(device)
model.train()
criterion = FastSpeech2Loss(preprocess, model_config).to(device)

print("Running T4 forward/backward check...", flush=True)
predictions = model(*(batch[2:]))
losses = criterion(batch, predictions)
if not all(torch.isfinite(loss).all().item() for loss in losses):
    raise RuntimeError("Non-finite loss.")
losses[0].backward()

gradients = [
    p.grad for p in model.parameters()
    if p.requires_grad and p.grad is not None
]
if not gradients or not all(
    torch.isfinite(g).all().item() for g in gradients
):
    raise RuntimeError("Missing or non-finite gradients.")
nonzero = sum(bool(torch.count_nonzero(g).item()) for g in gradients)
if nonzero == 0:
    raise RuntimeError("All gradients are zero.")

report = {
    "symbol_count": len(symbols),
    "training_clips": len(dataset),
    "validation_clips": len(metadata["validation"]),
    "speaker_ids_in_batch": batch[2].cpu().tolist(),
    "normalized_training_moments": normalized_moments,
    "losses": dict(zip(
        ["total", "mel", "postnet_mel", "pitch", "energy", "duration"],
        [float(loss.item()) for loss in losses],
    )),
    "gradient_tensors": len(gradients),
    "nonzero_gradient_tensors": nonzero,
    "optimizer_updates": 0,
    "status": "PASSED",
}
(root / "reproducibility/telugu_restoration_preflight.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2), flush=True)
'''

environment = os.environ.copy()
environment["PYTHONPATH"] = str(repo)
result = subprocess.run(
    [sys.executable, "-u", "-c", code],
    cwd=str(repo),
    env=environment,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
)
print(result.stdout)
print("Exit code:", result.returncode)
(root / "reproducibility/telugu_restoration_preflight.log").write_text(
    result.stdout, encoding="utf-8"
)
if result.returncode != 0:
    raise RuntimeError("Telugu check failed. Share the complete output.")

print("No optimizer updates performed. Telugu training has not started.")

from pathlib import Path
from uuid import uuid4
import subprocess
import sys
import yaml

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
source_path = root / "English/train.py"
destination = root / "Telugu/train.py"

source = source_path.read_text(encoding="utf-8")
old_repo = "/content/FastSpeech2_reference"
new_repo = "/content/FastSpeech2_telugu"

if source.count(old_repo) != 1:
    raise RuntimeError("English wrapper differs from the expected version.")

source = source.replace(old_repo, new_repo, 1)
source = source.replace("English project configs", "Telugu project configs")

compile(source, str(destination), "exec")
if destination.exists():
    if destination.read_text(encoding="utf-8") != source:
        raise RuntimeError("Different Telugu wrapper exists. No overwrite made.")
else:
    destination.write_text(source, encoding="utf-8")

train_config = yaml.safe_load(
    (root / "Telugu/config/train.yaml").read_text(encoding="utf-8")
)
expected_checkpoint_dir = root / "Telugu/checkpoints"
checkpoint_dir = Path(train_config["path"]["ckpt_path"])

if checkpoint_dir.resolve() != expected_checkpoint_dir.resolve():
    raise RuntimeError("Unexpected Telugu checkpoint directory.")

print("=== TELUGU OUTPUT WRITE CHECK ===")
for folder in [
    checkpoint_dir,
    Path(train_config["path"]["log_path"]) / "train",
    Path(train_config["path"]["log_path"]) / "val",
    Path(train_config["path"]["result_path"]),
]:
    folder.mkdir(parents=True, exist_ok=True)
    probe = folder / f"write_check_{uuid4().hex}.tmp"
    try:
        probe.write_text("check", encoding="utf-8")
        if probe.read_text(encoding="utf-8") != "check":
            raise RuntimeError(f"Write verification failed: {folder}")
    finally:
        if probe.exists():
            probe.unlink()
    print("[PASS]", folder)

print("\n=== WRAPPER INTERFACE ===")
result = subprocess.run(
    [sys.executable, str(destination), "--help"],
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
)
print(result.stdout)
print("Exit code:", result.returncode)

if result.returncode != 0:
    raise RuntimeError("Telugu wrapper check failed.")

print("Saved:", destination)
print("Telugu wrapper and output directories: PASSED")
print("English files unchanged. No training started.")

from pathlib import Path
from datetime import datetime, timezone
import json
import os
import subprocess
import sys
import time
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
checkpoint_dir = root / "Telugu/checkpoints"
final_checkpoint = checkpoint_dir / "1000.pth.tar"

if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable. Training not started.")

if list(checkpoint_dir.glob("*.pth.tar")):
    raise RuntimeError(
        "Telugu checkpoints already exist. Share their filenames "
        "before starting from zero."
    )

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
log_path = records / f"telugu_training_0_to_1000_{stamp}.log"

environment = os.environ.copy()
environment["PYTHONUNBUFFERED"] = "1"
command = [
    sys.executable, "-u", str(root / "Telugu/train.py"),
    "--restore_step", "0",
    "--stop_step", "1000",
    "--seed", "42",
]

print("TELUGU TRAINING: 0 → 1000", flush=True)
print("GPU:", torch.cuda.get_device_name(0), flush=True)
print("Full log:", log_path, flush=True)
started = time.monotonic()

with log_path.open("x", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    try:
        for line in process.stdout:
            log.write(line)
            log.flush()
            if line.strip() and not line.lstrip().startswith(
                ("Training:", "Epoch ")
            ):
                print(line, end="", flush=True)
        exit_code = process.wait()
    except KeyboardInterrupt:
        process.terminate()
        process.wait()
        print("\nInterrupted. Preserve any saved Telugu checkpoints.", flush=True)
        raise

summary = {
    "language": "Telugu",
    "restore_step": 0,
    "requested_final_step": 1000,
    "exit_code": exit_code,
    "elapsed_minutes": (time.monotonic() - started) / 60,
    "checkpoint": str(final_checkpoint),
    "checkpoint_exists": final_checkpoint.is_file(),
    "checkpoint_bytes": (
        final_checkpoint.stat().st_size
        if final_checkpoint.is_file() else None
    ),
    "console_log": str(log_path),
    "checkpoint_contents_verified": False,
}
log_path.with_suffix(".json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)
print("\n=== TELUGU EXECUTION SUMMARY ===")
print(json.dumps(summary, indent=2))

if exit_code != 0:
    raise RuntimeError("Telugu training failed. Share the complete traceback.")
if not final_checkpoint.is_file() or final_checkpoint.stat().st_size == 0:
    raise RuntimeError("Expected checkpoint is missing or empty.")

print("Segment completed. Losses and checkpoint require review.")

