from pathlib import Path
import csv
import json
import re
import matplotlib.pyplot as plt
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
results = root / "Results/Telugu"
results.mkdir(parents=True, exist_ok=True)

print("TELUGU — CHECKPOINT AND LOSS REVIEW THROUGH 5000")

checkpoint_path = root / "Telugu/checkpoints/5000.pth.tar"
checkpoint = torch.load(
    checkpoint_path, map_location="cpu", weights_only=True
)

for name, value in checkpoint["model"].items():
    if torch.is_tensor(value) and not torch.isfinite(value).all().item():
        raise RuntimeError(f"Non-finite model tensor: {name}")

states = checkpoint["optimizer"]["state"]
if not states:
    raise RuntimeError("Optimizer state is empty.")

steps = set()
for parameter_id, state in states.items():
    step = state["step"]
    steps.add(int(step.item() if torch.is_tensor(step) else step))
    for name, value in state.items():
        if torch.is_tensor(value) and not torch.isfinite(value).all().item():
            raise RuntimeError(f"Non-finite optimizer state: {parameter_id}/{name}")

if steps != {5000}:
    raise RuntimeError(f"Unexpected Adam update counts: {steps}")

del checkpoint, states, state, value
print("[PASS] Checkpoint 5000")

log_paths = [
    records / "telugu_training_0_to_1000_20261102T135621863947Z.log",
    records / "telugu_training_1000_to_5000_20261102T140539906752Z.log",
]
names = ["total", "mel", "postnet_mel", "pitch", "energy", "duration"]
number = r"([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)"
pattern = re.compile(
    r"(Validation Step|Step)\s+(\d+)(?:/\d+)?,\s*"
    r"Total Loss:\s*" + number +
    r",\s*Mel Loss:\s*" + number +
    r",\s*Mel PostNet Loss:\s*" + number +
    r",\s*Pitch Loss:\s*" + number +
    r",\s*Energy Loss:\s*" + number +
    r",\s*Duration Loss:\s*" + number
)
rows = {}

for path in log_paths:
    for match in pattern.finditer(path.read_text(encoding="utf-8")):
        step = int(match.group(2))
        if not 0 < step <= 5000:
            continue
        split = (
            "validation" if match.group(1).startswith("Validation") else "train"
        )
        row = {
            "split": split, "step": step,
            **dict(zip(names, map(float, match.groups()[2:]))),
        }
        key = (split, step)
        if key in rows and rows[key] != row:
            raise RuntimeError(f"Conflicting loss record: {key}")
        rows[key] = row

training = sorted(
    [r for r in rows.values() if r["split"] == "train"],
    key=lambda r: r["step"],
)
validation = sorted(
    [r for r in rows.values() if r["split"] == "validation"],
    key=lambda r: r["step"],
)

if [r["step"] for r in training] != list(range(100, 5001, 100)):
    raise RuntimeError("Training loss history incomplete.")
if [r["step"] for r in validation] != list(range(1000, 5001, 1000)):
    raise RuntimeError("Validation loss history incomplete.")

with (results / "loss_history.csv").open(
    "w", newline="", encoding="utf-8"
) as file:
    writer = csv.DictWriter(file, fieldnames=["split", "step", *names])
    writer.writeheader()
    writer.writerows(training + validation)

for values, filename, title in [
    (training, "training_loss.png", "Telugu training — logged minibatches"),
    (validation, "validation_loss.png", "Telugu validation — full split"),
]:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.plot(
        [r["step"] for r in values],
        [r["total"] for r in values],
        marker=".",
    )
    ax.axvline(1000, color="gray", linestyle=":", alpha=0.4)
    ax.set(xlabel="Optimizer step", ylabel="Total loss", title=title)
    ax.grid(alpha=0.3)
    fig.tight_layout()
    fig.savefig(results / filename, dpi=160)
    plt.show()
    plt.close(fig)

best = min(validation, key=lambda r: r["total"])
report = {
    "language": "Telugu",
    "verified_checkpoint": 5000,
    "training_points": len(training),
    "validation_points": len(validation),
    "best_validation_step_so_far": best["step"],
    "best_validation_total_loss": best["total"],
    "final_model_selected": False,
    "status": "PASSED",
}
(records / "telugu_training_5000_review.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2))
print("No training performed.")

from pathlib import Path
import os
import subprocess
import sys

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
repo = Path("/content/FastSpeech2_telugu")

code = r'''
from pathlib import Path
from types import SimpleNamespace
import json
import numpy as np
import soundfile as sf
import torch
import yaml

from dataset import Dataset
from utils.model import get_model, get_vocoder, vocoder_infer
from utils.tools import to_device

print("TELUGU STEP 5000 — TWO-SPEAKER AUDIO CHECK", flush=True)
if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable.")
device = torch.device("cuda")

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
configs = tuple(
    yaml.safe_load((root / "Telugu/config" / name).read_text(encoding="utf-8"))
    for name in ("preprocess.yaml", "model.yaml", "train.yaml")
)
preprocess, model_config, train = configs
data = Path(preprocess["path"]["preprocessed_path"])
lines = (data / "val.txt").read_text(encoding="utf-8").splitlines()
dataset = Dataset(
    "val.txt", preprocess, train, sort=False, drop_last=False
)

# Deterministic selection: first moderate-length sentence per speaker.
selected = []
for speaker in ("telugu_female", "telugu_male"):
    candidates = [
        i for i, line in enumerate(lines)
        if line.split("|")[1] == speaker
        and 30 <= len(line.split("|")[2][1:-1].split()) <= 100
    ]
    if not candidates:
        raise RuntimeError(f"No suitable validation sample: {speaker}")
    selected.append((speaker, candidates[0]))

model = get_model(
    SimpleNamespace(restore_step=5000), configs, device, train=False
)
model.eval()
vocoder = get_vocoder(model_config, device)
sr = preprocess["preprocessing"]["audio"]["sampling_rate"]
folder = root / "Results/Telugu/diagnostics/step_5000"
folder.mkdir(parents=True, exist_ok=True)
reports = []

for speaker, index in selected:
    batch = to_device(dataset.collate_fn([dataset[index]])[0], device)
    with torch.no_grad():
        prediction = model(*(batch[2:6]))

    predicted_frames = int(prediction[9][0].item())
    reference_frames = int(batch[7][0].item())
    if not 0 < predicted_frames <= 4000:
        raise RuntimeError(f"Unexpected predicted length: {speaker}")

    outputs = {}
    for label, mel in [
        ("reference", batch[6][0, :reference_frames]),
        ("prediction", prediction[1][0, :predicted_frames]),
    ]:
        if not torch.isfinite(mel).all().item():
            raise RuntimeError(f"Non-finite mel: {speaker}/{label}")

        with torch.no_grad():
            waveform = np.asarray(vocoder_infer(
                mel.T.unsqueeze(0), vocoder, model_config, preprocess
            )[0])
        if waveform.size == 0 or not np.isfinite(waveform).all():
            raise RuntimeError(f"Invalid waveform: {speaker}/{label}")

        path = folder / f"{speaker}_{label}.wav"
        sf.write(path, waveform, sr, subtype="PCM_16")
        outputs[label] = str(path)
        print("Saved:", path, flush=True)

    report = {
        "speaker": speaker,
        "utterance": str(batch[0][0]),
        "text": str(batch[1][0]),
        "checkpoint_step": 5000,
        "outputs": outputs,
        "listening_verified": False,
        "final_assignment_sample": False,
    }
    reports.append(report)
    print("Speaker:", speaker, flush=True)
    print("Expected text:", report["text"], flush=True)

(folder / "listening_comparison.json").write_text(
    json.dumps({
        "samples": reports,
        "optimizer_updates": 0,
    }, indent=2, ensure_ascii=False),
    encoding="utf-8",
)
transcripts = "\n\n".join(
    f"{item['speaker']}\n{item['text']}" for item in reports
)
(folder / "TRANSCRIPTS.txt").write_text(transcripts, encoding="utf-8")
print("TELUGU DIAGNOSTIC GENERATION: PASSED", flush=True)
'''

environment = os.environ.copy()
environment["PYTHONPATH"] = str(repo)
result = subprocess.run(
    [sys.executable, "-u", "-c", code],
    cwd=str(repo),
    env=environment,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
)
print(result.stdout)
print("Exit code:", result.returncode)
(root / "reproducibility/telugu_step_5000_listening_generation.log").write_text(
    result.stdout, encoding="utf-8"
)
if result.returncode != 0:
    raise RuntimeError("Telugu generation failed. Share the complete output.")

import zipfile
from google.colab import files

folder = root / "Results/Telugu/diagnostics/step_5000"
archive = Path("/content/telugu_step_5000_listening.zip")
with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as bundle:
    for speaker in ("telugu_female", "telugu_male"):
        for label in ("reference", "prediction"):
            name = f"{speaker}_{label}.wav"
            bundle.write(folder / name, arcname=name)
    bundle.write(folder / "TRANSCRIPTS.txt", arcname="TRANSCRIPTS.txt")

files.download(str(archive))
