import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
checkpoint_dir = root / "Telugu/checkpoints"
start_step, stop_step = 5000, 10000

if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable. Training not started.")
if not (checkpoint_dir / f"{start_step}.pth.tar").is_file():
    raise FileNotFoundError(f"Missing checkpoint {start_step}.")

newer = [
    path.name for path in checkpoint_dir.glob("*.pth.tar")
    if path.name.split(".")[0].isdigit()
    and int(path.name.split(".")[0]) > start_step
]
if newer:
    raise RuntimeError(
        f"Newer Telugu checkpoints exist: {newer}. Share this output."
    )

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
log_path = records / f"telugu_training_5000_to_10000_{stamp}.log"
final_checkpoint = checkpoint_dir / "10000.pth.tar"

environment = os.environ.copy()
environment["PYTHONUNBUFFERED"] = "1"
command = [
    sys.executable, "-u", str(root / "Telugu/train.py"),
    "--restore_step", str(start_step),
    "--stop_step", str(stop_step),
    "--seed", "42",
]

print("TELUGU TRAINING: 5000 → 10000", flush=True)
print("GPU:", torch.cuda.get_device_name(0), flush=True)
print("Full log:", log_path, flush=True)
started = time.monotonic()

with log_path.open("x", encoding="utf-8") as log:
    process = subprocess.Popen(
        command,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    try:
        for line in process.stdout:
            log.write(line)
            log.flush()
            if line.strip() and not line.lstrip().startswith(
                ("Training:", "Epoch ")
            ):
                print(line, end="", flush=True)
        exit_code = process.wait()
    except KeyboardInterrupt:
        process.terminate()
        process.wait()
        print("\nInterrupted. Preserve saved Telugu checkpoints.", flush=True)
        raise

summary = {
    "language": "Telugu",
    "restore_step": start_step,
    "requested_final_step": stop_step,
    "exit_code": exit_code,
    "elapsed_minutes": (time.monotonic() - started) / 60,
    "checkpoint": str(final_checkpoint),
    "checkpoint_exists": final_checkpoint.is_file(),
    "checkpoint_bytes": (
        final_checkpoint.stat().st_size
        if final_checkpoint.is_file() else None
    ),
    "console_log": str(log_path),
    "checkpoint_contents_verified": False,
}
log_path.with_suffix(".json").write_text(
    json.dumps(summary, indent=2), encoding="utf-8"
)

print("\n=== TELUGU EXECUTION SUMMARY ===")
print(json.dumps(summary, indent=2))

if exit_code != 0:
    raise RuntimeError("Training failed. Share the complete traceback.")
if not final_checkpoint.is_file() or final_checkpoint.stat().st_size == 0:
    raise RuntimeError("Final checkpoint missing or empty.")

print("Segment completed. Checkpoint and validation trend need review.")

from pathlib import Path
from datetime import datetime, timezone
import csv
import gc
import json
import re
import shutil
import matplotlib.pyplot as plt
import torch

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
records = root / "reproducibility"
results = root / "Results/Telugu"

print("TELUGU — REVIEW THROUGH STEP 10000")

for expected in (8000, 10000):
    path = root / f"Telugu/checkpoints/{expected}.pth.tar"
    checkpoint = torch.load(path, map_location="cpu", weights_only=True)

    for value in checkpoint["model"].values():
        if torch.is_tensor(value) and not torch.isfinite(value).all().item():
            raise RuntimeError(f"Non-finite model tensor: step {expected}")

    states = checkpoint["optimizer"]["state"]
    if not states:
        raise RuntimeError("Optimizer state is empty.")

    steps = set()
    for state in states.values():
        step = state["step"]
        steps.add(int(step.item() if torch.is_tensor(step) else step))
        for value in state.values():
            if torch.is_tensor(value) and not torch.isfinite(value).all().item():
                raise RuntimeError(f"Non-finite optimizer state: step {expected}")

    if steps != {expected}:
        raise RuntimeError(f"Unexpected Adam update counts: {steps}")

    print(f"[PASS] Checkpoint {expected}")
    del checkpoint, states, state, value
    gc.collect()

csv_path = results / "loss_history.csv"
names = ["total", "mel", "postnet_mel", "pitch", "energy", "duration"]
rows = {}

with csv_path.open(newline="", encoding="utf-8") as file:
    for row in csv.DictReader(file):
        step = int(row["step"])
        if step <= 5000:
            rows[(row["split"], step)] = {
                "split": row["split"], "step": step,
                **{name: float(row[name]) for name in names},
            }

log_path = records / (
    "telugu_training_5000_to_10000_20261102T143942186434Z.log"
)
number = r"([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)"
pattern = re.compile(
    r"(Validation Step|Step)\s+(\d+)(?:/\d+)?,\s*"
    r"Total Loss:\s*" + number +
    r",\s*Mel Loss:\s*" + number +
    r",\s*Mel PostNet Loss:\s*" + number +
    r",\s*Pitch Loss:\s*" + number +
    r",\s*Energy Loss:\s*" + number +
    r",\s*Duration Loss:\s*" + number
)

for match in pattern.finditer(log_path.read_text(encoding="utf-8")):
    step = int(match.group(2))
    if not 5000 < step <= 10000:
        continue
    split = "validation" if match.group(1).startswith("Validation") else "train"
    row = {
        "split": split, "step": step,
        **dict(zip(names, map(float, match.groups()[2:]))),
    }
    key = (split, step)
    if key in rows and rows[key] != row:
        raise RuntimeError(f"Conflicting loss record: {key}")
    rows[key] = row

training = sorted(
    [r for r in rows.values() if r["split"] == "train"],
    key=lambda r: r["step"],
)
validation = sorted(
    [r for r in rows.values() if r["split"] == "validation"],
    key=lambda r: r["step"],
)

if [r["step"] for r in training] != list(range(100, 10001, 100)):
    raise RuntimeError("Training history incomplete. No CSV replaced.")
if [r["step"] for r in validation] != list(range(1000, 10001, 1000)):
    raise RuntimeError("Validation history incomplete. No CSV replaced.")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
shutil.copy2(csv_path, results / f"loss_history_backup_{stamp}.csv")

with csv_path.open("w", newline="", encoding="utf-8") as file:
    writer = csv.DictWriter(file, fieldnames=["split", "step", *names])
    writer.writeheader()
    writer.writerows(training + validation)

for values, filename, title in [
    (training, "training_loss.png", "Telugu training — logged minibatches"),
    (validation, "validation_loss.png", "Telugu validation — full split"),
]:
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.plot(
        [r["step"] for r in values],
        [r["total"] for r in values],
        marker=".",
    )
    for boundary in (1000, 5000):
        ax.axvline(boundary, color="gray", linestyle=":", alpha=0.4)
    ax.set(xlabel="Optimizer step", ylabel="Total loss", title=title)
    ax.grid(alpha=0.3)
    fig.tight_layout()
    fig.savefig(results / filename, dpi=160)
    plt.show()
    plt.close(fig)

best = min(validation, key=lambda r: r["total"])
report = {
    "language": "Telugu",
    "verified_checkpoints": [8000, 10000],
    "training_points": len(training),
    "validation_points": len(validation),
    "best_validation_step_so_far": best["step"],
    "best_validation_total_loss": best["total"],
    "final_model_selected": False,
    "status": "PASSED",
}
(records / "telugu_training_10000_review.json").write_text(
    json.dumps(report, indent=2), encoding="utf-8"
)
print(json.dumps(report, indent=2))
print("No training performed.")

from pathlib import Path
import os
import subprocess
import sys

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
repo = Path("/content/FastSpeech2_telugu")

code = r'''
from pathlib import Path
from types import SimpleNamespace
import json
import numpy as np
import soundfile as sf
import torch
import yaml

from dataset import Dataset
from utils.model import get_model, get_vocoder, vocoder_infer
from utils.tools import to_device

print("TELUGU STEP 8000 — SAME-SENTENCE AUDIO CHECK", flush=True)
if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable.")
device = torch.device("cuda")

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
configs = tuple(
    yaml.safe_load((root / "Telugu/config" / name).read_text(encoding="utf-8"))
    for name in ("preprocess.yaml", "model.yaml", "train.yaml")
)
preprocess, model_config, train = configs
data = Path(preprocess["path"]["preprocessed_path"])
lines = (data / "val.txt").read_text(encoding="utf-8").splitlines()

previous = json.loads(
    (root / "Results/Telugu/diagnostics/step_5000/listening_comparison.json")
    .read_text(encoding="utf-8")
)
dataset = Dataset(
    "val.txt", preprocess, train, sort=False, drop_last=False
)
model = get_model(
    SimpleNamespace(restore_step=8000), configs, device, train=False
)
model.eval()
vocoder = get_vocoder(model_config, device)
sr = preprocess["preprocessing"]["audio"]["sampling_rate"]

folder = root / "Results/Telugu/diagnostics/step_8000"
folder.mkdir(parents=True, exist_ok=True)
reports = []

for sample in previous["samples"]:
    speaker = sample["speaker"]
    matches = [
        i for i, line in enumerate(lines)
        if line.split("|")[0] == sample["utterance"]
        and line.split("|")[1] == speaker
    ]
    if len(matches) != 1:
        raise RuntimeError(f"Validation sample match failed: {speaker}")

    batch = to_device(dataset.collate_fn([dataset[matches[0]]])[0], device)
    with torch.no_grad():
        prediction = model(*(batch[2:6]))
        frames = int(prediction[9][0].item())
        if not 0 < frames <= 4000:
            raise RuntimeError(f"Unexpected mel length: {speaker}/{frames}")

        mel = prediction[1][0, :frames].T.unsqueeze(0)
        if not torch.isfinite(mel).all().item():
            raise RuntimeError(f"Non-finite mel: {speaker}")

        waveform = np.asarray(vocoder_infer(
            mel, vocoder, model_config, preprocess
        )[0])

    if waveform.size == 0 or not np.isfinite(waveform).all():
        raise RuntimeError(f"Invalid waveform: {speaker}")

    path = folder / f"{speaker}_prediction.wav"
    sf.write(path, waveform, sr, subtype="PCM_16")
    reports.append({
        "speaker": speaker,
        "utterance": str(batch[0][0]),
        "text": str(batch[1][0]),
        "checkpoint_step": 8000,
        "wav_path": str(path),
        "listening_verified": False,
        "final_assignment_sample": False,
    })
    print("Saved:", path, flush=True)
    print("Expected text:", str(batch[1][0]), flush=True)

(folder / "listening_comparison.json").write_text(
    json.dumps({"samples": reports, "optimizer_updates": 0},
               indent=2, ensure_ascii=False),
    encoding="utf-8",
)
(folder / "TRANSCRIPTS.txt").write_text(
    "\n\n".join(f"{r['speaker']}\n{r['text']}" for r in reports),
    encoding="utf-8",
)
print("STEP-8000 AUDIO GENERATION: PASSED", flush=True)
'''

environment = os.environ.copy()
environment["PYTHONPATH"] = str(repo)
result = subprocess.run(
    [sys.executable, "-u", "-c", code],
    cwd=str(repo),
    env=environment,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
)
print(result.stdout)
print("Exit code:", result.returncode)
(root / "reproducibility/telugu_step_8000_listening_generation.log").write_text(
    result.stdout, encoding="utf-8"
)
if result.returncode != 0:
    raise RuntimeError("Generation failed. Share the complete output.")

import zipfile
from google.colab import files

folder = root / "Results/Telugu/diagnostics/step_8000"
archive = Path("/content/telugu_5000_vs_8000.zip")

with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as bundle:
    for step in (5000, 8000):
        for speaker in ("telugu_female", "telugu_male"):
            path = (
                root / f"Results/Telugu/diagnostics/step_{step}/"
                f"{speaker}_prediction.wav"
            )
            bundle.write(path, arcname=f"step{step}_{speaker}.wav")
    bundle.write(folder / "TRANSCRIPTS.txt", arcname="TRANSCRIPTS.txt")

files.download(str(archive))
print("No training performed.")

from pathlib import Path
