from pathlib import Path
import json
import re
import unicodedata

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
manifest_dir = root / "Telugu/manifests"

sentences = [
    {
        "id": "T1",
        "original_text":
            "న్యూరోఫార్మకోలాజికల్ పరిశోధనలో నూతన ఔషధాల ప్రభావాన్ని విశ్లేషించారు.",
    },
    {
        "id": "T2a",
        "original_text":
            "తాడుపై అతని పట్టు చాలా బలంగా ఉంది.",
    },
    {
        "id": "T2b",
        "original_text":
            "ఆమె పట్టు చీరను ధరించి వేడుకకు వచ్చింది.",
    },
    {
        "id": "T3",
        "original_text":
            "పులి అడ  విలో నిశ్శబ్దంగా నడిచింది.",
    },
    {
        "id": "T4",
        "original_text":
            "ఈ సమావేశం 2026 నవంబర్ 12వ తేదీ ఉదయం 10:45 గంటలకు ప్రారంభమవుతుంది, సమయానికి సిద్ధంగా ఉండండి.",
    },
]

assert "అడ  విలో" in sentences[3]["original_text"]
assert "అడ   విలో" not in sentences[3]["original_text"]

# Comparison keys only: original sentences remain unchanged.
def comparison_key(text):
    text = unicodedata.normalize("NFC", text)
    text = "".join(
        " " if unicodedata.category(char).startswith("P") else char
        for char in text
    )
    return re.sub(r"\s+", " ", text).strip().casefold()

test_keys = {
    comparison_key(entry["original_text"]): entry["id"]
    for entry in sentences
}

split_files = {
    "train": manifest_dir / "train_alignment_available.jsonl",
    "validation": manifest_dir / "validation_alignment_available.jsonl",
}

matches = []
counts = {}
for split, path in split_files.items():
    if not path.is_file():
        raise FileNotFoundError(path)

    count = 0
    with path.open(encoding="utf-8") as file:
        for line in file:
            if not line.strip():
                continue
            record = json.loads(line)
            count += 1
            key = comparison_key(record["text"])
            if key in test_keys:
                matches.append({
                    "split": split,
                    "test_id": test_keys[key],
                    "record_index": record["index"],
                })
    counts[split] = count

if matches:
    raise RuntimeError(
        "Test-text overlap found. Share this output before proceeding:\n"
        + json.dumps(matches, indent=2, ensure_ascii=False)
    )

document = {
    "verification": "User confirmed against assignment",
    "T3_two_spaces_confirmed": True,
    "normalization_applied_to_originals": False,
    "overlap_check": {
        "method": "NFC, punctuation and whitespace comparison keys",
        "records_checked": counts,
        "matching_records": matches,
    },
    "sentences": sentences,
}

path = manifest_dir / "test_sentences_confirmed.json"
content = json.dumps(document, indent=2, ensure_ascii=False)
if path.exists() and path.read_text(encoding="utf-8") != content:
    raise RuntimeError("Different confirmed file exists. No overwrite made.")
path.write_text(content, encoding="utf-8")

for entry in sentences:
    print(entry["id"], repr(entry["original_text"]))

print("\nSaved:", path)
print("Test-text overlap check: PASSED")
print("Original candidate preserved. No audio generated or training performed.")

