from pathlib import Path
import json
import shutil
import subprocess

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
log_path = root / "reproducibility/stage9_telugu_espeak_restore.log"
outputs = []

def run(command):
    print("Running:", " ".join(command), flush=True)
    result = subprocess.run(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )
    print(result.stdout)
    outputs.append(
        "$ " + " ".join(command) + "\n" + result.stdout
    )
    log_path.write_text("\n\n".join(outputs), encoding="utf-8")
    if result.returncode != 0:
        raise RuntimeError(
            f"Command failed with exit code {result.returncode}. "
            "Share the complete output."
        )
    return result.stdout.strip()

if shutil.which("espeak-ng") is None:
    run(["apt-get", "update", "-qq"])
    run(["apt-get", "install", "-y", "--no-install-recommends", "espeak-ng"])

version = run(["espeak-ng", "--version"])
voices = run(["espeak-ng", "--voices=te"])
pronunciation = run([
    "espeak-ng", "-q", "-v", "te", "--ipa", "--sep=|", "తెలుగు"
])

if not pronunciation:
    raise RuntimeError("Empty Telugu pronunciation output.")

print("\n=== RESTORATION CHECK ===")
print(json.dumps({
    "version": version,
    "test_word": "తెలుగు",
    "separated_IPA": pronunciation,
    "previous_training_tool_version": "1.51",
    "status": "EXECUTION_PASSED",
}, indent=2, ensure_ascii=False))
print("Log saved:", log_path)
print("No model symbols changed. No training or model audio generation performed.")

from pathlib import Path
import importlib.util
import json

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
telugu = root / "Telugu"

confirmed = json.loads(
    (telugu / "manifests/test_sentences_confirmed.json")
    .read_text(encoding="utf-8")
)
mapping = json.loads(
    (telugu / "lexicon/phone_mapping.json").read_text(encoding="utf-8")
)["ipa_to_token"]

# Load the saved standalone frontend without importing either model repository.
spec = importlib.util.spec_from_file_location(
    "saved_telugu_frontend", telugu / "text_frontend.py"
)
frontend = importlib.util.module_from_spec(spec)
spec.loader.exec_module(frontend)

prepared = []
pronunciation_cache = {}

for entry in confirmed["sentences"]:
    original = entry["original_text"]
    synthesis = original
    rules = []

    if entry["id"] == "T4":
        replacements = [
            ("2026", "రెండు వేల ఇరవై ఆరు"),
            ("12వ", "పన్నెండవ"),
            (
                "ఉదయం 10:45 గంటలకు",
                "ఉదయం పది గంటల నలభై ఐదు నిమిషాలకు",
            ),
        ]
        for source, replacement in replacements:
            if synthesis.count(source) != 1:
                raise RuntimeError(f"Unexpected occurrence count: {source}")
            synthesis = synthesis.replace(source, replacement, 1)
            rules.append({
                "action": "spoken_expansion",
                "source": source,
                "replacement": replacement,
            })

    normalized = frontend.normalize_training_text(synthesis)
    rules.append({
        "action": "existing_training_normalization",
        "details": "NFC; punctuation to spaces; collapse whitespace",
    })
    if entry["id"] == "T3":
        if "అడ  విలో" not in original or "అడ విలో" not in normalized:
            raise RuntimeError("T3 split-spelling preservation failed.")
        rules.append({
            "action": "preserve_split_spelling",
            "details": "Do not join అడ and విలో into a single word.",
        })

    word_records = []
    all_phones = []
    unsupported = []

    for word in normalized.split():
        if word not in pronunciation_cache:
            pronunciation_cache[word] = frontend.phonemize_word(word)
        phones = pronunciation_cache[word]
        missing = sorted(set(phones) - set(mapping))
        word_records.append({
            "word": word,
            "ipa_phones": phones,
            "unsupported_phones": missing,
        })
        all_phones.extend(phones)
        if missing:
            unsupported.append({"word": word, "phones": missing})

    prepared.append({
        "id": entry["id"],
        "original_text": original,
        "synthesis_text": synthesis,
        "normalized_text": normalized,
        "normalization_rules": rules,
        "words": word_records,
        "ipa_phones": all_phones,
        "model_phones": (
            [mapping[phone] for phone in all_phones]
            if not unsupported else None
        ),
        "unsupported": unsupported,
        "phone_coverage": "PASSED" if not unsupported else "BLOCKED",
        "pronunciation_accuracy_verified": False,
        "audio_generated": False,
    })

    print(f"\n=== {entry['id']} ===")
    print("Original:", repr(original))
    print("Synthesis text:", synthesis)
    print("Normalized text:", normalized)
    print("IPA phones:", " ".join(all_phones))
    print("Phone coverage:", prepared[-1]["phone_coverage"])
    print("Unsupported:", unsupported)

document = {
    "source": "Confirmed assignment sentences",
    "number_expansions_status": "Proposed; displayed for review",
    "sentences": prepared,
}
path = telugu / "manifests/test_sentences_prepared.json"
content = json.dumps(document, indent=2, ensure_ascii=False)
if path.exists() and path.read_text(encoding="utf-8") != content:
    raise RuntimeError("Different preparation file exists. No overwrite made.")
path.write_text(content, encoding="utf-8")

print("\nSaved:", path)
print("Confirmed originals unchanged.")
print("Model token encoding remains untested in this runtime.")
print("No model audio generated or training performed.")

from pathlib import Path
import hashlib
import importlib.metadata
import shutil
import tarfile
import tempfile
import torch

base = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
root = base / "project"
repo = Path("/content/FastSpeech2_telugu")
metadata_dir = Path("/content/fastspeech2_features/telugu_processed")

source_archive = root / "reproducibility/FastSpeech2_upstream_d4e79eb52e8b.tar.gz"
data_archive = base / "processed_data/Telugu/telugu_processed.tar.gz"
vocoder = base / "vocoder/UNIVERSAL_V1/g_02500000"

patches = {
    "audio/audio_processing.py":
        root / "upstream_modified/audio/audio_processing.py",
    "audio/stft.py":
        root / "upstream_modified/audio/stft.py",
    "preprocessor/preprocessor.py":
        root / "upstream_modified/preprocessor/preprocessor.py",
    "model/optimizer.py":
        root / "Telugu/upstream_modified/model/optimizer.py",
    "utils/model.py":
        root / "Telugu/upstream_modified/utils/model.py",
    "text/symbols.py":
        root / "Telugu/upstream_modified/text/symbols.py",
}

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

for path in [source_archive, data_archive, vocoder, *patches.values()]:
    if not path.is_file():
        raise FileNotFoundError(path)

if sha256(source_archive) != (
    "48a507d44986adf54a401e58f4ad8be87"
    "bb4f4602621aa4da0d7a05af85f3ac6"
):
    raise RuntimeError("Source archive hash mismatch.")

vocoder_hash = (
    "771eaf4876485a35e25577563d390c262"
    "e23c2421e4a8c929eacfde34a5b7a60"
)
if sha256(vocoder) != vocoder_hash:
    raise RuntimeError("Vocoder hash mismatch.")

if not repo.exists():
    print("Restoring Telugu repository...", flush=True)
    with tempfile.TemporaryDirectory(dir="/content") as temporary:
        temporary = Path(temporary)
        with tarfile.open(source_archive, "r:gz") as archive:
            archive.extractall(temporary, filter="data")
        extracted = temporary / "FastSpeech2"

        for relative, saved in patches.items():
            target = extracted / relative
            if not target.is_file():
                raise FileNotFoundError(target)
            shutil.copy2(saved, target)
            compile(target.read_text(encoding="utf-8"), str(target), "exec")

        shutil.copy2(
            vocoder, extracted / "hifigan/generator_universal.pth.tar"
        )
        shutil.move(str(extracted), str(repo))

# Verify existing/restored files without overwriting differences.
for relative, saved in patches.items():
    if sha256(repo / relative) != sha256(saved):
        raise RuntimeError(f"Local patch differs: {relative}")
if sha256(repo / "hifigan/generator_universal.pth.tar") != vocoder_hash:
    raise RuntimeError("Local vocoder differs.")

metadata_dir.mkdir(parents=True, exist_ok=True)
with tarfile.open(data_archive, "r:gz") as archive:
    members = archive.getmembers()
    for name in ("stats.json", "speakers.json"):
        matches = [
            member for member in members
            if member.isfile() and Path(member.name).name == name
        ]
        if len(matches) != 1:
            raise RuntimeError(f"Expected one archived {name}.")
        stream = archive.extractfile(matches[0])
        if stream is None:
            raise RuntimeError(f"Cannot read {name}.")
        content = stream.read()
        destination = metadata_dir / name
        if destination.exists() and destination.read_bytes() != content:
            raise RuntimeError(f"Different existing metadata: {name}")
        destination.write_bytes(content)
        print("Inference metadata verified:", name)

print("\n=== RUNTIME ===")
print("PyTorch:", torch.__version__)
print("CUDA available:", torch.cuda.is_available())
if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))

print("\n=== IMPORT DEPENDENCIES ===")
for package in ("Unidecode", "inflect", "PyYAML"):
    try:
        print(package, importlib.metadata.version(package))
    except importlib.metadata.PackageNotFoundError:
        print(package, "NOT INSTALLED")

print("\nRepository patches and vocoder: VERIFIED")
print("Only inference metadata restored; full feature restoration not required.")
print("Imports and model token encoding remain pending.")
print("No model audio generated or training performed.")

