from pathlib import Path
import hashlib
import shutil
import tarfile
import tempfile

base = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
root = base / "project"
repo = Path("/content/FastSpeech2_reference")
metadata_dir = Path("/content/fastspeech2_features/english_processed")

source_archive = root / "reproducibility/FastSpeech2_upstream_d4e79eb52e8b.tar.gz"
data_archive = base / "processed_data/English/english_processed.tar.gz"
vocoder = base / "vocoder/UNIVERSAL_V1/g_02500000"

patches = {
    "audio/audio_processing.py":
        root / "upstream_modified/audio/audio_processing.py",
    "audio/stft.py":
        root / "upstream_modified/audio/stft.py",
    "preprocessor/preprocessor.py":
        root / "upstream_modified/preprocessor/preprocessor.py",
    "model/optimizer.py":
        root / "English/upstream_modified/model/optimizer.py",
    "utils/model.py":
        root / "English/upstream_modified/utils/model.py",
}

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

for path in [source_archive, data_archive, vocoder, *patches.values()]:
    if not path.is_file():
        raise FileNotFoundError(path)

if sha256(source_archive) != (
    "48a507d44986adf54a401e58f4ad8be87"
    "bb4f4602621aa4da0d7a05af85f3ac6"
):
    raise RuntimeError("Source archive hash mismatch.")

vocoder_hash = (
    "771eaf4876485a35e25577563d390c262"
    "e23c2421e4a8c929eacfde34a5b7a60"
)
if sha256(vocoder) != vocoder_hash:
    raise RuntimeError("Vocoder hash mismatch.")

if not repo.exists():
    print("Restoring isolated English repository...", flush=True)
    with tempfile.TemporaryDirectory(dir="/content") as temporary:
        temporary = Path(temporary)
        with tarfile.open(source_archive, "r:gz") as archive:
            archive.extractall(temporary, filter="data")
        extracted = temporary / "FastSpeech2"

        for relative, saved in patches.items():
            target = extracted / relative
            if not target.is_file():
                raise FileNotFoundError(target)
            shutil.copy2(saved, target)
            compile(target.read_text(encoding="utf-8"), str(target), "exec")

        shutil.copy2(
            vocoder, extracted / "hifigan/generator_universal.pth.tar"
        )
        shutil.move(str(extracted), str(repo))

for relative, saved in patches.items():
    if sha256(repo / relative) != sha256(saved):
        raise RuntimeError(f"Local patch differs: {relative}")
if sha256(repo / "hifigan/generator_universal.pth.tar") != vocoder_hash:
    raise RuntimeError("Local vocoder differs.")

metadata_dir.mkdir(parents=True, exist_ok=True)
with tarfile.open(data_archive, "r:gz") as archive:
    members = archive.getmembers()
    for name in ("stats.json", "speakers.json"):
        matches = [
            member for member in members
            if member.isfile() and Path(member.name).name == name
        ]
        if len(matches) != 1:
            raise RuntimeError(f"Expected one archived {name}.")
        stream = archive.extractfile(matches[0])
        if stream is None:
            raise RuntimeError(f"Cannot read {name}.")
        content = stream.read()
        destination = metadata_dir / name
        if destination.exists() and destination.read_bytes() != content:
            raise RuntimeError(f"Different existing metadata: {name}")
        destination.write_bytes(content)
        print("Original English inference metadata verified:", name)

print("\nEnglish repository patches and vocoder: VERIFIED")
print("Original normalization metadata restored.")
print("Repair experiment and Telugu files unchanged.")
print("No audio generated or training performed.")

from pathlib import Path
import difflib
import json
import os
import subprocess
import sys

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
repo = Path("/content/FastSpeech2_reference")

speakers = json.loads(
    Path("/content/fastspeech2_features/english_processed/speakers.json")
    .read_text(encoding="utf-8")
)
groups = [name for name, speaker_id in speakers.items() if speaker_id == 86]
if len(groups) != 1:
    raise RuntimeError("Could not uniquely resolve conditioning group 86.")
group = groups[0]

source_path = root / "Telugu/inference.py"
destination = root / "English/inference.py"
original = source_path.read_text(encoding="utf-8")
source = original.replace("Telugu", "English").replace(
    "/content/FastSpeech2_telugu", "/content/FastSpeech2_reference"
)

replacements = [
    (
        'default=["T1", "T2a", "T2b", "T3", "T4"]',
        'default=["E1", "E2a", "E2b", "E3", "E4"]',
    ),
    (
        'default="telugu_female"',
        f"default={group!r}",
    ),
    (
        'phones = entry["model_phones"]',
        'phones = entry["phones"]',
    ),
]
for old, new in replacements:
    if source.count(old) != 1:
        raise RuntimeError(
            f"Unexpected source script. Expected exactly one: {old}"
        )
    source = source.replace(old, new, 1)

compile(source, str(destination), "exec")
if destination.exists() and destination.read_text(encoding="utf-8") != source:
    raise RuntimeError("Different English inference.py exists. No overwrite made.")
destination.write_text(source, encoding="utf-8")

patch = "".join(difflib.unified_diff(
    original.splitlines(keepends=True),
    source.splitlines(keepends=True),
    fromfile="Telugu/inference.py",
    tofile="English/inference.py",
))
(root / "reproducibility/english_inference_adaptation.patch").write_text(
    patch, encoding="utf-8"
)
print("Saved reusable script:", destination)
print("Fixed conditioning group:", group, "| ID: 86")

