from pathlib import Path
from datetime import datetime, timezone
import zipfile

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
files = {}

for language in ("English", "Telugu"):
    folder = root / language

    candidates = [
        folder / "config.yaml",
        *(
            folder / "manifests" / name
            for name in (
                "test_sentences_confirmed.json",
                "test_sentences_prepared.json",
                "test_sentences_tokenized.json",
            )
        ),
        folder / "lexicon/phone_mapping.json",
        folder / "lexicon/model_symbols.json",
    ]

    for path in candidates:
        if path.is_file():
            files[str(path.relative_to(root))] = path

    data = (
        Path("/content/fastspeech2_features")
        / f"{language.lower()}_processed"
    )
    for name in ("stats.json", "speakers.json"):
        path = data / name
        if path.is_file():
            files[f"{language}/inference_metadata/{name}"] = path
        else:
            print("MISSING:", path)

