from pathlib import Path
import hashlib
import json
import numpy as np
import soundfile as sf

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")

def require(path):
    if not path.is_file() or path.stat().st_size == 0:
        raise FileNotFoundError(f"Missing or empty: {path}")

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

for name in (
    "Technical_Report.pdf", "README.md",
    "requirements.txt", "requirements-preprocessing.txt",
):
    require(root / name)
print("[PASS] Documentation")

selection_path = root / "reproducibility/selected_checkpoints.json"
require(selection_path)
selected = json.loads(selection_path.read_text(encoding="utf-8"))

groups = {
    "English": ["E1", "E2a", "E2b", "E3", "E4"],
    "Telugu": ["T1", "T2a", "T2b", "T3", "T4"],
}

for language, ids in groups.items():
    for name in ("train.py", "inference.py", "preprocess.py", "normalize.py"):
        require(root / language / name)
    for name in ("preprocess.yaml", "model.yaml", "train.yaml"):
        require(root / language / "config" / name)

    step = selected[language]["step"]
    checkpoint = root / language / "checkpoints" / f"{step}.pth.tar"
    require(checkpoint)

    print(f"Checking {language} checkpoint {step}...", flush=True)
    if sha256(checkpoint) != selected[language]["checkpoint_sha256"]:
        raise RuntimeError(f"{language}: checkpoint hash mismatch")
    print(f"[PASS] {language} checkpoint hash")

    results = root / "Results" / language
    for name in ("loss_history.csv", "training_loss.png", "validation_loss.png"):
        require(results / name)

    for sentence_id in ids:
        folder = results / "variance_adaptor_predictions"
        record_path = folder / f"{sentence_id}.json"
        array_path = folder / f"{sentence_id}.npz"
        wav_path = results / "test_generated_audios" / f"{sentence_id}.wav"

        for path in (record_path, array_path, wav_path):
            require(path)

        record = json.loads(record_path.read_text(encoding="utf-8"))
        if (
            record["checkpoint_step"] != step
            or record["checkpoint_sha256"]
            != selected[language]["checkpoint_sha256"]
        ):
            raise RuntimeError(f"{sentence_id}: wrong checkpoint record")

        with np.load(array_path, allow_pickle=False) as arrays:
            phones = record.get("model_phones", record.get("phones"))
            for name in (
                "duration_frames", "duration_seconds",
                "pitch_hz", "energy_raw",
            ):
                values = arrays[name]
                if values.shape != (len(phones),) or not np.isfinite(values).all():
                    raise RuntimeError(f"{sentence_id}: invalid {name}")

            duration = arrays["duration_frames"]
            if (duration < 0).any() or not np.all(duration == np.round(duration)):
                raise RuntimeError(f"{sentence_id}: invalid durations")

            frames = int(duration.sum())
            if frames != record["predicted_mel_frames"]:
                raise RuntimeError(f"{sentence_id}: mel length mismatch")

        audio = sf.info(wav_path)
        if (
            audio.samplerate != 22050
            or audio.channels != 1
            or audio.subtype != "PCM_16"
            or audio.frames != frames * record["hop_length"]
        ):
            raise RuntimeError(f"{sentence_id}: WAV format/length mismatch")

        for feature in ("duration", "pitch", "energy"):
            require(
                results / "variance_adaptor_plots"
                / feature / f"{sentence_id}.png"
            )

        print(f"[PASS] {sentence_id}: WAV, arrays, checkpoint record, 3 plots")

print("\nFINAL FILE AUDIT: PASSED")
print("10 WAVs and 30 plots verified.")
print("Public download permissions and clean-runtime reproduction remain pending.")
print("No files changed. No training performed.")

from pathlib import Path
from datetime import datetime, timezone
import shutil

root = Path("/content/drive/MyDrive/FastSpeech2_Assignment/project")
readme = root / "README.md"

if not readme.is_file():
    raise FileNotFoundError(readme)

folder_url = (
    "https://drive.google.com/drive/folders/"
    "1jEcF1coy7FWSD_81xOOIyWJd6DDax3jY"
)

text = readme.read_text(encoding="utf-8")
start = "<!-- MODEL_DOWNLOADS_START -->"
end = "<!-- MODEL_DOWNLOADS_END -->"

section = f"""
{start}
## Model downloads

[Download the selected models and vocoder]({folder_url})

The project owner confirmed that this folder opens without login.

| Resource | Downloaded file must be placed at |
|---|---|
| English checkpoint, step 12000 | `English/checkpoints/12000.pth.tar` |
| Telugu checkpoint, step 8000 | `Telugu/checkpoints/8000.pth.tar` |
| Universal HiFi-GAN generator | `<reference_repo>/hifigan/generator_universal.pth.tar` |

If Drive copies have a `Copy of` prefix, rename the downloaded files
to the destination names above. Keep original training files unchanged.

Verify acoustic-model SHA-256 hashes against
`reproducibility/selected_checkpoints.json`.

Expected vocoder SHA-256:
`771eaf4876485a35e25577563d390c262e23c2421e4a8c929eacfde34a5b7a60`

Use the matching HiFi-GAN configuration and the supplied language-specific
normalization metadata. These model downloads do not include datasets.
{end}
"""

if start in text or end in text:
    if text.count(start) != 1 or text.count(end) != 1:
        raise RuntimeError("Ambiguous download section; README unchanged.")
    before, remainder = text.split(start, 1)
    _, after = remainder.split(end, 1)
    updated = before.rstrip() + "\n\n" + section.strip() + after
else:
    updated = text.rstrip() + "\n\n" + section.strip() + "\n"

updated = updated.replace(
    "Public download links for these resources have not been supplied.",
    "The shared model-download folder is listed in the Model downloads section."
)

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
backup = root / "reproducibility" / f"README_before_model_links_{stamp}.md"
backup.parent.mkdir(parents=True, exist_ok=True)
shutil.copy2(readme, backup)
readme.write_text(updated, encoding="utf-8")

print("[PASS] Model-download folder link added")
print("README backup:", backup)
print("Models, audio and configurations unchanged.")
print("No training performed.")

from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import shutil
import tarfile
import zipfile

base = Path("/content/drive/MyDrive/FastSpeech2_Assignment")
root = base / "project"
stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
stage = base / "submission_packages" / f"FastSpeech2_submission_{stamp}"

source_archive = (
    root / "reproducibility"
    / "FastSpeech2_upstream_d4e79eb52e8b.tar.gz"
)

def require(path):
    if not path.is_file() or path.stat().st_size == 0:
        raise FileNotFoundError(path)

def copy_file(source, relative):
    require(source)
    target = stage / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)

require(source_archive)

print("Checking saved upstream archive...", flush=True)
digest = hashlib.sha256()
with source_archive.open("rb") as file:
    for chunk in iter(lambda: file.read(4 * 1024 * 1024), b""):
        digest.update(chunk)

expected = "48a507d44986adf54a401e58f4ad8be87bb4f4602621aa4da0d7a05af85f3ac6"
if digest.hexdigest() != expected:
    raise RuntimeError("Upstream archive hash mismatch.")

stage.mkdir(parents=True, exist_ok=False)

for name in (
    "README.md", "Technical_Report.pdf",
    "requirements.txt", "requirements-preprocessing.txt",
):
    copy_file(root / name, name)

groups = {
    "English": ["E1", "E2a", "E2b", "E3", "E4"],
    "Telugu": ["T1", "T2a", "T2b", "T3", "T4"],
}

for language, ids in groups.items():
    folder = root / language

    for source in folder.glob("*.py"):
        copy_file(source, source.relative_to(root))

    copy_file(folder / "config.yaml", f"{language}/config.yaml")

    for source in (folder / "config").rglob("*.yaml"):
        copy_file(source, source.relative_to(root))

    for source in (folder / "upstream_modified").rglob("*.py"):
        copy_file(source, source.relative_to(root))

    for name in (
        "test_sentences_confirmed.json",
        "test_sentences_prepared.json",
        "test_sentences_tokenized.json",
    ):
        source = folder / "manifests" / name
        if source.is_file():
            copy_file(source, source.relative_to(root))

    for name in ("phone_mapping.json", "model_symbols.json"):
        source = folder / "lexicon" / name
        if source.is_file():
            copy_file(source, source.relative_to(root))

    if language == "English":
        copy_file(
            folder / "lexicon/english_synthesis.dict",
            "English/lexicon/english_synthesis.dict",
        )

    # Recover only the two inference metadata files.
    processed_archive = (
        base / "processed_data" / language
        / f"{language.lower()}_processed.tar.gz"
    )
    require(processed_archive)

    with tarfile.open(processed_archive, "r:gz") as archive:
        for name in ("stats.json", "speakers.json"):
            matches = [
                member for member in archive.getmembers()
                if member.isfile() and Path(member.name).name == name
            ]
            if len(matches) != 1:
                raise RuntimeError(f"{language}: ambiguous/missing {name}")
            target = stage / language / "inference_metadata" / name
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.extractfile(matches[0]) as source:
                target.write_bytes(source.read())

    results = root / "Results" / language
    for name in (
        "loss_history.csv", "training_loss.png",
        "validation_loss.png", "variance_plot_summary.json",
    ):
        copy_file(results / name, f"Results/{language}/{name}")

    for sentence_id in ids:
        relatives = [
            f"test_generated_audios/{sentence_id}.wav",
            f"variance_adaptor_predictions/{sentence_id}.json",
            f"variance_adaptor_predictions/{sentence_id}.npz",
            *[
                f"variance_adaptor_plots/{feature}/{sentence_id}.png"
                for feature in ("duration", "pitch", "energy")
            ],
        ]
        for relative in relatives:
            copy_file(
                results / relative,
                f"Results/{language}/{relative}",
            )

for folder in ("upstream_modified", "tools"):
    for source in (root / folder).rglob("*.py"):
        copy_file(source, source.relative_to(root))

for name in (
    "selected_checkpoints.json",
    "english_training_normalization_statistics.json",
    "telugu_training_normalization_statistics.json",
    "english_normalization_run.json",
    "telugu_normalization_run.json",
):
    copy_file(root / "reproducibility" / name, f"reproducibility/{name}")

# Include source/configuration/license files, not archived weights.
with tarfile.open(source_archive, "r:gz") as archive:
    for member in archive.getmembers():
        parts = Path(member.name).parts
        if not member.isfile() or not parts or parts[0] != "FastSpeech2":
            continue
        if ".." in parts or Path(member.name).is_absolute():
            raise RuntimeError("Unsafe archive path.")

        name = Path(member.name).name
        suffix = Path(name).suffix.lower()
        if suffix not in {".py", ".json", ".yaml", ".yml", ".md"} \
                and not name.lower().startswith(("license", "notice")) \
                and name != "requirements.txt":
            continue

        target = stage / "reference_source" / member.name
        target.parent.mkdir(parents=True, exist_ok=True)
        with archive.extractfile(member) as source:
            target.write_bytes(source.read())

# Matching vocoder configuration; generator remains an external download.
copy_file(
    base / "vocoder/UNIVERSAL_V1/config.json",
    "vocoder/UNIVERSAL_V1/config.json",
)

readme = stage / "README.md"
text = readme.read_text(encoding="utf-8")
text = (
    "# Submission staging copy\n\n"
    "This copy includes the ten generated WAVs and reviewed upstream source. "
    "Model and vocoder weights are external downloads linked below. "
    "Clean-runtime reproduction remains pending. "
    "Historical corpus-selection/export and statistics-fitting notebook "
    "cells are not yet packaged as standalone commands.\n\n"
    + text
)
text = text.replace(
    "It does not contain audio, acoustic-model weights, the upstream repository, "
    "dataset audio, alignment exports or the vocoder checkpoint.",
    "It includes generated assignment audio and reference source. "
    "It excludes acoustic-model weights, dataset audio, alignment exports "
    "and the vocoder checkpoint."
)
text = text.replace(
    "The ten final WAVs remain in the existing",
    "The ten final WAVs are included in the"
)
readme.write_text(text, encoding="utf-8")

wav_count = len(list(stage.glob("Results/*/test_generated_audios/*.wav")))
plot_count = len(list(stage.glob("Results/*/variance_adaptor_plots/*/*.png")))
if wav_count != 10 or plot_count != 30:
    raise RuntimeError(f"Unexpected counts: WAV={wav_count}, plots={plot_count}")

archive_path = stage.with_suffix(".zip")
with zipfile.ZipFile(archive_path, "x", zipfile.ZIP_DEFLATED) as archive:
    for path in sorted(stage.rglob("*")):
        if path.is_file():
            archive.write(path, path.relative_to(stage.parent))

with zipfile.ZipFile(archive_path) as archive:
    if archive.testzip() is not None:
        raise RuntimeError("ZIP integrity failed.")

print("\n[PASS] Submission staging copy")
print("WAVs:", wav_count, "| Variance plots:", plot_count)
print("Folder:", stage)
print("ZIP:", archive_path)
print("ZIP size MiB:", round(archive_path.stat().st_size / 1024**2, 2))
print("Clean-runtime reproduction: PENDING")
print("Original project unchanged. No training performed.")

from pathlib import Path
from datetime import datetime, timezone
import json
import os
import subprocess
import sys
import torch

stage = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/submission_packages/"
    "FastSpeech2_submission_20261102T185418336395Z"
)
if not (stage / "requirements.txt").is_file():
    raise FileNotFoundError("Staging requirements.txt नहीं मिला।")
if not torch.cuda.is_available():
    raise RuntimeError("GPU unavailable; setup अभी शुरू नहीं किया गया।")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
work = Path("/content") / f"fastspeech2_clean_repro_{stamp}"
work.mkdir(exist_ok=False)

records = stage / "reproducibility"
records.mkdir(exist_ok=True)
log_path = records / f"clean_environment_setup_{stamp}.log"

environment = os.environ.copy()
environment.pop("PYTHONPATH", None)
environment.pop("PYTHONHOME", None)

def run(command, label, env=None):
    print(label, flush=True)
    with log_path.open("a", encoding="utf-8") as log:
        result = subprocess.run(
            command,
            env=env if env is not None else environment,
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )
    if result.returncode:
        print("\n".join(
            log_path.read_text(encoding="utf-8", errors="replace")
            .splitlines()[-45:]
        ))
        raise RuntimeError(f"{label} failed. Full log: {log_path}")

# Install the environment-creation tool into a temporary folder only.
bootstrap = work / "bootstrap"
run(
    [
        sys.executable, "-m", "pip", "install",
        "--target", str(bootstrap), "virtualenv",
    ],
    "1/4: Preparing isolated environment tool...",
)

bootstrap_env = environment.copy()
bootstrap_env["PYTHONPATH"] = str(bootstrap)
venv = work / "venv"
run(
    [
        sys.executable, "-m", "virtualenv",
        "--no-download", str(venv),
    ],
    "2/4: Creating fresh Python environment...",
    bootstrap_env,
)
python = venv / "bin/python"

# Match the CUDA PyTorch build already working in this Colab runtime.
torch_version = torch.__version__
cuda_tag = "cu" + torch.version.cuda.replace(".", "")
run(
    [
        str(python), "-m", "pip", "install",
        f"torch=={torch_version}",
        "--index-url", f"https://download.pytorch.org/whl/{cuda_tag}",
    ],
    "3/4: Installing matching CUDA PyTorch...",
)
run(
    [
        str(python), "-m", "pip", "install",
        "-r", str(stage / "requirements.txt"),
    ],
    "4/4: Installing recorded runtime dependencies...",
)

check = subprocess.run(
    [
        str(python), "-c",
        """
import json, torch
if not torch.cuda.is_available():
    raise RuntimeError("CUDA unavailable in isolated environment")
x = torch.ones((16, 16), device="cuda")
assert (x @ x).sum().item() == 4096
print(json.dumps({
    "torch": torch.__version__,
    "cuda_build": torch.version.cuda,
    "gpu": torch.cuda.get_device_name(0),
    "gpu_computation": "PASSED"
}))
"""
    ],
    env=environment,
    capture_output=True,
    text=True,
)
if check.returncode:
    print(check.stdout, check.stderr)
    raise RuntimeError("Isolated GPU check failed.")

gpu_check = json.loads(check.stdout.strip())
report = {
    "stage": str(stage),
    "work_directory": str(work),
    "python": str(python),
    "system_site_packages": False,
    "gpu_check": gpu_check,
    "setup_log": str(log_path),
    "model_inference_tested": False,
    "status": "ENVIRONMENT_SETUP_PASSED",
}
report_path = records / "clean_environment_setup.json"
report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")

print(json.dumps(report, indent=2))
print("Original project and current Python environment unchanged.")
print("No training performed.")

