records = stage / "reproducibility"
setup = json.loads(
    (records / "clean_environment_setup.json").read_text(encoding="utf-8")
)
python = Path(setup["python"])
work = Path(setup["work_directory"])

if not python.is_file():
    raise FileNotFoundError("Isolated environment नहीं मिला।")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
downloads = work / f"public_models_{stamp}"
downloads.mkdir(exist_ok=False)
log_path = records / f"public_model_download_{stamp}.log"

environment = os.environ.copy()
environment.pop("PYTHONPATH", None)
environment.pop("PYTHONHOME", None)


def run(command, label):
    print(label, flush=True)
    with log_path.open("a", encoding="utf-8") as log:
        result = subprocess.run(
            command,
            env=environment,
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )
    if result.returncode:
        print("\n".join(
            log_path.read_text(encoding="utf-8", errors="replace")
            .splitlines()[-40:]
        ))
        raise RuntimeError(f"{label} failed. Log: {log_path}")

run(
    [str(python), "-m", "pip", "install", "gdown==5.2.2"],
    "Installing download tool in isolated environment...",
)

download_code = """
import gdown
import sys

paths = gdown.download_folder(
    url=sys.argv[1],
    output=sys.argv[2],
    quiet=False,
    use_cookies=False,
)
if not paths:
    raise RuntimeError("No files downloaded from public folder.")
print("Downloaded files:", len(paths))
"""

run(
    [
        str(python), "-c", download_code,
        "https://drive.google.com/drive/folders/"
        "1jEcF1coy7FWSD_81xOOIyWJd6DDax3jY",
        str(downloads),
    ],
    "Downloading public model copies without login...",
)

selected = json.loads(
    (records / "selected_checkpoints.json").read_text(encoding="utf-8")
)
expected = {
    "English": selected["English"]["checkpoint_sha256"],
    "Telugu": selected["Telugu"]["checkpoint_sha256"],
    "vocoder": (
        "771eaf4876485a35e25577563d390c262e23"
        "c2421e4a8c929eacfde34a5b7a60"
    ),
}

verified = {}
for path in sorted(downloads.rglob("*")):
    if not path.is_file():
        continue

    print("Hashing:", path.name, flush=True)
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    value = digest.hexdigest()

    for role, wanted in expected.items():
        if value == wanted:
            if role in verified:
                raise RuntimeError(f"Duplicate matching file: {role}")
            verified[role] = {
                "path": str(path),
                "sha256": value,
                "bytes": path.stat().st_size,
            }
            print("[PASS]", role)

missing = sorted(set(expected) - set(verified))
if missing:
    raise RuntimeError(f"Missing or incorrect model copies: {missing}")

report = {
    "anonymous_public_download": "PASSED",
    "hash_verification": "PASSED",
    "files": verified,
    "log": str(log_path),
    "model_inference_tested": False,
}
report_path = records / "clean_model_downloads.json"
report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")

print("\nPUBLIC DOWNLOAD AND HASH CHECK: PASSED")
print("Verified:", ", ".join(verified))
print("Report:", report_path)
print("Original checkpoints unchanged. No training performed.")

from pathlib import Path
from datetime import datetime, timezone
import json
import os
import shutil
import subprocess
import numpy as np
import soundfile as sf
import yaml

stage = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/submission_packages/"
    "FastSpeech2_submission_20261102T185418336395Z"
)
records = stage / "reproducibility"

setup = json.loads(
    (records / "clean_environment_setup.json").read_text(encoding="utf-8")
)
downloads = json.loads(
    (records / "clean_model_downloads.json").read_text(encoding="utf-8")
)
selection = json.loads(
    (records / "selected_checkpoints.json").read_text(encoding="utf-8")
)

python = Path(setup["python"])
source = stage / "reference_source/FastSpeech2"

if not python.is_file() or not (source / "train.py").is_file():
    raise FileNotFoundError("Clean environment or packaged source missing.")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
run_root = Path(setup["work_directory"]) / f"inference_{stamp}"
project = run_root / "project"
project.mkdir(parents=True, exist_ok=False)

environment = os.environ.copy()
environment.pop("PYTHONPATH", None)
environment.pop("PYTHONHOME", None)
environment["PYTHONUNBUFFERED"] = "1"
environment["MPLBACKEND"] = "Agg"

groups = {
    "English": ["E1", "E2a", "E2b", "E3", "E4"],
    "Telugu": ["T1", "T2a", "T2b", "T3", "T4"],
}
repositories = {}

def copy_file(source_path, destination):
    if not source_path.is_file():
        raise FileNotFoundError(source_path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source_path, destination)

# Prepare independent repositories and inference inputs.
for language in groups:
    print("Preparing isolated source:", language, flush=True)
    repo = run_root / "repositories" / language
    shutil.copytree(source, repo)

    for patches in (
        stage / "upstream_modified",
        stage / language / "upstream_modified",
    ):
        if not patches.is_dir():
            raise FileNotFoundError(patches)
        for patch in patches.rglob("*.py"):
            copy_file(patch, repo / patch.relative_to(patches))

    copy_file(
        Path(downloads["files"]["vocoder"]["path"]),
        repo / "hifigan/generator_universal.pth.tar",
    )
    copy_file(
        stage / "vocoder/UNIVERSAL_V1/config.json",
        repo / "hifigan/config.json",
    )

    language_root = project / language
    copy_file(
        stage / language / "inference.py",
        language_root / "inference.py",
    )
    copy_file(
        stage / language / "manifests/test_sentences_tokenized.json",
        language_root / "manifests/test_sentences_tokenized.json",
    )

    data = run_root / "metadata" / language
    for name in ("stats.json", "speakers.json"):
        copy_file(
            stage / language / "inference_metadata" / name,
            data / name,
        )

    checkpoint = (
        language_root / "checkpoints"
        / f"{selection[language]['step']}.pth.tar"
    )
    copy_file(Path(downloads["files"][language]["path"]), checkpoint)
    selection[language]["checkpoint"] = str(checkpoint)

    for name in ("preprocess.yaml", "model.yaml", "train.yaml"):
        config = yaml.safe_load(
            (stage / language / "config" / name)
            .read_text(encoding="utf-8")
        )

        if name == "preprocess.yaml":
            config["path"]["preprocessed_path"] = str(data)
        elif name == "train.yaml":
            config["path"]["ckpt_path"] = str(checkpoint.parent)
            config["path"]["log_path"] = str(language_root / "logs")
            config["path"]["result_path"] = str(
                project / "Results" / language
            )

        destination = language_root / "config" / name
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(
            yaml.safe_dump(config, sort_keys=False),
            encoding="utf-8",
        )

    repositories[language] = repo

selected_path = project / "reproducibility/selected_checkpoints.json"
selected_path.parent.mkdir(parents=True, exist_ok=True)
selected_path.write_text(json.dumps(selection, indent=2), encoding="utf-8")

summary = {}

for language, ids in groups.items():
    log_path = records / f"clean_inference_{language.lower()}_{stamp}.log"
    command = [
        str(python), "-u",
        str(project / language / "inference.py"),
        "--repo", str(repositories[language]),
        "--device", "cuda",
        "--ids", *ids,
    ]

    print("Running clean-environment inference:", language, flush=True)
    with log_path.open("x", encoding="utf-8") as log:
        result = subprocess.run(
            command,
            cwd=repositories[language],  # Vocoder relative paths.
            env=environment,
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )

    if result.returncode:
        print("\n".join(
            log_path.read_text(encoding="utf-8", errors="replace")
            .splitlines()[-50:]
        ))
        raise RuntimeError(f"{language} inference failed. Log: {log_path}")

    results = project / "Results" / language
    for sentence_id in ids:
        folder = results / "variance_adaptor_predictions"
        record = json.loads(
            (folder / f"{sentence_id}.json").read_text(encoding="utf-8")
        )

        if record["checkpoint_sha256"] != selection[language]["checkpoint_sha256"]:
            raise RuntimeError(f"{sentence_id}: checkpoint mismatch")

        with np.load(folder / f"{sentence_id}.npz", allow_pickle=False) as arrays:
            if not all(np.isfinite(arrays[name]).all() for name in arrays.files):
                raise RuntimeError(f"{sentence_id}: non-finite prediction")
            duration = arrays["duration_frames"]
            if (duration < 0).any() or not np.all(duration == np.round(duration)):
                raise RuntimeError(f"{sentence_id}: invalid durations")
            frames = int(duration.sum())

        audio = sf.info(
            results / "test_generated_audios" / f"{sentence_id}.wav"
        )
        if (
            frames != record["predicted_mel_frames"]
            or audio.frames != frames * record["hop_length"]
            or audio.samplerate != 22050
            or audio.channels != 1
            or audio.subtype != "PCM_16"
        ):
            raise RuntimeError(f"{sentence_id}: output inconsistency")

        print("[PASS]", sentence_id, flush=True)

    summary[language] = {
        "checkpoint_step": selection[language]["step"],
        "generated_sentences": len(ids),
        "log": str(log_path),
        "status": "PASSED",
    }

report = {
    "isolated_environment": True,
    "weights_source": "Anonymous public downloads; SHA-256 verified",
    "packaged_source_used": True,
    "original_results_overwritten": False,
    "training_performed": False,
    "new_audio_listening_reviewed": False,
    "results_directory": str(project / "Results"),
    "languages": summary,
    "status": "CLEAN_INFERENCE_PASSED",
}
report_path = records / "clean_inference_verification.json"
report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")

print("\n" + json.dumps(report, indent=2))
print("Original project unchanged. No training performed.")

from pathlib import Path
from datetime import datetime, timezone
import json
import os
import shutil
import subprocess
import zipfile

stage = Path(
    "/content/drive/MyDrive/FastSpeech2_Assignment/submission_packages/"
    "FastSpeech2_submission_20261102T185418336395Z"
)
records = stage / "reproducibility"

report = json.loads(
    (records / "clean_inference_verification.json")
    .read_text(encoding="utf-8")
)
setup = json.loads(
    (records / "clean_environment_setup.json")
    .read_text(encoding="utf-8")
)
downloads = json.loads(
    (records / "clean_model_downloads.json")
    .read_text(encoding="utf-8")
)

if report["status"] != "CLEAN_INFERENCE_PASSED":
    raise RuntimeError("Clean inference verification has not passed.")
if downloads["hash_verification"] != "PASSED":
    raise RuntimeError("Downloaded model hashes are not verified.")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")

# Record exact packages from the successful isolated environment.
environment = os.environ.copy()
environment.pop("PYTHONPATH", None)
environment.pop("PYTHONHOME", None)
environment["MPLBACKEND"] = "Agg"

freeze = subprocess.run(
    [setup["python"], "-m", "pip", "freeze"],
    env=environment,
    capture_output=True,
    text=True,
    check=True,
)
(stage / "requirements-clean-inference.lock.txt").write_text(
    freeze.stdout, encoding="utf-8"
)

addendum = """# Clean inference verification

- Fresh Python environment: system_site_packages=False.
- GPU: Tesla T4; PyTorch 2.11.0+cu130.
- Public model downloads: anonymous download passed.
- English checkpoint 12000 and Telugu checkpoint 8000: hashes verified.
- Universal vocoder: hash verified.
- Packaged reference source and compatibility patches used.
- All five English and five Telugu inference runs passed.
- WAV format, duration consistency and finite arrays checked.
- Original results were preserved; no training was performed.
- Newly reproduced audio has not received a separate listening review.

## Required execution setting

Set `MPLBACKEND=Agg` before starting the inference subprocess.
Colab's inherited notebook backend is unavailable in the isolated environment.

## Interpretation

This verifies inference reproduction for the ten frozen assignment inputs.
It does not establish bitwise identical output, general pronunciation accuracy,
or full raw-data-to-training reproduction.

Technical_Report.pdf is the earlier review snapshot. This addendum records
the subsequent successful clean inference test.

See clean_inference_verification.json and clean_model_downloads.json for
the recorded results. Exact installed versions are in
requirements-clean-inference.lock.txt.
"""
(records / "CLEAN_REPRODUCTION.md").write_text(
    addendum, encoding="utf-8"
)

readme = stage / "README.md"
text = readme.read_text(encoding="utf-8")
backup = records / f"README_before_clean_verification_{stamp}.md"
shutil.copy2(readme, backup)

text = text.replace(
    "Clean-runtime reproduction remains pending.",
    "Clean-environment inference passed for all ten frozen assignment inputs. "
    "See reproducibility/CLEAN_REPRODUCTION.md."
)
text = text.replace(
    "A clean installation was not tested in this review.",
    "Subsequent clean-environment installation and ten-sentence inference "
    "passed; see reproducibility/CLEAN_REPRODUCTION.md."
)

marker = "<!-- CLEAN_INFERENCE_VERIFIED -->"
if marker not in text:
    text += f"""
\n{marker}
## Verified clean inference

Public downloads and SHA-256 checks passed. Both selected models generated
all ten assignment sentences using packaged source in a fresh Python
environment.

Use `MPLBACKEND=Agg` when launching inference.

See [verification addendum](reproducibility/CLEAN_REPRODUCTION.md)
and [exact environment lock](requirements-clean-inference.lock.txt).
Earlier pending-status statements describe the pre-verification snapshot.
Full historical raw-data preprocessing reproduction remains a separate scope.
"""

readme.write_text(text, encoding="utf-8")

output = stage.parent / f"FastSpeech2_submission_verified_{stamp}.zip"
with zipfile.ZipFile(output, "x", zipfile.ZIP_DEFLATED) as archive:
    for path in sorted(stage.rglob("*")):
        if path.is_file() and not path.name.startswith("README_before_"):
            archive.write(path, path.relative_to(stage.parent))

with zipfile.ZipFile(output) as archive:
    if archive.testzip() is not None:
        raise RuntimeError("ZIP integrity failed.")

print("[PASS] Clean verification addendum saved")
print("[PASS] Exact environment lock saved")
print("[PASS] Staging README updated")
print("[PASS] Updated ZIP integrity")
print("ZIP:", output)
print("Size MiB:", round(output.stat().st_size / 1024**2, 2))
print("Original project unchanged. No training performed.")

